UPDATE `courses` SET `apply_form` = 'https://www.federation.edu.au/courses/dgc4-graduate-certificate-in-social-and-community-services/', `course_description` = '<h4>Course Information</h4> <p>The Graduate Certificate in Social and Community Services is designed for community and human services professionals looking to advance their careers or those seeking a new career in this growing sector. Many social problems, including poverty, conflict, family violence, growing social and economic disparities in health, education and mental health, are challenges confronting the welfare sector in Australia and around the globe. You will learn theories and practice frameworks that underpin community service work and develop skills to undertake complex case work, group work and social advocacy.</p> <h5>Course Structure</h5> <p>60 credit points over 6 months.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Entry requirements (year 12) N/A Entry requirements (non year 12) Completed a Bachelors Degree AQF Level 7 in any discipline OR Completed a Diploma VET/TAFE or Associate Degree qualification in a related discipline AND a minimum of three years full-time professional experience in the related community and human service fields, such as disability studies, community development, youth work, child protection, family violence, homelessness, housing, humanitarian organisations.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `total_course_duration` = '6 months full-time (26 weeks)', `intakes` = 'March 01 2027; March 01 2027, July 26 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 293;
