UPDATE `courses` SET `apply_form` = 'https://www.federation.edu.au/courses/dho9-master-of-health-research/', `course_description` = '<h4>Course Information</h4> <p>This course is designed for students undertaking allied health programs including occupational therapy, physiotherapy and speech pathology, who wish to proceed with a full research training degree at masters level.</p> <h5>Course Structure</h5> <p>180 Credit Points</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Entry requirements (year 12) Entry requirements (non year 12) An applicant must have successfully completed a three-year (minimum) Bachelor level qualification in a related health cognate discipline area. Applicants who are applying for entry without honours qualifications will be required to demonstrate evidence on research knowledge and experience. This is referred to as Honours equivalence.</li></ul>', `total_course_duration` = '1.5 years full-time (78 weeks)', `intakes` = 'Anytime during the year', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 402;
