UPDATE `courses` SET `apply_form` = 'https://www.federation.edu.au/courses/dmd0-doctor-of-philosophy/', `course_description` = '<h4>Course Information</h4> <p>The Doctor of Philosophy sees candidates working with a Principal Supervisor, appointed by the Research Higher Degrees Sub Committee, with the approval of the Institute.</p> <h5>Course Structure</h5> <p>360 Credit Points</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>To be eligible for admission as a Candidate for the degree of Doctor of Philosophy a person must:have graduated with or qualified for a Masters degree that included a dissertation demonstrating the ability to undertake research at PhD level; have graduated with or qualified for a four year Honours Bachelor degree, or Degree with Honours at first class or second class, upper division, honours, that included a dissertation demonstrating the ability to undertake research at PhD level; have been enrolled for a Masters degree by research and have completed research which is assessed by the academic Board as demonstrating the capacity to undertake research at PhD level; hold qualifications and/or have demonstrated skills, experience, research, or publications which are assessed by the Academic Board as being at least equivalent to or as a satisfactory substitute for any of the qualifications prescribed above.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `total_course_duration` = '3 years full-time (156 weeks)', `intakes` = 'January 01 2026, January 01 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 6123;
