UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Our Foundation Studies program is designed to strengthen your academic skills, enhance your English language proficiency, and bridge any gaps in your preparation for university study. It provides a direct pathway to more than 110 bachelor&#x27;s degrees at the University of Newcastle, Australia. Successful applicants will receive a packaged offer that includes both the Foundation Studies program and the chosen bachelor&#x27;s degree in the same offer.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Completion of Year 1; or Middle Years Programme (MYP) with 28 points over 8 subjects; or O Levels with D grade average across 5 subjects</li></ul>', `total_course_duration` = '8 months full-time (34.666666666666664 weeks)', `assessment_style` = 'assignment', `intakes` = 'October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 818;
