UPDATE `courses` SET `apply_form` = 'https://www.jcu.edu.au/global-experience/inbound-programs/study-abroad', `course_description` = '<h4>Course Information</h4> <p>Embark on the adventure of a lifetime. Enjoy the freedom to choose what and when youd like to study at JCU. We welcome hundreds of undergraduate and postgraduate students each year from universities across our Study Abroad network and the world. You will pay tuition fees directly to JCU while you are here and receive the same excellent services and study opportunities available to all JCU students.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Undergraduate entry requirements; You must have successfully completed 6 months of full-time study at a recognised higher education institution and received a minimum cumulative GPA of 4.0 out of 7.0, or minimum average results of a passing grade.; Postgraduate entry requirements; You must have successfully completed a Bachelors degree or equivalent from a recognised higher education institution. Postgraduate students applying for the Study Abroad program can study a maximum of one teaching period only.</li></ul>', `total_course_duration` = '13 weeks full-time', `assessment_style` = 'mixed', `intakes` = 'February; February, July; February, May, September; January; January, July; January, May; January, May, July, September, November; January, May, September; January, September; July; July, November; March, July, October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1214;
