UPDATE `courses` SET `apply_form` = 'https://www.jcu.edu.au/courses/doctor-of-philosophy?international=', `course_description` = '<h4>Course Information</h4> <p>Designed for high performing university graduates, the Doctor of Philosophy (PhD) is a postgraduate research degree with a supervised project of original research at its core. Develop high level independent research skills while making an original contribution of knowledge to a specific discipline or area of practice. As a JCU PhD candidate, you will have the opportunity to undertake focused research in the tropics. You will explore and generate new knowledge to meet the social, environmental and sustainability challenges facing tropical communities.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>AQF level 8 bachelor honours degree (1 or 2A) or postgraduate qualification, incl. one semester of supervised research with a distinction grade and one research methods subject; AQF level 9 research master with two thirds supervised research and a thesis.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 86</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 86</li></ul>', `total_course_duration` = '4 years online/off-campus (208 weeks), 4 years full-time (208 weeks)', `assessment_style` = 'assignment', `intakes` = 'March, July, October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1244;
UPDATE `courses` SET `apply_form` = 'https://www.jcu.edu.au/courses/doctor-of-philosophy?international=', `course_description` = '<h4>Course Information</h4> <p>Designed for high performing university graduates, the Doctor of Philosophy (PhD) is a postgraduate research degree with a supervised project of original research at its core. Develop high level independent research skills while making an original contribution of knowledge to a specific discipline or area of practice. As a JCU PhD candidate, you will have the opportunity to undertake focused research in the tropics. You will explore and generate new knowledge to meet the social, environmental and sustainability challenges facing tropical communities.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>AQF level 8 bachelor honours degree (1 or 2A) or postgraduate qualification, incl. one semester of supervised research with a distinction grade and one research methods subject; AQF level 9 research master with two thirds supervised research and a thesis.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 86</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 86</li></ul>', `total_course_duration` = '4 years online/off-campus (208 weeks), 4 years full-time (208 weeks)', `assessment_style` = 'assignment', `intakes` = 'February; February, July; February, May, September; January; January, July; January, May; January, May, July, September, November; January, May, September; January, September; July; July, November; March, July, October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1245;
