UPDATE `courses` SET `apply_form` = 'https://www.jcu.edu.au/courses/master-of-philosophy?international=', `course_description` = '<h4>Course Information</h4> <p>JCU Master of Philosophy graduates are internationally recognised as experts who discover valuable new knowledge in their fields. The skills you develop during your MPhil will enable you to extend yourself professionally within your existing sector, or to apply your research, critical thinking and problem-solving skills to new contexts. Graduates can also continue their independent research in a Doctor of Philosophy.</p> <h5>Course Structure</h5> <p>Research thesis relevant to field of study. Disiplines include: Public health and tropical medicine; Speech pathology; Sport and exercise science; Tropical health; Tropical medical science; others as negotiated with advisors. Disciplines are dependent on availability of appropriate advisors on each campus.</p> <h5>Study & Career Pathways</h5> <p>PhD</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>AQF level 7 bachelor degree with conditions</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 86</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 86</li></ul>', `total_course_duration` = '2 years online/off-campus (104 weeks), 2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'March, July, October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1254;
