UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/8520XMPHIL', `course_description` = '<h4>Course Information</h4> <p>The Australian National University provides our Master of Philosophy students with a vibrant research community and outstanding program support. When selecting a research program, an institutions reputation is everything. ANU is one of the worlds leading universities, and the smart choice for your research program.</p> <h5>Course Structure</h5> <p>96 Units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants must present at a minimum, an Australian Bachelor degree or equivalent, with an overall grade of distinction (or GPA 6/7) or higher, and the approval of an identified supervisor for the research project/thesis. Equivalence may be met by a combination of qualifications and professional experience.</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1380;
UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/8620XMPHIL', `course_description` = '<h4>Course Information</h4> <p>The Australian National University provides our Master of Philosophy students with a vibrant research community and outstanding program support. When selecting a research program, an institutions reputation is everything. ANU is one of the worlds leading universities, and the smart choice for your research program.</p> <h5>Course Structure</h5> <p>96 Units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants must:; 1. Present a relevant Bachelor Honours degree or international equivalent; With a minimum overall grade of Second Class Honours Upper (H2A); or an equivalent combination of qualifications, research publications and/or professional experience related to the field of study.; 2. Provide:; Original evidence of all relevant academic qualifications and graduation documentation (with English translation as appropriate); An up to date CV including academic qualifications, work experience and research publications; At least two professional or academic referee reports.</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1381;
