UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/9560XPHD', `course_description` = '<h4>Course Information</h4> <p>The Doctor of Philosophy in Regulation and Governance provides interdisciplinary training in the areas of regulation and governance, combining rigorous research with innovative forms of knowledge translation. The program is built on principles of justice, sustainability and human well being and delivered by the dynamic community of scholars at RegNet, one of the worlds most vibrant governance and regulatory academic centres.</p> <h5>Course Structure</h5> <p>The Doctor of Philosophy requires the submission and successful examination of a thesis of up to 100,000 words.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>To be eligible to pursue the PhD in Regulation and Governance, you must:; have an Australian university honours degree (at the level honours 2A or above) or; have equivalent prior studies in Australia or elsewhere (for example, a bachelors degree plus a graduate diploma or a masters degree) that includes research work or; have a bachelors degree and professional qualifications, work experience and/or published research that may be deemed equivalent to the Honours degree and; have met the minimum English language requirements for admission.</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'mixed', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1393;
