UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/HDEVS', `course_description` = '<h4>Course Information</h4> <p>The Bachelor of Development Studies (Honours) degree exemplifies the ANU commitment to research led education. Building on the Bachelor of Development Studies, it gives high level preparation for professional life or a higher degree by research through the development of an advanced knowledge of the research principles and methods and theoretical concepts of development studies, and through the design and implementation of a research project, typically a 20,000 word thesis, that leads to the development of new understandings or that provides solutions to complex problems.</p> <h5>Course Structure</h5> <p>The Bachelor of Development Studies (Honours) requires the completion of 48 units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>The Bachelor of Development Studies (Honours) requires the completion of 48 units</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1463;
