UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/MAHST', `course_description` = '<h4>Course Information</h4> <p>Where better to study art history and curatorship than surrounded by Australias national cultural and collecting institutions? Whats more, where better to study Art History than in Australias premier practice led research institution, the ANU School of Art and Design. Here, you will study the history of art while surrounded by the making of art.</p> <h5>Course Structure</h5> <p>The Master of Art History and Curatorial Studies requires completion of 48 units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A cognate Bachelor degree or international equivalent with a minimum GPA of 5/7; A Bachelor degree or international equivalent AND a Graduate Certificate or Graduate Diploma in a cognate discipline with a minimum GPA of 4/7</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1476;
