UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/MGAL', `course_description` = '<h4>Course Information</h4> <p>As language assumes ever greater importance in an interconnected, multilingual world, the study of linguistics and applied linguistics is relevant to a growing number of careers from language teaching to natural language processing. In the Master of General and Applied Linguistics, you will have the opportunity to explore diverse topics across general and applied linguistics areas including structural linguistics, sociolinguistics, language acquisition, language contact, language teaching, language and culture, social interaction, forensic linguistics and language documentation</p> <h5>Course Structure</h5> <p>The Masters of General and Applied Linguistics requires completion of 72 units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A Bachelor degree or international equivalent with a minimum GPA of 5/7.</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1498;
