UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/VGLOB', `course_description` = '<h4>Course Information</h4> <p>The program is designed to meet your professional needs, with problem based learning, research methods and tailored focus areas including business, security, development, environmental sustainability, culture, communications and regional implications.</p> <h5>Course Structure</h5> <p>The Master of Globalisation (Advanced) requires completion of 96 units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>By transfer from the Master of Globalisation with a minimum GPA of 6/7 as well as the approval of an identified supervisor for the research project/thesis.</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1500;
UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/MHIT', `course_description` = '<h4>Course Information</h4> <p>Studying history at ANU you can draw upon our prize winning teaching and research in Australian, North American, ancient, early modern and modern European, and British history, and the expertise of our leading centres for Indigenous history, environmental history, and biography.</p> <h5>Course Structure</h5> <p>The Master of History requires the completion of 48 units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A cognate Bachelor degree or international equivalent with a minimum GPA of 5/7A Bachelor degree or international equivalent AND a Graduate Certificate or Graduate Diploma in a cognate discipline with a minimum GPA of 4/7</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1501;
UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/VHIT', `course_description` = '<h4>Course Information</h4> <p>The Master of History (Advanced) provides the theoretical grounding and practical skills you need for the advanced study of history, plus the opportunity to tailor a program according to your interests. If youre a secondary school teacher, you are able to focus on areas in the national curriculum for history.</p> <h5>Course Structure</h5> <p>The Master of History (Advanced) requires completion of 72 units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A cognate Bachelor degree or international equivalent with a minimum GPA of 6/7, and the approval of an identified supervisor for the research project/thesis; A Bachelor degree or international equivalent AND a Graduate Certificate or Graduate Diploma in a cognate discipline with a minimum GPA of 5/7, and the approval of an identified supervisor for the research project/thesis</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1502;
