UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/MSTD', `course_description` = '<h4>Course Information</h4> <p>The Master of Studies is an exit qualification only. It provides a flexible option for ANU students who require an early or different exit point from a single or Double Masters Degree or Master (Advanced) degree.</p> <h5>Course Structure</h5> <p>The Master of Studies requires the completion of 72 units, of which must come from 6000 level, 7000 level and 8000 level courses.</p>', `enrolment_fee` = 150.0, `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1522;
