UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>An AQF Level 7 Bachelor of Environmental Studies Degree, or equivalent, completed within the last two years:; with a weighted average mark equivalent to an ANU 70 per cent calculated from the 36 units (i.e. 0.75 EFTSL) of courses in the discipline cognate to the honours specialisation, excluding 1000 level courses (i.e. introductory undergraduate courses), with the highest marks.; And the satisfaction of any admission requirements described in the relevant honours specialisation</li></ul>', `enrolment_fee` = 150.0, `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1528;
