UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/BASIA', `course_description` = '<h4>Course Information</h4> <p>Engaging with Asia as a part of Asia is a strategic imperative for Australia. The Bachelor of Asian Studies provides a pathway for ambitious and adventurous people in all fields of study to gain the language skills and cultural historical expertise critical to leading that engagement. Graduates emerge with a nuanced understanding of the Asian region and its complex national and subnational parts.</p> <h5>Course Structure</h5> <p>The Bachelor of Asian Studies requires completion of 144 units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>An Australian year 12 qualification or international equivalent; OR previous higher education studies; or secondary education results if completed less than one full time equivalent year (1.0 FTE) of a degree; or the result from a bridging or preparatory course. Or previously completed VET qualifications at AQF level 5 or higher (i.e. a Diploma or above); or secondary education results if the VET qualification is not completed.</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '3 years full-time (156 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1538;
