UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/DPUBP', `course_description` = '<h4>Course Information</h4> <p>The Graduate Diploma of Public Policy is an exit Award only and is not available for direct admission.</p> <h5>Course Structure</h5> <p>The Graduate Diploma of Public Policy requires the completion of 48 units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>The Graduate Diploma of Public Policy is an exit Award only and is not available for direct admission.</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1546;
