UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/DENVI', `course_description` = '<h4>Course Information</h4> <p>The Graduate Diploma in Environment is a flexible interdisciplinary coursework degree that reflects a program of learning suited to your individual interests and skills in environment and sustainability. A broad ranging suite of courses from across the University provide exposure to current perspectives on environmental issues and approaches. Areas of interest include environmental science and management, social and ecological linkages, environmental economics and governance, environmental policy, and integrative research methods.</p> <h5>Course Structure</h5> <p>The Graduate Diploma of Environment requires the completion of 48 units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>The Graduate Diploma of Environment is an exit Award only and is not available for direct admission.</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1551;
