UPDATE `courses` SET `apply_form` = 'https://programsandcourses.anu.edu.au/2026/program/BAPAR', `course_description` = '<h4>Course Information</h4> <p>The Bachelor of Asia Pacific Affairs provides students with an in depth exploration of Asia Pacific regional affairs drawing on the strength of ANU in four different subject and disciplinary areas including politics and government; international relations and security; conflict and peacebuilding; history and cultural identity. This innovative program will give students a unique opportunity to understand the transnational forces and contemporary challenges facing the Asia Pacific region, and to deepen their understanding and appreciation of different Asia Pacific cultures.</p> <h5>Course Structure</h5> <p>The Bachelor of Asia Pacific Affairs requires the completion of 192 units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>An ATAR of 82 or an equivalent rank derived from the Australian Senior Secondary Certificate of Education (AQF) or equivalent; The ANU English Language Admission Requirements for admission into a Bachelor Degree program, as advertised by ANU at the time of application</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'assignment', `intakes` = 'First Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 1607;
