UPDATE `courses` SET `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: overall score of 6.5, no band less than 6</li><li><strong>TOEFL iBT:</strong> TOEFL: overall score of 79, section scores no less than: Listening: 19 Speaking: 19 Reading: 18 Writing: 22</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: overall score of 6.5, no band less than 6</li><li><strong>TOEFL iBT:</strong> TOEFL: overall score of 79, section scores no less than: Listening: 19 Speaking: 19 Reading: 18 Writing: 22</li></ul>', `total_course_duration` = '104 weeks', `assessment_style` = 'assignment', `intakes` = '06 July 2026, 13 July 2026; 11 January 2027, 15 February 2027, 26 April 2027; 13 July 2026,; 13 July 2026, 05 October 2026; 15 February 2027; 15 February 2027,; 15 February 2027, 26 April 2027, 26 July 2027; 20 July 2026,; 27 July 2026,; 27 July 2026', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2064;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Build on your experience as a education professional by studying the latest theory with a Master of Education (by coursework) from Victoria University.\r\nThis flexible postgraduate education course is underpinned by a strong focus on social justice, sustainability and ethical action. You will gain the skills and confidence to address educational challenges and opportunities in the school system, universities, community, government and industry.\r\nStudying advanced theory under passionate and experienced educators, you&#x27;ll further your expertise in learning and teaching practice.\r\nThe Master of Education is designed for teachers, principals, community educators, youth workers, policy-makers and other professionals whose work has an educational component or responsibility.\r\nThis course does not provide you with registration to teach in Australia.</p> <h5>Course Structure</h5> <p>To attain the award of Master of Education students will be required to completed in total 192 credit points consisting of:\r\n\r\n192 credit points of Core studies</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>To be considered for postgraduate study, you will need to have specific academic qualifications, as outlined below. We also consider non-academic research and work experience for our research candidates. Admission criteria Completion of an Australian Bachelor degree (or equivalent) in a similar discipline OR Completion of an Australian Graduate Diploma (or equivalent) in a similar discipline PLUS IELTS (or equivalent): Overall score of 7 (Listening 7.0, Reading 6.5, Writing 6.5 and Speaking 7.0)</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: Overall score of 7 Listening 7</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: Overall score of 7 Listening 7</li></ul>', `total_course_duration` = '2 years flexible delivery (104 weeks)', `assessment_style` = 'assignment', `intakes` = '27 July 2026, 28 September 2026', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2065;
UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Entry into a graduate certificate or graduate diploma generally requires you to have completed an undergraduate qualification that is comparable to an Australian bachelor degree.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: overall score of 6.5, no band less than 6</li><li><strong>PTE Academic:</strong> PTE: overall score of at least 60, no section score</li><li><strong>TOEFL iBT:</strong> TOEFL: overall score of 79, section scores no less than: Listening: 19 Speaking: 19 Reading: 18 Writing: 22</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: overall score of 6.5, no band less than 6</li><li><strong>PTE Academic:</strong> PTE: overall score of at least 60, no section score</li><li><strong>TOEFL iBT:</strong> TOEFL: overall score of 79, section scores no less than: Listening: 19 Speaking: 19 Reading: 18 Writing: 22</li></ul>', `total_course_duration` = '78 weeks', `assessment_style` = 'assignment', `intakes` = '06 July 2026, 13 July 2026; 11 January 2027, 15 February 2027, 26 April 2027; 13 July 2026,; 13 July 2026, 05 October 2026; 15 February 2027; 15 February 2027,; 15 February 2027, 26 April 2027, 26 July 2027; 20 July 2026,; 27 July 2026,; 27 July 2026', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2068;
UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Bachelor degrees are the most common first university degree after high school, usually completed in three or four years full-time.</li><li>Academic entry requirements for bachelor degrees</li><li>Entry into undergraduate courses (for example a bachelor degree) generally requires you to have completed a secondary school qualification equivalent to an Australian Year 12 certificate.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: overall score of 6.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: overall score of 6.0</li></ul>', `total_course_duration` = '52 weeks', `assessment_style` = 'assignment', `intakes` = '06 July 2026, 13 July 2026; 11 January 2027, 15 February 2027, 26 April 2027; 13 July 2026,; 13 July 2026, 05 October 2026; 15 February 2027; 15 February 2027,; 15 February 2027, 26 April 2027, 26 July 2027; 20 July 2026,; 27 July 2026,; 27 July 2026', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2069;
