UPDATE `courses` SET `apply_form` = 'https://www.vu.edu.au/about-vu/teaching-colleges-schools/college-of-english-foundation-pathways/vu-english/general-english', `course_description` = '<h4>Course Information</h4> <p>The General English course is for students with beginner to intermediate levels of English. This course will help you develop the English language skills for: everyday use; speaking, listening, reading and writing; entry into the English for Academic Purposes course.</p> <h5>Course Structure</h5> <p>Elementary (Level 1), Pre-intermediate (Level 2), Intermediate (Level 3), Upper Intermediate (Level 4), Advanced (Level 5)</p> <h5>Study & Career Pathways</h5> <p>On completion of GE3 - General English 3 (Intermediate) you can advance to English for Academic Purposes (EAP) and English for BULATS Preparation.</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: 6.0</li><li><strong>TOEFL iBT:</strong> TOEFL IBT: 60</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: 6.0</li><li><strong>TOEFL iBT:</strong> TOEFL IBT: 60</li></ul>', `total_course_duration` = '10 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'Multiple Intakes', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2078;
