UPDATE `courses` SET `apply_form` = 'https://www.vu.edu.au/about-vu/teaching-colleges-schools/college-of-english-foundation-pathways/vu-english/english-for-academic-purposes-eap', `course_description` = '<h4>Course Information</h4> <p>English for Academic Purposes (EAP) is a university and TAFE preparation course for international students.It&#x27;s designed for international students with upper-intermediate to advanced levels of English who want to gain admission to an Australian TAFE, undergraduate or postgraduate course.</p> <h5>Course Structure</h5> <p>EAP 4 – English for Academic Purposes Upper IntermediateA 10-week unit for students who wish to study academic English or gain direct entry into foundation studies, TAFE certificates/diplomas or higher education diplomas (Diploma of Business, Engineering or Information Technology) at VU.EAP 5 – University Preparation UndergraduateA specialised 10-week unit for students who wish to enrol in a Victoria University undergraduate course.EAP 6 – University Preparation PostgraduateFor students with an advanced level of English who wish to enrol in a Victoria University postgraduate course.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>IELTS 5.0^, VU English Placement Test or completion of VU General English Intermediate (Level 3). ^ Overall score of 6, plus writing at 6, for EAP 6. Overall score of 5.5, plus writing at 5.5, for EAP 5</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 5.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 5.0</li></ul>', `total_course_duration` = '10 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'Multiple Intakes', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2108;
