UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Prepare for a fascinating career in the justice system or community welfare, with VU&#x27;s Bachelor of Criminal Justice and Psychological Studies.\r\n\r\nYou&#x27;ll gain a strong understanding of the factors that contribute to criminal behaviour. You&#x27;ll also learn about the legal, political and community responses to social dislocation and disorder.\r\n\r\nOur expert lecturers deliver a clear overview of:\r\n\r\ncriminal justice systems\r\nethics\r\ncrime investigation\r\nlaw and governance.\r\nYour psychology studies will give you insight into the factors that underpin human behaviour and development.\r\n\r\nYou&#x27;ll graduate equipped with analytical and problem-solving skills needed for roles in criminal justice, police and welfare systems.</p> <h5>Course Structure</h5> <p>To attain the Bachelor of Criminal Justice and Psychological Studies students will be required to complete 288 credit points</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Australian Senior Secondary Certificate (e.g. VCE) orAn Australian or overseas equivalent orAn International Baccalaureate (IB).</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6</li></ul>', `total_course_duration` = '3 years full-time (156 weeks)', `assessment_style` = 'assignment', `intakes` = '27 July 2026,', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2245;
