UPDATE `courses` SET `apply_form` = 'https://www.canberra.edu.au/course/NPB003/1/2026', `course_description` = '<h4>Course Information</h4> <p>UCs new Bachelor of Science has been created to help expand your scientific knowledge, while giving you the freedom to explore what you like and discover what you love. Building on the strong foundational Core Major in Science, youll develop a highly-transferrable set of skills that include critical thinking, scientific reasoning, data analysis and communication thatll stay with you long after graduating. Youll also undertake scenario-based study, participate in practical work integrated learning opportunities, and use industry-standard lab equipment. These experiences and skills will equip you to solve a range of theoretical and contemporary real-world problems.</p> <h5>Course Structure</h5> <p>72 credit points</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Admission to this course is based on an entrance rank. A rank can be achieved by the following means: Year 12 ATAR, other Australian Qualification, work experience, overseas qualification.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic score of 6.0 overall, with no band score below 6</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic score of 6.0 overall, with no band score below 6</li></ul>', `total_course_duration` = '3 years full-time (156 weeks)', `assessment_style` = 'assignment', `intakes` = 'February 16, 2026, August 10, 2026, February 15 2027, August 09 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2394;
