UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/bachelor-of-business-bachelor-of-laws-honours', `course_description` = '<h4>Course Information</h4> <p>Combine law with a business specialisation, opening doors to careers in corporate law, company takeovers, mergers and acquisitions or intellectual property law.</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic / One Skill Retake 6.5</li><li><strong>PTE Academic:</strong> PTE Academic 59</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic / One Skill Retake 6.5</li><li><strong>PTE Academic:</strong> PTE Academic 59</li></ul>', `total_course_duration` = '5.5 years full-time', `assessment_style` = 'assignment', `intakes` = 'February; February, June, October; January; July; July, August, October; July, November; July. August. October. November; March, July, November; October; Start any time; Throughout the year', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2601;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>In a world where organisations are being disrupted and expectations of work and professional practice are changing, QUT&#x27;s management major will help you develop the skills to confidently manage teams, risk, projects and operations in changing environments. You will develop skills in entrepreneurial thinking, strategic decision making, leadership, communication, and negotiation, and have the opportunity to study either entrepreneurship or project management. The focus of this major is to provide students with the knowledge and skillset to implement the efficient and effective use of organisational resources; whether in new entrepreneurial ventures or established organisations.</p> <h5>Course Structure</h5> <p>288 units</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic / One Skill Retake Overall 6.5</li><li><strong>PTE Academic:</strong> PTE Academic Overall 58</li><li><strong>TOEFL iBT:</strong> TOEFL iBT Overall 79</li></ul>', `assessment_style` = 'assignment', `intakes` = 'July, November', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2602;
