UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/university-study-abroad-year?international=', `course_description` = '<h4>Course Information</h4> <p>University Study Abroad Year</p>', `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2626;
UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/doctor-of-education', `course_description` = '<h4>Course Information</h4> <p>The Doctor of Education (EdD) focuses on applied investigation and problem solving rather than on a contribution to pure research or to theoretical knowledge. This professional doctorate, comprising coursework units and a thesis, is oriented towards enhancing professional practice and focuses on the professional development of practitioners involved in some aspect of education.</p> <h5>Course Structure</h5> <p>288 credit points</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A completed recognised four-year honours Class IIA degree in education; or a masters degree in education or in a field relevant to the professional doctorate in education with a minimum GPA of 5.00 on QUT&#x27;s 7 point scale; and two years&#x27; practice in a position of professional responsibility in education or a closely related field.</li></ul>', `total_course_duration` = '3 years full-time (156 weeks), 6 years part-time (312 weeks)', `assessment_style` = 'assignment', `intakes` = 'January', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2627;
UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/bachelor-of-information-technology-honours', `course_description` = '<h4>Course Information</h4> <p>The primary aim of the Bachelor of Information Technology (Honours) is to provide a strong and practical foundation both for research and professional employment. Advanced theory, professional training (where appropriate), and a research project that leads to a research paper or thesis are therefore incorporated within the course.\nIn addition to developing graduates&#x27; skills in knowledge and problem solving to an advanced level, the course aims to equip graduates with well-developed skills in lifelong learning and a strong commitment to professional and ethical practice.</p> <h5>Course Structure</h5> <p>96 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>You must have a recognised bachelor degree in information technology or relevant discipline with a minimum grade point average of 5.00 (on QUT&#x27;s 7-point scale), completed within the last 5 years, plus: Suitable honours topic, Proposed honours supervisor; If you do not meet the grade point average requirement but you have: Excelled in the final semesters of your degree; or Completed a double degree and excelled in the business or commerce part of your double degree.</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2628;
UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/graduate-diploma-in-public-health', `course_description` = '<h4>Course Information</h4> <p>Public health professionals promote population health and wellbeing in service areas such as food safety, disease control, prevention programs, health promotion and environmental health. QUT&#x27;s public health programs are designed for professionals interested in a career in public health, mid-career professionals seeking advancement and clinicians looking to broaden their range of expertise. Students obtain core skills in epidemiology and biostatistics and an understanding of contemporary and challenging population health issues. You may choose to complete specialist study in emergency and disaster management; epidemiology and research methods; health promotion; health services management; health, safety and environment; or select units from more than one study area.</p> <h5>Designed For</h5> <p>Health professionals moving into the public health area; mid-career health professionals seeking advancement; and clinicians wishing to broaden their range of expertise</p> <h5>Course Structure</h5> <p>Total credit point: 96</p> <h5>Study & Career Pathways</h5> <p>This course fully articulates into the Master of Public Health. Students who complete 4 units may exit early with a Graduate Certificate.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A completed recognised Bachelor Degree in any discipline</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2629;
UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/graduate-diploma-in-applied-science-medical-physics', `course_description` = '<h4>Course Information</h4> <p>These courses deal with well-established and emerging areas of medical and health physics including clinical measurement, computing, health physics, instrumentation, medical electronics, medical imaging, physiological monitoring, physics of radiotherapy, radiobiology, and radiological imaging sciences. The coursework also contains an introduction to the clinical sciences.</p> <h5>Designed For</h5> <p>Those who wish to gain an understanding of medical and health physics through a coursework program</p> <h5>Course Structure</h5> <p>96 total credit points</p> <h5>Study & Career Pathways</h5> <p>Articulates into Master of Applied Science (Medical Physics)</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>You must have a recognised bachelor degree (or higher qualification) in one of the following fields: Biomedical, medical, medical electronics etc engineering; Biophysics; Electrical, avionics etc engineering; Geophysics; Mechanical engineering; Medical physics; Physics</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2630;
