UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Combine psychology and business for a career as a market researcher, human resources manager or training and development consultant. This double degree will give you a solid understanding of how business and psychological influences impact on organisations. Your knowledge of human behaviour and its role in organisational environments will prepare you for many professional roles.</p> <p>If you are aiming for a managerial career in business, you will develop the skills necessary to face the increasingly high demands of training and change management.</p> <h5>Course Structure</h5> <p>Students are required to complete 384 credit points comprised of 192 credit points from the Bachelor of Behavioural Science (Psychology) program and 192 credit points from the Bachelor of Business.</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic / One Skill Retake Overall 6.5</li><li><strong>PTE Academic:</strong> PTE Academic Overall 58</li><li><strong>TOEFL iBT:</strong> TOEFL iBT Overall 79</li></ul>', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2662;
UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/bachelor-of-behavioural-science-honours-psychology?international=', `course_description` = '<h4>Course Information</h4> <p>The honours program builds on an Australian Psychology Accreditation Council (APAC)-accredited undergraduate psychology degree and provides an opportunity for advanced study and research.</p> <h5>Course Structure</h5> <p>Total credit point: 96</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A completed recognised bachelor degree in psychology completed within the past ten years with a minimum grade point average (GPA) of 5.0 (on QUT&#x27;s 7-point scale). The degree must be accredited by the Australian Psychology Accreditation Council (APAC) as an entry point into an honours program; e.g.Bachelor of Behavioural Science (Psychology) at QUT. A grade of at least 4.0 (on QUT&#x27;s 7-point scale) for each of the APAC-accredited second and third year psychology units listed below. A grade point average of at least 5.30 (on QUT&#x27;s 7-point scale) across all attempts of the listed APAC accredited second- and third-year psychology units listed below. Successful completed an APAC-accredited advanced statistical analysis unit at third-year level.</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2663;
UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/graduate-diploma-in-occupational-health-and-safety?international=', `course_description` = '<h4>Course Information</h4> <p>The Graduate Diploma in Occupational Health and Safety is multidisciplinary in design and equips students with advanced knowledge and skills in risk assessment, risk management, ergonomics, occupational health, law, management, and occupational hygiene. Graduates of this program can pursue management positions in a variety of industries locally and overseas.</p> <h5>Designed For</h5> <p>Graduates who wish to gain professional knowledge in the field of occupational health and safety</p> <h5>Course Structure</h5> <p>(96 credit points)</p> <h5>Study & Career Pathways</h5> <p>The course fully articulates with the Master of Health, Safety and Environment.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A completed recognised bachelor degree (or higher award) with a minimum grade point average (GPA) of 4 (on QUT&#x27;s 7 point scale) in any discipline.</li></ul>', `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2664;
UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/graduate-diploma-in-environmental-health', `course_description` = '<h4>Course Information</h4> <p>The Graduate Diploma in Environmental Health provides an entry pathway into environmental health professional practice. Students are highly skilled to assess environmental health risks and combat a range of environmental challenges including climate change, pollution, and communicable diseases.</p> <h5>Designed For</h5> <p>Science, nursing or health graduates wanting entry into environmental health</p> <h5>Course Structure</h5> <p>96 credit points</p> <h5>Study & Career Pathways</h5> <p>The course articulates into the Master of Health, Safety and Environment.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A completed recognised bachelor degree (or higher award) with a minimum grade point average (GPA) of 4 (on QUT&#x27;s 7 point scale) in any discipline; and A minimum 48 credit points (equivalent of one semester full-time study) of recognised basic science units that were included at Bachelor level and must include: a minimum of 12 credit points (one subject) of foundation chemistry; and a further 36 credit points (equivalent to three subjects) in other science areas (e.g. microbiology, physics, anatomy and physiology, life science, environmental science).</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2665;
