UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/general-english-program-45-weeks', `course_description` = '<h4>Course Information</h4> <p>General English at QUT College is a great way to improve your English for school, work and everyday life. You will develop your proficiency through presentation and practice of relevant language content and skills in small classes (maximum 18 students). There will be interactive, task-based, student-centred activities in both simulated and authentic contexts.</p> <h5>Course Structure</h5> <p>Total credit points 180</p>', `total_course_duration` = '15 weeks full-time, 45 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'July. August. October. November', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2667;
