UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Combine psychology and social work to work in community services, counselling and family-centred intervention, mental health services, drug and alcohol intervention, or disability services. Graduates of this degree have a substantial skill set which is suitable for challenging and complex practice in a variety of settings including mental health, drug and alcohol prevention and intervention, international practice, disabilities, and in the development and delivery of community services, counselling and family-centred intervention.</p> <h5>Course Structure</h5> <p>Total credit points 480</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic / One Skill Retake Overall 7</li><li><strong>PTE Academic:</strong> PTE Academic Overall 66</li><li><strong>TOEFL iBT:</strong> TOEFL iBT Overall 98</li></ul>', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2676;
