UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This course helps you improve your academic English language skills to achieve an IELTS 7.0 (sub-scores 7.0). This program is taught at QUT College, which is located at QUT&#x27;s Kelvin Grove campus. The College is where you will spend most of your time going to classes and getting to know other international students. You will receive a QUT Student ID card which will give you access to all QUT&#x27;s outstanding facilities, making you part of the fun and exciting QUT university community right from the start. Our community offers lifestyle and social opportunities, which will help you to enjoy a richer cultural experience.</p>', `total_course_duration` = '10 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2684;
UPDATE `courses` SET `apply_form` = 'https://qutvirtual4.qut.edu.au/web/qut/course?courseCode=HL53&id=44070&year=2026', `course_description` = '<h4>Course Information</h4> <p>The Bachelor of Biomedical Science (Honours) is designed to provide a strong and practical foundation for research and professional employment.</p> <h5>Course Structure</h5> <p>Total credit point: 96</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A recognised bachelor degree in agriculture science, engineering, health, information technology, mathematics, science, or veterinary science with a minimum grade point average of 5.00 (on QUT&#x27;s 7-point scale), completed within the last 2 years, plus: Suitable honours topic, Proposed honours supervisor. If you do not meet the grade point average requirement but you have: Excelled in the final semesters of your degree; or, Completed a double degree and excelled in the relevant degree part of your double degree</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'February; February, June, October; January; July; July, August, October; July, November; July. August. October. November; March, July, November; October; Start any time; Throughout the year', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2685;
