UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/master-of-advanced-manufacturing', `course_description` = '<h4>Course Information</h4> <p>Learn the skills to become an innovative engineer to design, optimise and improve manufacturing. Major in Digital and Robotics Manufacturing or Bioprocess Engineering.</p>', `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2830;
