UPDATE `courses` SET `apply_form` = 'https://qutvirtual4.qut.edu.au/web/qut/course?courseCode=BV06&id=41992&year=2025', `course_description` = '<h4>Course Information</h4> <p>This vertical double degree will provide you with a comprehensive Business and Data Analytics education. You will acquire a solid foundation in business during your undergraduate studies and enhance your analytical skills in the postgraduate component.</p>', `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'assignment', `intakes` = 'February; February, June, October; January; July; July, August, October; July, November; July. August. October. November; March, July, November; October; Start any time; Throughout the year', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2842;
