UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/master-of-advanced-manufacturing-with-data-analytics', `course_description` = '<h4>Course Information</h4> <p>Advanced manufacturing is important for the world as it couples manufacturing efforts together to get the most sustainable output. This course prepares you to design, optimise and improve modern manufacturing systems with new technologies that are coming into the market every day to engineer a holistic and circular manufacturing approach.</p>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2851;
