UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/master-of-cyber-security', `course_description` = '<h4>Course Information</h4> <p>Advance your career with the QUT Master of Cyber Security. Gain in-demand skills, complete industry projects, and learn from top experts. Address the rising demand for cyber security professionals and prepare for roles such as cyber security specialist, information security analyst and penetration tester.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>2 year program; You must have a recognised bachelor degree (or higher qualification) in any discipline with a minimum grade point average (GPA) of 4.00 (on QUTs 7 point scale).; 1.5 year program; A recognised bachelor degree (or higher qualification) in information technology with a minimum grade point average (GPA) score of 4.00 (on QUT&#x27;s 7 point scale) or; A recognised bachelor degree in any other discipline with a minimum grade point average (GPA) score of 4.00 (on QUT&#x27;s 7 point scale) followed by three full-time years (or equivalent) of professional work experience in information technology.</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2881;
UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/master-of-artificial-intelligence', `course_description` = '<h4>Course Information</h4> <p>Advance your career with the QUT Master of Artificial Intelligence. Gain specialised AI and machine learning skills, complete industry projects, and learn from top experts. Address the rising demand for AI professionals and prepare for roles like AI Engineer, Machine Learning Specialist, Data Scientist, and more.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>2 year program; You must have a recognised bachelor degree (or higher qualification) in any discipline with a minimum grade point average (GPA) of 4.00 (on QUTs 7 point scale).; 1.5 year program; A recognised bachelor degree (or higher qualification) in information technology with a minimum grade point average (GPA) score of 4.00 (on QUTs 7 point scale) or; A recognised bachelor degree in any other discipline with a minimum grade point average (GPA) score of 4.00 (on QUTs 7 point scale) followed by three full-time years (or equivalent) of professional work experience in information technology</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 2882;
UPDATE `courses` SET `apply_form` = 'https://www.qut.edu.au/courses/master-of-biomedical-systems-and-technology', `course_description` = '<h4>Course Information</h4> <p>Learn from industry and research experts, such as Associate Professor Paige Little, who leads cutting-edge spine biomechanics research, partnering with the Queensland Children’s Hospital to design bespoke, technology-driven patient solutions. Her work highlights the role engineers play in advancing the future of personalised healthcare. As the MedTech industry continues to grow over the next decade, there is an increasing demand for engineers who possess practical skills alongside real-world experience to solve clinical challenges.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A recognised completed four-year full-time (or equivalent) engineering degree in a relevant discipline with a minimum GPA of 4.00 (on QUT’s 7-point scale)</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `total_course_duration` = '1.5 years full-time (78 weeks), 3 years part-time (156 weeks)', `assessment_style` = 'assignment', `intakes` = 'July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5800;
