UPDATE `courses` SET `apply_form` = 'https://www.cdu.edu.au/study/course/english-academic-purposes-4-zeap40', `course_description` = '<h4>Course Information</h4> <p>English for Academic Purposes prepares international students for undergraduate and postgraduate studies at Charles Darwin University. English for Academic Purposes is designed for students who have met the academic requirements of their program but have not yet met the English language requirements. The course builds both English Language skills and the academic skills students need to succeed at the university. Small classes and specialist teachers provide a supportive, inclusive, and effective learning environment in which students can build their confidence before transitioning into an Australian University environment.</p>', `total_course_duration` = '0.5 years full-time (26 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1; Semester 1, Semester 2; Semester 1, Semester 2, Summer Semester', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3010;
