UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/postgraduate/master-of-professional-accounting', `course_description` = '<h4>Course Information</h4> <p>Are you considering a career in Accounting? Do you hold an undergraduate degree or equivalent? The Master of Professional Accounting is an accredited graduate conversion program. It provides opportunities for applicants holding a degree (recognised as equivalent to an Australian three year undergraduate degree) in any discipline, other than an accredited accounting major, to complete the pre-entry educational requirements for CPA Australia, Chartered Accountants Australia and New Zealand (CA ANZ), and the Institute of Public Accountants (IPA). The program delivers a contemporary education in accounting principles and procedures supported by knowledge of associated disciplines of law, economics and finance. During this program you will learn how to apply accounting concepts, theories and models through a range of individual and collaborative means, including industry relevant projects and realistic business problems.</p> <h5>Course Structure</h5> <p>120 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants must have successfully completed an undergraduate degree, or higher, in business or; Successfully completed a Graduate Certificate in any discipline.</li></ul>', `total_course_duration` = '1.5 years full-time (78 weeks), 3 years part-time (156 weeks)', `assessment_style` = 'assignment', `intakes` = '22 June 2026, 14 September 2026, 04 January 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3302;
