UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-design-and-technology', `course_description` = '<h4>Course Information</h4> <p>This program will provide comprehensive knowledge of all design areas, leading to multiple career outcomes, including product design, packaging, rapid prototyping, 3D modelling, exhibition design and secondary school teaching (with additional degrees). You will also have the flexibility to specialise.</p> <h5>Course Structure</h5> <p>240 credit points. (24 subjects). A 10 week session of industrial experience is required during/after the third year.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent; Assumed knowledge: any two units of English plus at least two units of Design, Design and Technology, Visual Arts, Digital Multimedia, Engineering, or Business Studies</li></ul>', `total_course_duration` = '3 years full-time (156 weeks), 6 years part-time (312 weeks)', `intakes` = '20 July 2026, 01 March 2027, 19 July 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3310;
