UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-health-science', `course_description` = '<h4>Course Information</h4> <p>Our Bachelor of Health Science combines study with hands-on experience and allows you to major in one or two specialisations in the areas of public health, health promotion, health services management, recreational therapy and clinical sciences. The program is designed to give you the skills you need to work with clients and develop great services which promote health and well-being.</p> <h5>Course Structure</h5> <p>240 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent; Assumed knowledge: Any 2 units of English.</li></ul>', `total_course_duration` = '3 years full-time (156 weeks), 3 years online/off-campus (156 weeks)', `intakes` = '20 July 2026, 01 March 2027, 19 July 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3327;
