UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-policing', `course_description` = '<h4>Course Information</h4> <p>As the only Policing degree in metropolitan Sydney, we prepare you for an unlimited future in the force. This degree will give you the skills you need to enter into careers in policing, criminal and community justice organisations, corrective services, border protection, intelligence, security and fraud management, forensics, computer forensics, and more.</p> <h5>Course Structure</h5> <p>240 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent; any 2 units of English</li></ul>', `total_course_duration` = '3 years full-time (156 weeks), 6 years part-time (312 weeks)', `intakes` = '20 July 2026, 01 March 2027, 19 July 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3329;
