UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-medical-research', `course_description` = '<h4>Course Information</h4> <p>This program provides students enrolled in the Doctor of Medicine more detailed experience in medical research.</p> <h5>Course Structure</h5> <p>240 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Must be currently enrolled in Bachelor of Medicine and Bachelor of Surgery (MBBS) or Doctor of Medicine (MD) at Western Sydney University, and have successfully completed at least 160 credit points of that program, with a Grade Point Average (GPA) of 5 (credit average), before being admitted to Year 3 of the intercalated Bachelor Medical Research.</li></ul>', `total_course_duration` = '3 years full-time (156 weeks), 6 years part-time (312 weeks)', `intakes` = '01 March 2027,; 01-Mar-27; 04 January 2027,; 20 July 2026,; 20 July 2026, 01 March 2027, 19 July 2027; 22 June 2026, 14 September 202, 04 January 2027; 22 June 2026, 14 September 2026, 04 January 2027; 29 June 2026, 26 October 2026; Applicable for th', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3365;
