UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-health-science-sport-and-exercise-science', `course_description` = '<h4>Course Information</h4> <p>This degree focuses on the science that underpins physical activity and exercise, and how it can be used to design, implement and evaluate exercise programs. Throughout your study, you will gain valuable practical experience while having access to state-of-the-art facilities, dedicated exercise and sport science labs, and sports venues.</p> <h5>Course Structure</h5> <p>240 credit points. There are 140 hours of professional practice placements. Professional placements require full-time attendance.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent; Assumed Knowledge: Any 2 subjects of English; Recommended Studies: Any 2 subjects of English, plus four subjects of Science and/or Mathematics. PDHPE can be counted as a science subject for this program.</li></ul>', `total_course_duration` = '3 years full-time (156 weeks)', `intakes` = '20 July 2026,', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3382;
