UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/postgraduate/master-of-professional-accounting-advanced', `course_description` = '<h4>Course Information</h4> <p>Take your accounting career to the next level. This postgraduate degree gives you an in-depth understanding of accounting theory, principles, procedures and teaches relevant aspects of the law, economics and finance to nurture your ability to provide quality business information and solutions.</p> <h5>Course Structure</h5> <p>160 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants must have successfully completed an undergraduate degree, or higher, in any discipline or; Successfully completed a Graduate Certificate.</li></ul>', `total_course_duration` = '2 years full-time (104 weeks), 4 years part-time (208 weeks)', `intakes` = '22 June 2026, 14 September 2026, 04 January 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3385;
