UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-traditional-chinese-medicine', `course_description` = '<h4>Course Information</h4> <p>This degree equips practitioners with the knowledge and professional competencies required for a career in acupuncture, Chinese herbal medicine and herb dispensing. Building a solid, broad understanding of biomedicine and various health science fields in this way will give you a deeper understanding of TCM and help you to work in interdisciplinary teams and centres and assist you in advising clients on treatment options</p> <h5>Course Structure</h5> <p>320 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent; Assumed knowledge: any 2 units of English.; Recommended studies: Biology</li></ul>', `total_course_duration` = '4 years full-time (208 weeks)', `intakes` = '01 March 2027,', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3444;
