UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-business-bachelor-of-laws', `course_description` = '<h4>Course Information</h4> <p>This double degree provides you with the practical skills and knowledge required to excel in the fields of both business and law. Whether you wish to pursue a corporate role in a global enterprise or start your own business, this degree will provide you with the skills to do it.</p> <h5>Course Structure</h5> <p>400 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent; Recommended studies: HSC English (Advanced); Assumed Knowledge: HSC 2 unit Mathematics.</li></ul>', `total_course_duration` = '5 years full-time (260 weeks), 10 years part-time (520 weeks)', `intakes` = '20 July 2026, 01 March 2027, 19 July 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3454;
