UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/postgraduate/master-of-human-resource-management', `course_description` = '<h4>Course Information</h4> <p>This program builds the necessary knowledge base for working in employment relations, but the emphasis is knowledge in action, as inspired by the Australia Human Resource Institutes capabilities for HR professionals and Western Sydney Graduate Attributes designed to bring knowledge to life.</p> <h5>Course Structure</h5> <p>80 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants must have successfully completed a graduate certificate, or higher, in a business discipline or; Successfully completed an undergraduate degree in a Business discipline (specifically human resource management, human resource development, industrial relations, employment relations, organisational development or related discipline) with a GPA of 5.0 or WAM (Weighted Average Mark) of 65+ (if provided on the academic record) or; Successfully completed an undergraduate degree, or higher, in any discipline and a minimum of two years full-time equivalent managerial/professional work experience in roles facilitating human resource management, organisational development and training, and employment relations, or in related roles or; Successfully completed an undergraduate degree, or higher, in any discipline and a minimum of five years general work experience in human resource management, organisational development and training, and employment relations, or in related roles.</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = '22 June 2026, 14 September 2026, 04 January 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3473;
