UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/postgraduate/master-of-property-investment-and-development', `course_description` = '<h4>Course Information</h4> <p>This program allows you to understand the multi-disciplinary nature of property investment and development, and to develop the analytical and decision making skills necessary for property investment and development, and property professionals. This property program has an outstanding reputation in the property industry, with many students moving into major careers in the property industry in Australia and overseas.</p> <h5>Course Structure</h5> <p>80 credit points.; 120 credit points.; 160 credit points. depending on qualifications and pathway undertaken.</p>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks)', `intakes` = '22 June 2026, 14 September 2026, 04 January 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3506;
