UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-speech-pathology', `course_description` = '<h4>Course Information</h4> <p>Speech pathology assesses and treats disorders of communication in areas such as speech, voice, language and swallowing in children and adults. Make a difference in the lives of others with the skills learned in this program.</p> <h5>Course Structure</h5> <p>320 credit points.</p>', `total_course_duration` = '4 years full-time (208 weeks)', `intakes` = '01 March 2027,', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3271;
