UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/postgraduate/master-of-artificial-intelligence', `course_description` = '<h4>Course Information</h4> <p>You will learn how AI is driving digital disruption, how to work in this dynamic and fast evolving field, and how it is changing every facet of life and society. This program focuses on the most important and up to date AI topics and trends including but not limited to: knowledge representation and reasoning, machine learning, natural language understanding and processing, knowledge graphs, AI ethics and governance as well as relevant major areas in Computing and Data Sciences.</p> <h5>Course Structure</h5> <p>160 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Undergraduate degree in Information Technology, Information Systems or Computer Science or equivalent. Degrees in other disciplines containing at least 8 units in Information Technology or other relevant disciplines such as data science, engineering, communications technology, may also be eligible.; Undergraduate degree in any discipline AND at least one year full time equivalent work experience in Information Technology, Information Systems or Computer Science or other relevant work experience or; Graduate Certificate in Information Technology Information Systems or Computer Science or equivalent or; Graduate Diploma in any discipline AND at least two years full time equivalent in Information Technology, Information Systems or Computer Science or other relevant work experience</li></ul>', `total_course_duration` = '2 years full-time (104 weeks), 4 years part-time (208 weeks)', `intakes` = '20 July 2026, 01 March 2027, 19 July 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3284;
