UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-paramedicine', `course_description` = '<h4>Course Information</h4> <p>Westerns Bachelor of Paramedicine gives you the skills and knowledge you need to be a paramedic and play an integral role in the health system, responding to emergencies involving patients with a range of health problems in diverse settings. When you graduate, you will have the required skills to work in an ambulance service, the private paramedical industry, or the defence forces.</p> <h5>Course Structure</h5> <p>240 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent; Assumed knowledge: any 2 units of English; Mathematics; Recommended studies: Biology</li></ul>', `total_course_duration` = '3 years full-time (156 weeks)', `intakes` = '01 March 2027,', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3538;
UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-industrial-design-honours', `course_description` = '<h4>Course Information</h4> <p>The Bachelor of Industrial Design (Honours) program prepares you for the profession with a new culture of learning supported by a user/student-centered approach, competency learning, design studio-project based learning, applied design research and innovation.</p> <h5>Course Structure</h5> <p>320 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent; Assumed knowledge: any two subjects of English plus at least two subjects of Design, Design and Technology, Visual Arts, Digital Multimedia, Engineering, or Business Studies.</li></ul>', `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'assignment', `intakes` = '20 July 2026, 01 March 2027, 19 July 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3539;
