UPDATE `courses` SET `apply_form` = 'https://www.westernsydney.edu.au/future/study/courses/undergraduate/bachelor-of-international-studies-bachelor-of-laws', `course_description` = '<h4>Course Information</h4> <p>This double degree program provides you with the practical skills and knowledge required to excel in the fields of both international studies and law. The Bachelor of International Studies program examines the historical development of relations among nation states and analyses contemporary political, social and cultural issues such as globalisation, transnationalism and migration. The Bachelor of Laws program satisfies the academic degree requirements for admission to practice as an Australian lawyer. Students will engage in collaborative face-to-face problem and case-based learning, will be supported by online learning materials, and will participate in authentic assessment to develop knowledge and skills.</p> <h5>Course Structure</h5> <p>400 credit points.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent; Assumed knowledge: any 2 units of HSC English; Recommended studies: HSC English standard or equivalent</li></ul>', `total_course_duration` = '5 years full-time (260 weeks), 10 years part-time (520 weeks)', `intakes` = '20 July 2026, 01 March 2027, 19 July 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3589;
