UPDATE `courses` SET `apply_form` = 'https://www.notredame.edu.au/study/international-students/semester-abroad-at-unda', `course_description` = '<h4>Course Information</h4> <p>Studying abroad can be a rich and fulfilling experience. Getting out of your comfort zone and experiencing other cultures can expand your horizons and worldview in a way no textbook can.</p> <p>Notre Dame has opportunities for you to study a semester abroad in Australia. Download aStudy Abroad Guideor emailstudyabroad@nd.edu.au.</p> <p>Watch what our Study Abroad students like most about studying here in our latest video about Study Abroad in Notre Dame, Australia, along with our top four reasons for choosing Notre Dame.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate IV or Diploma to gain entry into a degree</li></ul>', `total_course_duration` = '26 weeks', `assessment_style` = 'assignment', `intakes` = 'Semester 1; Semester 1, Semester 2; Semester 1; Semester 2', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3613;
