UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>The Graduate Certificate in Business is a one year part-time (or half year full-time) program taught by a team of industry leaders and academics who are passionate about sharing their knowledge. Throughout the course of your studies, you can choose to explore topics such as accounting, marketing, strategic management, leadership and business analytics. Upon the completion of this program, you have the option to progress to a Diploma of Business, Master of Leadership, or MBA.</p> <h5>Course Structure</h5> <p>1 compulsory course; 3 elective courses</p>', `assessment_style` = 'assignment', `intakes` = 'Semester 1, Semester 2', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3720;
