UPDATE `courses` SET `apply_form` = 'https://www.notredame.edu.au/programs/school-of-education/postgraduate/master-of-primary-teaching', `course_description` = '<h4>Course Information</h4> <p>The Master of Primary Teaching is a graduate-entry course for those who want to become primary school teachers and have an appropriate undergraduate degree. The degree is a NESA accredited initial teacher education program that applies advanced knowledge and research to the complexities, challenges and concerns facing the current teacher workforce. Graduates will be eligible for employment in government and non-government schools and if they decide to undertake a concurrent Religious education qualification, Catholic and other faith-based schools. This Master</p> <h5>Course Structure</h5> <p>1 core curriculum course; 13 compulsory courses; 2 Professional Experience courses</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants for this program must hold a Bachelor&#x27;s degree from a recognised higher education provider. Students who have English as an additional language and are admitted on the basis of an International English Language Testing System (IELTS) assessment, or an equivalent English language proficiency assessment, are only admitted if they have attained an overall score of 7.5 in IELTS Academic, with no score lower than 8.0 in speaking and listening, and no score lower than 7.0 in reading and writing.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic, with no score lower than 8.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic, with no score lower than 8.0</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1, Semester 2', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3733;
UPDATE `courses` SET `apply_form` = 'https://www.notredame.edu.au/programs/school-of-education/postgraduate/master-of-secondary-teaching', `course_description` = '<h4>Course Information</h4> <p>Do you hold a bachelor</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants for this program must hold a Bachelor&#x27;s degree from a recognised higher education provider. Students who have English as an additional language and are admitted on the basis of an International English Language Testing System (IELTS) assessment, or an equivalent English language proficiency assessment, are only admitted if they have attained an overall score of 7.5 in IELTS Academic, with no score lower than 8.0 in speaking and listening, and no score lower than 7.0 in reading and writing.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic, with no score lower than 8.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic, with no score lower than 8.0</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1, Semester 2', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3734;
