UPDATE `courses` SET `apply_form` = 'https://www.notredame.edu.au/programs/arts-and-sciences/postgraduate/master-of-computer-science', `course_description` = '<h4>Course Information</h4> <p>The Master of Computer Science offers a rigorous and immersive curriculum tailored to meet the needs of students aspiring to excel in the field of computer science. Structured to facilitate a strong grasp of core concepts, the program also emphasises practical application through real-world problem-solving. Students engage with cutting-edge software development tools and technologies, mastering their effective utilisation in tackling complex challenges.</p>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3749;
