UPDATE `courses` SET `apply_form` = 'https://hotelschool.scu.edu.au/courses/bachelor-of-business-in-hotel-management/', `course_description` = '<h4>Course Information</h4> <p>The three-year Bachelor of Business in Hotel Management focuses on hotel operational skills, management practices in. hospitality industries and the skills needed for employment in a competitive, changing, global business environment. This Southern Cross University degree combines academic rigour with contemporary hotel practice. Choose a major in either events, tourism or hospitality. This major appears on your testamur, e.g. Bachelor of Business in. Hotel Management (Events). Alternatively, you can choose from a range of elective units to tailor your studies, gaining knowledge in the areas that really interest you and that suit your current work-life journey.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Qualification equivalent to an Australian Year 12 with the required entry grade, or relevant work experience.; English language proficiency comparable to Academic IELTS 6.0 with no band less than 5.5.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6.0 with no band less than 5.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 60</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6.0 with no band less than 5.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 60</li></ul>', `total_course_duration` = '3 years full-time (156 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, June and October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3805;
