UPDATE `courses` SET `apply_form` = 'https://hotelschool.scu.edu.au/courses/diploma-of-hotel-management/', `course_description` = '<h4>Course Information</h4> <p>Undertaking a Diploma is your chance to engage in a study pathway without committing yourself to a full three year degree. Whether you are a school leaver, already working in the hotel industry or looking to make a career change, this course will develop your skills and enhance your career prospects in a dynamic, global industry. . This course covers theory and practices within the industry, finance, management and communication as well as food, beverage and accommodation operations.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Qualification equivalent to an Australian Year 12 with the required entry grade.; English language proficiency comparable to Academic IELTS 5.5 with 5.5 in writing and no other band less than 5.0.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 5.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 5.5</li></ul>', `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, June and October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3761;
UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Completion of Year 12 (or equivalent) or relevant work experience</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 5.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 5.5</li></ul>', `total_course_duration` = '52 weeks', `assessment_style` = 'assignment', `intakes` = 'February, June and October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3762;
UPDATE `courses` SET `apply_form` = 'https://hotelschool.scu.edu.au/courses/master-of-business-in-global-hotel-leadership/', `course_description` = '<h4>Course Information</h4> <p>Developed in collaboration with a range of top hotel leaders, the Master of Business in Global Hotel Leadership is designed for future leaders in the Hotel, Tourism and Leisure industry with a desire to accelerate their career path. This course will help participants to develop an advanced level of understanding of hotel operations and the principles behind hotel asset management, service design and delivery systems, operational models and disruptive technologies.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Equivalent to an Australian Bachelor degree (or demonstrated academic or professional standing equivalent).; English language proficiency comparable to Academic IELTS 6.5 with no band less than 6.0.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6.5 with no band less than 6.0</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 79</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6.5 with no band less than 6.0</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 79</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, June and October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3763;
UPDATE `courses` SET `apply_form` = 'https://hotelschool.scu.edu.au/courses/graduate-diploma-of-business-in-global-hotel-leadership/', `course_description` = '<h4>Course Information</h4> <p>The Graduate Diploma of Business in Global Hotel Leadership is a pathway to the Master of Business in Global Hotel Leadership. Taught by academics with industry backgrounds, the course provides comprehensive study of aspects of hotel management and leadership from both theoretical and applied industry perspectives. The course provides graduates with the skills and professional confidence to apply contemporary leadership techniques to the global hospitality and business sector. Graduates will be prepared to succeed in a middle management role across a range of hotel and hospitality settings.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Equivalent to an Australian Bachelor degree (or demonstrated academic or professional standing equivalent).; English language comparable to Academic IELTS 6.0 with no band less than 5.5.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6.0 with no band less than 5.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 79</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6.0 with no band less than 5.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 79</li></ul>', `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, June and October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3764;
UPDATE `courses` SET `apply_form` = 'https://hotelschool.scu.edu.au/courses/graduate-certificate-of-business-in-global-hotel-leadership/', `course_description` = '<h4>Course Information</h4> <p>The Graduate Certificate of Business in Global Hotel Leadership is a pathway to the Master of Business in Global Hotel Leadership. It provides an introduction to advanced study in contemporary leadership techniques as they apply to the global hotel and hospitality sectors. This course develops applied business skills to support graduates with their leadership careers in contemporary global hotel industries. The course provides an introduction to aspects of hotel management and leadership from both theoretical and applied industry perspectives.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Equivalent to an Australian Bachelor degree (or demonstrated academic or professional standing equivalent).; English language comparable to Academic IELTS 6.0 with no band less than 5.5.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6.0 with no band less than 5.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 79</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6.0 with no band less than 5.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 79</li></ul>', `total_course_duration` = '4 months full-time (17.333333333333332 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, June and October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3765;
