UPDATE `courses` SET `apply_form` = 'https://www.unisc.edu.au/study/courses-and-programs/postgraduate-degrees/master-of-health-promotion', `course_description` = '<h4>Course Information</h4> <p>The Master in Health Promotion is designed for professionals interested in a career in health promotion or wanting to develop deeper practice or research knowledge and skills in health promotion to complement their current roles.</p> <h5>Course Structure</h5> <p>Total units: 192</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Entry to the Master of Health Promotion program requires completion of a recognised Bachelors degree or equivalent from a recognised higher education institution.</li></ul>', `total_course_duration` = '2 years online/off-campus (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'Refer to UniSC website.', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3936;
