UPDATE `courses` SET `apply_form` = 'https://www.unisc.edu.au/study/courses-and-programs/postgraduate-degrees/master-of-nursing-clinical-leadership', `course_description` = '<h4>Course Information</h4> <p>Shape the future of clinical healthcare. If you are a degree-qualified nurse who is eligible to register (Division 1), this Masters program equips you with the skills and knowledge to have significant impact on the development and delivery of healthcare services. In this program you will prepare for clinical leadership, research and advanced practice roles and develop advanced knowledge and expertise in project design and management (research or quality improvement) and you will get to participate in continuing professional development.</p> <h5>Course Structure</h5> <p>Total units: 144</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants are required to have successfully completed a Bachelor qualification (AQF level 7) in nursing from a recognised tertiary education provider. Applicants who are Registered Nurses registered in Australia with the Australian Health Practitioner Regulation Agency (AHPRA) who do not have a Bachelor qualification may be considered for admission based on extensive industry experience and will require approval by the Program Leader.</li></ul>', `total_course_duration` = '1.5 years online/off-campus (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'Refer to UniSC website', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3974;
UPDATE `courses` SET `apply_form` = 'https://www.unisc.edu.au/study/courses-and-programs/bachelor-degrees-undergraduate-programs/bachelor-of-laws', `course_description` = '<h4>Course Information</h4> <p>Unleash your full potential and open doors to diverse legal career pathways with UniSCs Bachelor of Laws (LLB) degree. Become a master in courtroom advocacy, an expert in resolving community legal issues, or forge your own path, by choosing one of our unique specialised elective minors. Offering practical learning experiences and a comprehensive legal education, this degree covers all requirements for admission as a legal practitioner within Australia.</p> <h5>Course Structure</h5> <p>Total units: 288</p>', `total_course_duration` = '3 years flexible delivery (156 weeks)', `intakes` = '8 March 2027/ 12 July 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 3975;
