UPDATE `courses` SET `apply_form` = 'https://www.usc.edu.au/study/courses-and-programs/postgraduate-degrees/postgraduate-qualifying-pathway', `course_description` = '<h4>Course Information</h4> <p>Supercharge your ability to make a meaningful impact over the duration of your career. The Postgraduate Qualifying Pathway (PQP) is for international students who either require or would benefit from additional undergraduate study in English before entry to a UniSC postgraduate qualification.</p> <h5>Course Structure</h5> <p>Total units: 48</p>', `total_course_duration` = '6 months full-time (26 weeks)', `intakes` = 'Trimester 1,2', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4013;
