UPDATE `courses` SET `apply_form` = 'https://www.vit.edu.au/mba', `course_description` = '<h4>Course Information</h4> <p>VIT Master of Business Administration (MBA) is a Post-Graduate course at Australian Qualification Framework (AQF) Level 9. This prestigious course offers a substantial opportunity for those who want to succeed in the world of business. The Master of Business Administration (MBA) at VIT is designed for professional people like you who wish to expand their horizons as business leaders. This course prepares you to apply the skills and knowledge to your workplace</p> <h5>Course Structure</h5> <p>2 years (16 units) delivered Online.</p> <h5>Study & Career Pathways</h5> <p>Recognition of Prior Learning is available based on prior studies/experience at time of application - max 4 units).</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>a recognised Bachelor degree in Business or other discipline and/or 5+ years of supervisory and managerial experience.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS equivalence no band &lt; 6.0</li><li><strong>PTE Academic:</strong> PTE Academic: 48</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS equivalence no band &lt; 6.0</li><li><strong>PTE Academic:</strong> PTE Academic: 48</li></ul>', `enrolment_fee` = 275.0, `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'Weekly', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4079;
UPDATE `courses` SET `apply_form` = 'https://vit.edu.au/mba/gdba', `course_description` = '<h4>Course Information</h4> <p>We believe every professional deserves a fast track to leadership. GDBA offers practical, graduate-level business education designed for career changers or aspiring managers</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate III in Commercial Cookery</li><li>Age Requirement:Minimum 18 years of age at course commencement.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS Academic: Overall 6.5, with no band below 6 Academic Requirement: Certificate III in Commercial Cooke</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS Academic: Overall 6.5, with no band below 6 Academic Requirement: Certificate III in Commercial Cooke</li></ul>', `enrolment_fee` = 275.0, `total_course_duration` = '1 Year', `assessment_style` = 'assignment', `intakes` = 'Weekly', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4080;
UPDATE `courses` SET `apply_form` = 'https://vit.edu.au/mba/gcba', `course_description` = '<h4>Course Information</h4> <p>Start your business journey with confidence and clarity. GCBA offers core business skills and executive-level insight in a short, flexible course format — perfect for busy professionals.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate III in Commercial Cookery</li><li>Age Requirement:Minimum 18 years of age at course commencement.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS Academic: Overall score 6.5, with no band below 6 Academic Requirement: Certificate III in Commercial Cooke</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS Academic: Overall score 6.5, with no band below 6 Academic Requirement: Certificate III in Commercial Cooke</li></ul>', `enrolment_fee` = 275.0, `total_course_duration` = '6 Months', `assessment_style` = 'assignment', `intakes` = 'Weekly', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4081;
UPDATE `courses` SET `apply_form` = 'https://www.vit.edu.au/mits', `course_description` = '<h4>Course Information</h4> <p>VIT Master of Information Technology and Systems (MITS) is a Post-Graduate course at Australian Qualification Framework (AQF) Level 9. This prestigious Master of IT course offers a substantial opportunity for those who want to succeed in the world of Information Technology. The Master of Information Technology And Systems(MITS) at VIT is designed for people like you who want to enhance their career as an IT professional. The Master Of Information Technology course prepares you to take up senior IT positions in a wide variety of industries, such as Senior Software Engineer, Team Leader, Network Manager, Software Project Manager etc</p> <h5>Course Structure</h5> <p>2 years full time</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A recognised Bachelor Degree in Information Technology (for 4 units RPL credits) OR A recognised Bachelor Degree in any discipline An overseas recognised Bachelor Degree (recommended 4 years) is equivalent to Australian Qualifications Framework (AQF) Level 7</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS equivalence no band &lt; 6.0</li><li><strong>PTE Academic:</strong> PTE Academic: 48</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS equivalence no band &lt; 6.0</li><li><strong>PTE Academic:</strong> PTE Academic: 48</li></ul>', `enrolment_fee` = 275.0, `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'Weekly', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4082;
UPDATE `courses` SET `apply_form` = 'https://www.vit.edu.au/mits/gdits', `course_description` = '<h4>Course Information</h4> <p>The Graduate Diploma of Information Technology and Systems course at VIT offers a well-structured curriculum that combines theoretical knowledge with hands-on learning experiences to provide students with high-level IT skills required to work in various industry sectors.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Candidates with a recognised bachelors degree (AQF 7) in a discipline related to ICT, Computer Science or Software Engineering may apply for credit transfer/recognition of prior learning (CT/RPL) and possibly be granted exemption up to 24 credit points from foundation unit(s), thus completing the GDITS course by studying the 4 core units (total 24 credit points).; Candidates with a recognised bachelors degree (AQF 7) or above in any discipline other than ICT, Computer Science or Software Engineering, and preferably with a solid background in STEM areas such as science, technology, engineering or mathematics, will be admitted into the GDITS course and study 8 units (total 48 credit points), including the 4 foundation units and the 4 core units.; Candidates without a bachelors degree but with at least seven (7) years of relevant work experience may enrol in the Graduate Certificate of Information Technology and Systems (GCITS), and after successful completion of all four foundation units, such students can choose to continue study and enrol in the GDITS course.; Candidates with an Australian Advanced Diploma or Associate Degree or other tertiary study equivalent to AQF Level 6 and with at least three (3) years of relevant work experience may enrol in the Graduate Certificate of Information Technology and Systems (GCITS), and after successful completion of all four foundation units, such students can choose to continue study and enrol in the GDITS course.; Candidates who hold the Graduate Certificate of Information Technology and Systems (GCITS) from VIT or equivalent study from other recognised institutions may enrol in the GDITS course with credit exemptions of up to 24 credit points.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS equivalence no band &lt; 6.0</li><li><strong>PTE Academic:</strong> PTE Academic: 48</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS equivalence no band &lt; 6.0</li><li><strong>PTE Academic:</strong> PTE Academic: 48</li></ul>', `enrolment_fee` = 275.0, `total_course_duration` = '1 year online/off-campus (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'Weekly', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4083;
UPDATE `courses` SET `apply_form` = 'https://www.vit.edu.au/mits/gcits', `course_description` = '<h4>Course Information</h4> <p>The Graduate Certificate of Information Technology and Systems course at VIT offers a well-structured curriculum that combines theoretical knowledge with hands-on learning experiences for non-IT degree holders and is designed to provide students with the necessary foundation for key IT skills.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Candidates with a recognized bachelors degree (AQF 7) or above in any discipline other than ICT, Computer Science or Software Engineering, and preferably with good preparation in STEM areas such as science, technology, engineering or mathematics.; Candidates without a bachelors degree but with at least seven (7) years of relevant work experience may enrol in the GCITS course.; Candidates with an Australian Advanced Diploma or Associate Degree or other tertiary study equivalent to AQF Level 6 and with at least three (3) years of relevant work experience may enrol in the GCITS course.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS equivalence no band &lt; 6.0</li><li><strong>PTE Academic:</strong> PTE Academic: 48</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS equivalence no band &lt; 6.0</li><li><strong>PTE Academic:</strong> PTE Academic: 48</li></ul>', `enrolment_fee` = 275.0, `total_course_duration` = '6 months online/off-campus (26 weeks)', `assessment_style` = 'assignment', `intakes` = 'Weekly', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4084;
