UPDATE `courses` SET `apply_form` = 'https://www.vit.edu.au/vocational/cpc30220-certificate-iii-in-carpentry', `course_description` = '<h4>Course Information</h4> <p>This is a trade qualification for carpenters in residential and commercial workplaces. It includes setting out, manufacturing, constructing, assembling, installing and repairing products made using timber and non-timber materials. Occupational titles may include:Carpenter - Commercial Carpenter - FormworkCarpenter - Residential State and territory jurisdictions may have different licensing, legislative, regulatory or certification requirements. Relevant state and territory regulatory authorities should be consulted to confirm those requirements.This qualification is suitable for an Australian apprenticeship pathway.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate III in Commercial Cookery</li><li>Age Requirement:Minimum 18 years of age at course commencement.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS Academic: Overall 6.0, with no individual band below 5 Academic Requirement: Certificate III in Commercial Cooke</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS Academic: Overall 6.0, with no individual band below 5 Academic Requirement: Certificate III in Commercial Cooke</li></ul>', `enrolment_fee` = 275.0, `total_course_duration` = '104 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'Weekly', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4088;
