UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This course is designed for both aspiring managers and people currently employed in business or management. The Holmes MBA (Professional) has the clear objective of providing business education and skills to students to enable them to manage and lead in organisations in the digital age. The Holmes MBA (Professional) will enable you to critically examine problems and opportunities through a range of analytical frameworks.</p> <h5>Course Structure</h5> <p>7 Core Units; 8 Elective Units</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Bachelor degree or equivalent</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6</li></ul>', `enrolment_fee` = 250.0, `total_course_duration` = '104 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'March, July, November; March. July and November', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4210;
