UPDATE `courses` SET `apply_form` = 'https://tmice.edu.au/products/undergraduate-certificate-in-fashion-business?variant=31894158508075', `course_description` = '<h4>Course Information</h4> <p>Interested in the dynamic world of fashion but prefer business strategies over sketching designs? Our Undergraduate Certificate in Fashion Business is the best fit for you. This course will help you understand the many different roles in the fashion industry where you don&#x27;t need to be a designer. Roles in marketing, social media, merchandising and more are fun, creative and incredibly rewarding.</p>', `enrolment_fee` = 250.0, `total_course_duration` = '14 weeks online/off-campus', `assessment_style` = 'assignment', `intakes` = 'March, July, November; March. July and November', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4212;
