UPDATE `courses` SET `apply_form` = 'https://www.greenwichcollege.edu.au/cambridge-exam-preparation-courses/cpe-proficiency-english-preparation', `course_description` = '<h4>Course Information</h4> <p>Cambridge C2 Proficiency (CPE) is the most comprehensive English language qualification. C2 Proficiency shows that you have the native-speaker English-language skills sought by employers and organisations in language proficient careers - such as medicine and law. Recognised in Australia and around the world, C2 Proficiency shows you have the highest level of English.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>IELTS 8.0 or equivalent; Greenwich College Placement Test.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 8.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 8.0</li></ul>', `total_course_duration` = '4 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'Courses are offered twice a year', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4232;
