UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This course is designed to help you achieve your target score on the official IELTS test. Study alongside other students with the same goal, develop effective test-taking strategies through regular practice exams and become fully familiar with the IELTS test format.</p> <p>Build the confidence and skills you need to open global opportunities for study, work, or immigration.</p> <p>Learners who need an internationally recognised English test result</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate IV in Project Management Practice | BSB40920</li></ul>', `offshore_tuition_fee` = 11620.0, `total_course_duration` = '1 week full-time', `assessment_style` = 'assignment', `intakes` = '9/3/26, 4/5/26, 29/6/26, 24/8/26, 19/10/26; August, October; Classes are offered 3 times each year.; Classes commence every 4 weeks.; Classes commence every Monday.; Courses are offered twice a year; Courses start every 5 weeks.; Every 12 weeks.; Eve', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4223;
