UPDATE `courses` SET `apply_form` = 'https://greenwichcollege.edu.au/cambridge-exam-preparation-courses/first-certificate-in-english-fce-course/', `course_description` = '<h4>Course Information</h4> <p>Build on the core English skills you learnt inCambridge English: A2 Key (KET)andCambridge English: B1 Preliminary (PET)to extend your vocabulary, convey more abstract themes, and write more complex pieces to operate more confidently and naturally in an English-speaking environment.</p> <p>Upon completing your Cambridge English: B2 First (FCE) course you can continue your studies withCambridge English: C1 Advanced (CAE)</p> <p>Gain a higher result in your final examination with FREE classes and test practice including:- Weekly test practice to reinforce learning and check progress- 6 hours of ‘Cambridge Club’ classes per course, to refine examination skills- Regular one-on-one academic counselling, so you know where to focus your efforts.</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6</li></ul>', `offshore_tuition_fee` = 4980.0, `total_course_duration` = '12 weeks full-time', `assessment_style` = 'mixed', `intakes` = 'Every 12 weeks.', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4229;
