UPDATE `courses` SET `apply_form` = 'https://wincollege.edu.au/courses/english-teaching/11020nat-diploma-of-english-language-teaching-tesol/', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate IV in Project Management</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 5.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 5.5</li></ul>', `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'Weekly intakes', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4277;
