UPDATE `courses` SET `apply_form` = 'https://www.warwick.edu.au/cpp41419-certificate-iv-in-real-estate-practice/', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of real estate professionals who apply knowledge of real estate practice legal agency and compliance requirements, ethical standards and consumer preferences to conduct real estate functions. This qualification applies to people working in both residential and commercial property, including business broking, and stock and station transactions.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate IV in Real Estate Practice</li></ul>', `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'July, October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4357;
UPDATE `courses` SET `apply_form` = 'https://www.warwick.edu.au/cpp51119-diploma-of-property-agency-management/', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of property services principals who apply knowledge of property agency and compliance requirements, ethical standards and consumer preferences to establish and control property services functions.</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 5.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 5.5</li></ul>', `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'July, October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4358;
