UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of individuals in a range of community settings and peoples&#x27; homes, who provide support in a manner that empowers people with disabilities to achieve greater levels of independence, self-reliance, community participation and wellbeing. Workers promote a person-centred approach, work according to and may contribute to an individualised plan, and work without direct supervision. They may be required to supervise and/or coordinate a small team.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Completion of: CHC33021 Certificate III in Individual Support (Disability)ORCompletion of: CHC33015 Certificate III in Individual Support (Disability)ORCompletion of: CHC30408 Certificate III in Disability PLUS the CHCSS00125 Entry to Certificate IV in Disability Support Skill Set.</li></ul>', `total_course_duration` = '48 weeks full-time', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4454;
