UPDATE `courses` SET `apply_form` = 'https://apicollege.edu.au/courses/graduate-diploma-in-project-management-graddippm/', `course_description` = '<h4>Course Information</h4> <p>This course is designed to broaden the skills already gained in relevant undergraduate programs and/or in the Graduate Certificate in Project Management course, and to impart further specialisation in the discipline of project management as well as enhancement of professional skills and attitude in this field.</p> <h5>Designed For</h5> <p>Aspiring project managers</p> <h5>Course Structure</h5> <p>7 units: 4 core units plus either 2 secondary core units or 1 secondary core unit and 1 elective. Areas of study include project management in industries including Construction and Infrastructure; IT and Services; Manufacturing and Production; Mining; Energy; and Processing.</p> <h5>Study & Career Pathways</h5> <p>Pathways include Master of Business and Project Management; MBA (Project and Program Management)</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Relevant bachelor degree; diploma or advanced diploma or equivalent plus relevant industry experience also considered</li></ul>', `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'Feb, Jun, Sep', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4491;
