UPDATE `courses` SET `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: overall band score of 6.0</li><li><strong>PTE Academic:</strong> PTE Academic Module with a minimum score of 50</li><li><strong>TOEFL iBT:</strong> TOEFL overall score of 65</li></ul>', `assessment_style` = 'assignment', `intakes` = 'Feb, Jun, Sep', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4500;
UPDATE `courses` SET `apply_form` = 'https://apicollege.edu.au/courses/master-of-information-technology/', `course_description` = '<h4>Course Information</h4> <p>The Master of Information Technology (MIT) is designed to enable those with a degree in non IT areas to develop skills and knowledge that will allow them to enter the field of information technology. Students entering the Master of Information Technology from cognate bachelor degrees (e.g. bachelor degree in IT or Computer Science) are eligible for potential unit substitution for one or more of the foundational units within the course.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants must have successfully completed a Bachelor’s degree (AQF 7) or higher, awarded by a recognised university or higher education institution, in any discipline OR Applicants who have completed a postgraduate preparation program.</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'Feb, Jun, Sep', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4501;
