UPDATE `courses` SET `apply_form` = 'https://spencercollege.edu.au/courses/general-english-course/', `course_description` = '<h4>Course Information</h4> <p>The General English Course at Spencer College is designed to help students develop confidence and fluency in everyday English communication. Whether you are a complete beginner or preparing for advanced study, this course provides the language skills needed for academic, professional, and social success in an English-speaking environment.\r\nOur program is delivered from Elementary to Upper-Intermediate (Levels 1-5), allowing students to progress smoothly through each stage of language development. Classes focus on real-life communication, pronunciation, vocabulary, grammar, reading, writing, listening, and speaking skills.</p>', `assessment_style` = 'mixed', `intakes` = 'Ongoing intakes', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5960;
