UPDATE `courses` SET `apply_form` = 'https://cac.edu.au/certificate-iv-in-automotive-mechanical-diagnosis/', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of individuals who perform advanced diagnostic tasks in the automotive retail, service and repair industry.</p> <h5>Course Structure</h5> <p>1 core unit plus 9 electives.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Those undertaking the Certificate IV in Automotive Mechanical Diagnosis must have completed an automotive mechanical Certificate III qualification, or be able to demonstrate equivalent competency.No licensing, legislative or certification requirements apply to this qualification at the time of publication.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS (Academic or General Training) 6.0</li><li><strong>PTE Academic:</strong> Pearson Test of English (PTE) Academic 47</li><li><strong>TOEFL iBT:</strong> TOEFL iBT 67</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS (Academic or General Training) 6.0</li><li><strong>PTE Academic:</strong> Pearson Test of English (PTE) Academic 47</li><li><strong>TOEFL iBT:</strong> TOEFL iBT 67</li></ul>', `total_course_duration` = '26 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'Jan, April, July and Oct; Monthly Intake', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4624;
UPDATE `courses` SET `apply_form` = 'https://cac.edu.au/diploma-of-automotive-management/', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of individuals who undertake leadership and management roles in the automotive industry. It is suitable for entry into senior management roles in all sectors of the automotive industry.</p> <h5>Course Structure</h5> <p>12 units: 6 core; 6 elective</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS (Academic or General Training) 6.0</li><li><strong>PTE Academic:</strong> Pearson Test of English (PTE) Academic 47</li><li><strong>TOEFL iBT:</strong> TOEFL iBT 67</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS (Academic or General Training) 6.0</li><li><strong>PTE Academic:</strong> Pearson Test of English (PTE) Academic 47</li><li><strong>TOEFL iBT:</strong> TOEFL iBT 67</li></ul>', `total_course_duration` = '52 weeks full-time, 1 year full-time (52 weeks), 1.5 years part-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'Jan, April, July and Oct; Monthly Intake', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4625;
UPDATE `courses` SET `apply_form` = 'https://cac.edu.au/diploma-of-automotive-technology/', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of individuals who diagnose, analyse, evaluate, design and modify vehicle systems in the automotive retail, service and repair industry.</p> <h5>Course Structure</h5> <p>12 units: 1 core; 11 elective</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Those undertaking the Diploma of Automotive Technology must have completed an automotive Certificate IV qualification in one of the following disciplines, or be able to demonstrate equivalent competency.AUR40216 Certificate IV in Automotive Mechanical DiagnosisAUR40816 Certificate IV in Automotive Mechanical OverhaulingNo licensing, legislative or certification requirements apply to this qualification at the time of publication.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6</li></ul>', `total_course_duration` = '26 weeks full-time, 1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'Jan, April, July and Oct; Monthly Intake', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 4626;
