UPDATE `courses` SET `apply_form` = 'https://trinityinstitute.edu.au/courses/automotive/aur32721-certificate-iii-in-automotive-electric-vehicle-technology/', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of individuals who service, diagnose and repair battery electric vehicles and components in the automotive, service and repair industry who carry out work according to Australian Standards (AS) 5732 Electric vehicle operations - Maintenance and repair. Licensing, legislative, regulatory or certification considerationsLicensing, legislative and certification requirements may apply to this qualification but vary between states, territories and industry sectors. Licensing requirements relating to handling refrigerants are governed by the Australian Refrigeration Council.Users are advised to check with the relevant state/territory jurisdiction or industry body for current requirements.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate III in Light Vehicle Mechanical Technology</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS academic score of 6.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS academic score of 6.0</li></ul>', `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'January, February, April, May, June', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5164;
