UPDATE `courses` SET `apply_form` = 'https://ikon.edu.au/bachelor-of-arts-therapy/', `course_description` = '<h4>Course Information</h4> <p>The Bachelor of Arts Therapy is designed to provide graduates with a broad body of knowledge relating to the field of arts therapy, with emphasis on the underlying principles and concepts of art making processes. A feature of the course is the focus on experiential small-group learning that supports students to develop and practice their skills and knowledge in a safe supportive environment.</p> <h5>Course Structure</h5> <p>Students are required to successfully complete 23 subjects (144 credit points) to be eligible for the award of Bachelor Arts Therapy. The course structure includes two placement experiences.</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `total_course_duration` = '3 years full-time (156 weeks), 3 years online/off-campus (156 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, May, September', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5176;
UPDATE `courses` SET `apply_form` = 'https://ikon.edu.au/bachelor-of-counselling-and-psychotherapy/', `course_description` = '<h4>Course Information</h4> <p>The Bachelor of Counselling and Psychotherapy is designed to provide graduates with a broad and coherent body of knowledge relating to the field of counselling and psychotherapy, with an emphasis on embedding a conceptual framework and model of psychotherapeutic practice for the</p> <h5>Course Structure</h5> <p>Students are required to successfully complete 23 subjects (144 credit points) to be eligible for the award of Bachelor of Counselling and Psychotherapy. The course structure includes two placement experiences.</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `total_course_duration` = '3 years full-time (156 weeks), 3 years online/off-campus (156 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, May, September', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5177;
UPDATE `courses` SET `apply_form` = 'https://ikon.edu.au/diploma-of-arts-therapy/', `course_description` = '<h4>Course Information</h4> <p>The Diploma of Arts Therapy is a higher education diploma where you will study the significance of arts marking process and symbolic expression for healing outcomes. Arts therapy is effective in engaging people who may struggle to participate in more traditional</p> <h5>Course Structure</h5> <p>Students are required to successfully complete 8 subjects (48 credit points) to be eligible for the award of Diploma Arts Therapy.</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 1 year online/off-campus (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, May, September', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5178;
