UPDATE `courses` SET `apply_form` = 'https://www.ahmi.edu.au/Home/certificate-IV-in-kitchen-management', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of chefs and cooks who have a supervisory or team leading role in the kitchen. They operate independently or with limited guidance from others and use discretion to solve non-routine problems.This qualification provides a pathway to work in organisations such as restaurants, hotels, clubs, pubs, cafes and coffee shops, or to run a small business in these sectors.The skills in this qualification must be applied in accordance with Commonwealth and State or Territory legislation, Australian standards and industry codes of practice.No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate III in Carpentry</li><li>Age Requirement:Minimum 18 years of age at course commencement.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS Academic 6.0 no band below 5 Academic Requirement: Certificate III in Carpentry Age Requirement: Minimum 18 years of age at course commencement</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS Academic 6.0 no band below 5 Academic Requirement: Certificate III in Carpentry Age Requirement: Minimum 18 years of age at course commencement</li></ul>', `enrolment_fee` = 300.0, `materials_fee` = 300.0, `total_course_duration` = '78 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'January, April, July, October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5210;
