UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of individuals in a variety of Business Services job roles. These individuals may have general management accountabilities.Individuals in these roles carry out complex tasks in a specialist field of expertise. They may undertake technical research and analysis, and will often contribute to setting the strategic direction for a work area.The qualification is suited to individuals who are responsible for the supervision and leadership of a team or work area (including by managing staff performance and making staffing decisions).Licensing/Regulatory InformationNo licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Entry to this qualification is limited to those who:Have completed a Diploma or Advanced Diploma from the BSB Training Package (current or superseded equivalent versions).orHave two years equivalent full-time relevant workplace experience in an operational or leadership role in an enterprise.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic 6.0 no band below 5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic 6.0 no band below 5</li></ul>', `enrolment_fee` = 300.0, `materials_fee` = 300.0, `assessment_style` = 'assignment', `intakes` = 'Jan, Apr, July, Oct', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 6003;
