UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of support workers who complete specialised tasks and functions in aged services; either in residential, home or community based environments. Workers will take responsibility for their own outputs within defined organisation guidelines and maintain quality service delivery through the development, facilitation and review of individualised service planning and delivery.  Workers may be required to demonstrate leadership and have limited responsibility for the organisation and the quantity and quality of outputs of others within limited parameters.To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p> <h5>Course Structure</h5> <p>18 units: 15 core; 3 elective</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate III, IV, and Diploma levels, recognized within the Australian Qualifications Framework (AQF)</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS* score of 6.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS* score of 6.0</li></ul>', `offshore_tuition_fee` = 11900.0, `enrolment_fee` = 200.0, `materials_fee` = 1000.0, `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'January, February, March, April, May, June, July, August, September, October, November', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5428;
