UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>The Bachelor of Business (BB) at AIBI Higher Education gives students a strong foundation in essential business skills and strategies. Students will be able to apply their knowledge to real-life scenarios and projects taught by experienced academics and industry professionals. This course prepares graduates to navigate and succeed in a wide range of business environments.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 Completion (or equivalent). Requirements differ per country.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: 6.0 Overall no band less than 5</li><li><strong>PTE Academic:</strong> PTE: 52 Overall (no band less than 50, or equivalent)</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: 6.0 Overall no band less than 5</li><li><strong>PTE Academic:</strong> PTE: 52 Overall (no band less than 50, or equivalent)</li></ul>', `total_course_duration` = '3 years full-time (156 weeks), 6 years part-time (312 weeks)', `assessment_style` = 'assignment', `intakes` = 'March 2, 2026', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5470;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>The Bachelor of Enterprise Management Systems (BEMS) at AIBI Higher Education teaches students how to choose, set up, and manage systems that improve business processes and data analysis. With a focus on practical skills using industry-standard software and real-world case studies, this degree prepares graduates for a range of roles in different sectors.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 Completion (or equivalent). Requirements differ per country.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>PTE Academic:</strong> PTE: 52 Overall (no band less than 50, or equivalent)</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>PTE Academic:</strong> PTE: 52 Overall (no band less than 50, or equivalent)</li></ul>', `total_course_duration` = '3 years full-time (156 weeks), 6 years part-time (312 weeks)', `assessment_style` = 'assignment', `intakes` = 'March 2, 2026', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5471;
