UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This qualification describes the skills and knowledge for supervisory/managerial job roles in the production horticulture industry including grower, field manager, supervisor, crop grower, plant manager, integrated pest manager, quality assurance, compliance manager and human resources manager.Individuals with this qualification perform tasks involving technical skills, problem solving and supervisory skills to operate, monitor and improve performance of production horticulture systems and may supervise staff.Work must comply with work health and safety and environmental regulations and legislation that apply to the workplace.No licensing, legislative or certification requirements apply to this qualification at the time of publication.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate IV in Kitchen Management</li></ul>', `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'July, September', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5488;
