UPDATE `courses` SET `apply_form` = 'https://reachcollege.edu.au/courses/hospitality/diploma-of-hospitality-management/', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of highly skilled senior operators who use a broad range of hospitality skills combined with managerial skills and sound knowledge of industry to coordinate hospitality operations. They operate independently, have responsibility for others and make a range of operational business decisions.This qualification provides a pathway to work in any hospitality industry sector as a departmental or small business manager. The diversity of employers includes restaurants, hotels, motels, catering operations, clubs, pubs, caf\\u00e9s, and coffee shops. This qualification allows for multiskilling and for acquiring targeted skills in accommodation services, cookery, food and beverage and gaming.The skills in this qualification must be applied in accordance with Commonwealth and State/Territory legislation, Australian standards and industry codes of practice.No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate III in Individual Support (Ageing)</li><li>Age Requirement:Minimum 18 years of age at course commencement.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 6.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 6.0</li></ul>', `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'January, February, March, April, May, June, July, August, September, October, November, December', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5900;
UPDATE `courses` SET `apply_form` = 'https://reachcollege.edu.au/courses/hospitality/advanced-diploma-of-hospitality-management/', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of highly skilled senior managers who use a broad range of hospitality skills combined with specialised managerial skills and substantial knowledge of industry to coordinate hospitality operations. They operate with significant autonomy and are responsible for making strategic business management decisions.This qualification provides a pathway to work in any hospitality industry sector and for a diversity of employers including restaurants, hotels, motels, catering operations, clubs, pubs, caf\\u00e9s, and coffee shops. This qualification allows for multi-skilling and for acquiring targeted skills in accommodation services, cookery, food and beverage and gaming.The skills in this qualification must be applied in accordance with Commonwealth and State/Territory legislation, Australian standards and industry codes of practice.No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate III in Individual Support (Ageing)</li><li>Age Requirement:Minimum 18 years of age at course commencement.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 6.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 6.0</li></ul>', `total_course_duration` = '104 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'January, February, March, April, May, June, July, August, September, October, November, December', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5901;
