UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>The MSW has a minimum academic entry requirement of a bachelors degree (AQF level 7) with at least 8 units in the social and behaviour sciences, or equivalent for international students, as required by the AASW.; The MSW also has inherent requirements which are academic and non-academic requirements that are essential to the successful completion of a course.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic score of 7.0 overall, with no band less than 7</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic score of 7.0 overall, with no band less than 7</li></ul>', `assessment_style` = 'assignment', `intakes` = 'February, May and September', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5557;
