UPDATE `courses` SET `apply_form` = 'https://hic.edu.au/sit60322-advanced-diploma-hospitality-management/', `course_description` = '<h4>Course Information</h4> <p>Face-to-Face classroom-based learning | Practical Training and Assessment at the HIC Kitchen | Work-Based Training</p> <p>Area Manager | Operations Manager | Cafe Owner or Manager | Food and Beverage Manager | Motel Owner or Manager</p> <p>This qualification reflects the role of highly skilled senior managers who use a broad range of hospitality skills combined with specialised managerial skills and substantial knowledge of industry to coordinate hospitality operations. They operate with significant autonomy and are responsible for making strategic business management decisions.This qualification provides a pathway to work in any hospitality industry sector and for adiversity of employers including restaurants, hotels, motels, catering operations, clubs, pubs, cafés, and coffee shops.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>CERTIFICATE IV IN KITCHEN MANAGEMENT</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS: Overall band score of 6.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS: Overall band score of 6.0</li></ul>', `materials_fee` = 500.0, `total_course_duration` = '26 weeks', `assessment_style` = 'assignment', `intakes` = 'Main intake dates occur in January, April, July and October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5569;
