UPDATE `courses` SET `apply_form` = 'https://npa.edu.au/general-english/', `course_description` = '<h4>Course Information</h4> <p>Taking the General English (Level 1 to Level 5) Course will improve your English proficiency and you will receive a certificate detailing your level and duration of study.</p> <p>The entry level of General English (Level 1 to Level 5) Course and the approximate number of weeks required to achieve an English proficiency (IELTS Scores are an approximation) are shown below.</p> <p>International students should meet the English requirement of a minimum of IELTS 6.0 or equivalent.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate III</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 6.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 6.0</li></ul>', `total_course_duration` = '1 week full-time', `intakes` = 'Any Monday', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 5699;
