UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Designed for students with a first qualification in a discipline other than education, this course orientates you to the education discipline and provides you with an understanding of concepts and contemporary issues in education and of educational contexts and systems, locally and globally. You will have the opportunity to draw on a range of support mechanisms as you develop your knowledge and understanding of the major theoretical and professional debates in specialist areas within the field of education, and locate these within contemporary research. Completion of this course will position you to pursue education related careers and/or further study in education.</p> <h5>Course Structure</h5> <p>Total 24 Credit Points</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL: 79</li></ul>', `total_course_duration` = '6 months full-time (26 weeks), 6 months online/off-campus (26 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 9791;
