UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Entry Level 1:; An Australian bachelor degree (or equivalent) in a non cognate discipline with at least a Weighted Average Mark (WAM) of 60% or qualification and experience approved by the faculty.; Entry Level 2:; One of the following with a Weighted Average Mark (WAM) of at least 60% or; An Australian bachelor degree (or equivalent) in a relevant discipline with at least a Weighted Average Mark (WAM) of 60% and a minimum of two years of relevant work experience.; Entry Level 3:; An Australian Master of Philosophy or PhD or doctoral degree or AQF level 9 qualifications (or equivalent) in a cognate discipline and a minimum of two years of relevant work experience. or; An Australian bachelor degree (or equivalent) in a cognate discipline and a minimum of two years of relevant work experience and; Part 1 of a specialist medical training program or current Fellowship of a specialist medical college recognised by the Medical Board of Australia and; current registration with AHPRA or equivalent registration approved by the faculty.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 79</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 79</li></ul>', `total_course_duration` = '2 years full-time (104 weeks), 1 year online/off-campus (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 9802;
