UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A bachelor&#x27;s degree (or equivalent) in a relevant discipline (see below), or a bachelor&#x27;s degree (or equivalent) in any discipline, plus 1 year, full-time equivalent relevant work experience in a healthcare setting.; or a graduate certificate or graduate diploma (or equivalent) in a relevant discipline (see below).</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 87</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 87</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `intakes` = 'Semester 1 (23/02/2026), Semester 2 (27/06/2026)', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 9868;
UPDATE `courses` SET `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS overall 6.5</li><li><strong>PTE Academic:</strong> PTE Academic - Overall Score of 64</li><li><strong>TOEFL iBT:</strong> TOEFL iBT (including Paper Edition) - Overall 87, listening 19, reading 19, writing 21 and speaking 19</li></ul>', `assessment_style` = 'assignment', `intakes` = 'Semester 1 (23/02/2026), Semester 2 (27/06/2026)', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 9869;
UPDATE `courses` SET `apply_form` = 'https://study.uq.edu.au/study-options/programs/doctor-philosophy-7501', `course_description` = '<h4>Course Information</h4> <p>With the guidance of an advisory team, you will undertake a research project, produce an 80,000-word thesis and complete an oral examination. A PhD takes 3 to 4 years full-time. Under guidance, you will develop advanced research skills and knowledge in your chosen field. The thesis is a substantial document that makes an original contribution to your field of research. Your thesis may involve an alternate format. You will need a strong academic background and you may need to submit a research proposal and other documents to support your application. About 1,000 PhD candidates join UQ each year researching a wide range of topics.</p> <h5>Course Structure</h5> <p>48 units</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li></ul>', `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'mixed', `intakes` = '23-Feb-26; Semester 1 (02/02/2026); Semester 1 (22 Feb, 2027), Semester 2 (26 Jul, 2027); Semester 1 (22/02/2027); Semester 1 (22/02/2027); Semester 2 (26/07/2027); Semester 1 (23 Feb, 2026); Semester 1 (23 Feb, 2026), Semester 2 (27 Jul, 2026); Seme', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 9870;
