UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Develop the core communication skills required to become an effective communicator across health and medicine, public affairs, public relations, community relations and journalism. This degree is designed for aspiring and experienced communicators, health advocates, public relations specialists, media experts, and healthcare professionals.</p> <h5>Course Structure</h5> <p>Credit points 72</p>', `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 9959;
UPDATE `courses` SET `apply_form` = 'https://www.sydney.edu.au/courses/courses/pc/graduate-diploma-in-health-communication.html', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Admission to candidature for the Graduate Diploma in Health Communication requires:; a bachelors degree from the University of Sydney with a minimum 60% average calculated over the whole degree, including a major in a relevant subject area in the humanities, social sciences or public health, or an equivalent qualification or; completion of the requirements for the Graduate Certificate in Health Communication with a minimum credit (65%) average, or an equivalent qualification.</li></ul>', `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 9960;
UPDATE `courses` SET `apply_form` = 'https://www.sydney.edu.au/courses/courses/pc/graduate-certificate-in-health-communication.html', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Admission to the course requires:; a bachelors degree from the University of Sydney or an equivalent qualification or; equivalent professional experience of no less than three years in a relevant field such as communications/media research, public relations, social/cause related marketing or health promotion.</li></ul>', `total_course_duration` = '6 months full-time (26 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 9961;
