UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Our Master of Cancer and Haematology Nursing aims to assist nurses who care for people affected by cancer and haematological illness to develop their knowledge and skills for their care. Students will investigate the biology of cancer and haematology and associated treatments. Our Master of Cancer and Haematology Nursing is designed for Registered Nurses caring for patients the in cancer and haematology field to expand their knowledge, clinical capability and clinical research ability to advance their practice and improves outcomes for their patients.</p> <h5>Course Structure</h5> <p>Credit points 60</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Admission to this course requires:; a pre registration nursing degree with credit average from the University of Sydney or equivalent qualification or; an embedded graduate certificate or graduate diploma in this discipline from the University of Sydney or equivalent qualification.</li></ul>', `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 9971;
UPDATE `courses` SET `apply_form` = 'https://www.sydney.edu.au/courses/courses/pc/master-of-emergency-nursing.html', `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 9972;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Our course aims to provide nurses with sound theoretical underpinning of clinical practice skills to deliver comprehensive care and advice to critically ill patients and their families, as well as work across complex medical environments that demand rapid, advanced and challenging decision making. Our Master of Intensive Care Nursing is designed for registered nurses working in the intensive care environment who are looking to become an expert and advance to clinical leadership roles or build professional practice capabilities.</p> <h5>Course Structure</h5> <p>Credit points 60</p>', `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 9973;
