UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A candidate for the degree shall have been awarded an appropriate Bachelor degree with Honours from the University of New South Wales or a qualification considered equivalent to the above from another university or tertiary institution.; A candidate for the degree shall have been awarded an appropriate coursework Master degree which includes a substantial research component from the University of New South Wales or a qualification considered equivalent to the above from another university or tertiary institution.; Candidates may be admitted to the PhD program after one years full-time enrolment in a Masters by Research program, with the approval of the Faculty Higher Degree Committee.; In exceptional cases an applicant who submits evidence of such other academic and professional qualifications as may be approved by the Committee may be permitted to enrol for the degree.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>TOEFL iBT:</strong> TOEFL iBT: 90 overall</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>TOEFL iBT:</strong> TOEFL iBT: 90 overall</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '3 years full-time (156 weeks)', `assessment_style` = 'mixed', `intakes` = 'Term 1; Term 1 and 2; Term 1 and 3; Term 1, 2 and 3; Term 1, Term 2, Term 3, Summer Term', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10070;
