UPDATE `courses` SET `apply_form` = 'https://handbook.unsw.edu.au/research/programs/2025/1851?year=2025', `course_description` = '<h4>Course Information</h4> <p>The Doctor of Philosophy (PhD) program is recognition of successful research experience. This degree requires an original and significant contribution to knowledge in an approved area. The degree requires a minimum of 3 years full-time study and preparation of a thesis.</p> <h5>Course Structure</h5> <p>Students must complete 144 UOC when taken as a standalone program.</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>TOEFL iBT:</strong> TOEFL iBT: 90 overall</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '3 years full-time (156 weeks)', `assessment_style` = 'assignment', `intakes` = 'Term 1; Term 1 and 2; Term 1 and 3; Term 1, 2 and 3; Term 1, Term 2, Term 3, Summer Term', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10072;
