UPDATE `courses` SET `apply_form` = 'https://www.unsw.edu.au/study/postgraduate/master-of-public-health-health-leadership-and-management?studentType=international', `course_description` = '<h4>Course Information</h4> <p>This program is widely recognised as essential for a career in population health, including health promotion, primary health care, policy formulation, research, and management of health programs. It has been designed to provide students with the essential knowledge, skills and attributes required for senior managerial roles in health service delivery.</p> <h5>Designed For</h5> <p>Health professions and those seeking roles in public health; managers or those seeking management roles in health services</p> <h5>Course Structure</h5> <p>72 units of credit (UOC): 7 core courses (42 UOC) including: Health Promotion and Social Perspectives in Health; Foundations in Public Health and Health Care Systems; Strategy Policy and Change; Healthcare Economics and Financial Management; Epidemiology and Statistics for Public Health; Health Leadership and Workforce Management; Clinical Governance and Risk Management and 5 electives (30 UOC).</p> <h5>Study & Career Pathways</h5> <p>Master of Public Health, Master of Health Management</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>PTE Academic:</strong> PTE Academic: 58 overall min</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>PTE Academic:</strong> PTE Academic: 58 overall min</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '1.7 years flexible delivery (88.39999999999999 weeks)', `assessment_style` = 'assignment', `intakes` = 'Term 1; Term 1 and 2; Term 1 and 3; Term 1, 2 and 3; Term 1, Term 2, Term 3, Summer Term', `updated_at` = '2026-1