UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent; assumed knowledge: Mathematics and Chemistry. Recommended Knowledge: One of Biology, Earth and Environmental Science, Physics.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>PTE Academic:</strong> PTE Academic: 58 overall min</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>PTE Academic:</strong> PTE Academic: 58 overall min</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '3 years flexible delivery (156 weeks)', `assessment_style` = 'assignment', `intakes` = 'Term 1, 2 and 3', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10112;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This dual degree program qualifies students for two degrees leading to the award of the degrees Bachelor of Environmental Management and Bachelor of Arts. This dual degree will provide students with a strong education in the skills and knowledge necessary to work or carry out research as an environmental scientist, as well as enabling students to complete a degree in the Arts field. It is ideal for those interested in combining their interest in environmental management with studies in the Arts.</p> <h5>Course Structure</h5> <p>Students take 120 units of credit core (UOC) of the Bachelor of Environmental Management program and 96 units of credit core (UOC) of the Bachelor of Arts program, for a total of 216 UOC.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent; Assumed knowledge: Mathematics, Chemistry. Recommended Knowledge: Biology, Earth and Environmental Science, Physics.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>PTE Academic:</strong> PTE Academic: 58 overall min</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>PTE Academic:</strong> PTE Academic: 58 overall min</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '4.7 years flexible delivery (244.4 weeks)', `assessment_style` = 'assignment', `intakes` = 'Term 1; Term 1 and 2; Term 1 and 3; Term 1, 2 and 3; Term 1, Term 2, Term 3, Summer Term', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10113;
