UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>A recognised Bachelor degree and a postgraduate teaching qualification (e.g. Graduate Diploma of Education or Master of Teaching). OR a four year pre-service teacher education qualification, including professional experience, equivalent to the qualifications required for Graduate teacher status in NSW.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>PTE Academic:</strong> PTE Academic: 58 overall min</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>PTE Academic:</strong> PTE Academic: 58 overall min</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '1 year flexible delivery (52 weeks), 2 years part-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'Term 1, 2 and 3', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10141;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>The Master of Science in Health Data Science will prepare you to find the right data, unlock hidden insights and use this information to better support clinical care, inform health policy and improve population health.  The two-year Master of Science in Health Data Science (Extension) builds upon this, offering an opportunity to dive deeper into different aspects and applications of Health Data Science through a research dissertation or a work placement. This research can involve analysing big data to solve health issues or involve the development of health-related data driven application. You</p> <h5>Course Structure</h5> <p>The Master of Science in Health Data Science (Extension) can be completed in two years of full-time study or four years part-time.</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>PTE Academic:</strong> PTE Academic: 58 overall min</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '2 years flexible delivery (104 weeks), 4 years part-time (208 weeks)', `assessment_style` = 'assignment', `intakes` = 'Term 1 and 3', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10142;
