UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Candidates are in general considered eligible if they have:; A four year degree of Bachelor with first or upper second class Honours in a relevant discipline from UNSW, or with an MBBS from an Australian or New Zealand university; A Masters by Research or Masters of Philosophy from UNSW with a substantial research component and demonstrated capacity for timely completion of a high quality research thesis; A qualification from a tertiary institution and research or publication experience at a level considered equivalent by the Committee to criteria 1 or 2.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>TOEFL iBT:</strong> TOEFL iBT: 90 overall</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: 6.5 overall</li><li><strong>TOEFL iBT:</strong> TOEFL iBT: 90 overall</li></ul>', `enrolment_fee` = 150.0, `total_course_duration` = '3 years full-time (156 weeks)', `assessment_style` = 'assignment', `intakes` = 'Term 1; Term 1 and 2; Term 1 and 3; Term 1, 2 and 3; Term 1, Term 2, Term 3, Summer Term', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10155;
