UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Bachelor of Communication in Creative Writing Master of Teaching in Secondary Education</li><li>In the Bachelor of Communication in Creative Writing component, you’ll complete 96 credit points of disciplinary content comprising of 18 credit points of Communication core subjects, a 48 credit point Creative Writing stream, a 6 credit point core literary subject and 24 credit points of either Society and Culture subjects or electives.</li><li>The outline below shows an example program for the Bachelor of Communication (Writing and Publishing) Master of Teaching in Secondary Education based on a full-time study load. Please note that your exact program may differ based on your unique circumstances, such as your commencement date, subject selections and recognition of prior learning.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: overall 7.5, listening 8</li><li><strong>PTE Academic:</strong> PTE: overall 73, listening 79, speaking 79, reading 65, writing 65</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic: overall 7.5, listening 8</li><li><strong>PTE Academic:</strong> PTE: overall 73, listening 79, speaking 79, reading 65, writing 65</li></ul>', `total_course_duration` = '208 weeks', `assessment_style` = 'assignment', `intakes` = 'Autumn Session, 2026; Autumn Session, 2026, Spring Session, 2026; Autumn Session, Spring Session; July; July, August, October; September Session; Spring Session; Spring Session and December Session; Spring Sessions and Summer Session', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10199;
