UPDATE `courses` SET `apply_form` = 'https://www.uow.edu.au/study/courses/master-of-occupational-health-and-safety-extension/', `course_description` = '<h4>Course Information</h4> <p>The Master of Occupational Health and Safety Extension provides students with an integrated teaching and research program, with the objective of promoting the highest level of safety, inspiring the next generation of professionals. This extension degree provides you with an opportunity to focus on health promotion or occupational health and safety (OH&amp;S) research, enabling you to address complex workplace OH&amp;S issues through specialised technical knowledge and application.</p>', `total_course_duration` = '2 years full-time (104 weeks)', `intakes` = 'Autumn 2026; Autumn 2026\nSpring 2026\nSummer 2026/2027 2026; Autumn 2026, NURS Autumn A 2026, NURS Spring A 2026; Autumn 2026, Spring 2026; Autumn 2026, Spring 2026, Summer 2026/2027; February, June and September; Jan 2027 Intake: 03 Aug 2026 to 26 Oc', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10201;
UPDATE `courses` SET `apply_form` = 'https://www.uow.edu.au/study/courses/master-of-occupational-health-and-safety/', `course_description` = '<h4>Course Information</h4> <p>The Master of Occupational Health and Safety provides students with an integrated teaching and research program, with the objective of promoting the highest level of safety and inspiring the next generation of Occupational Health and Safety (OH&amp;S) professionals. This degree has been developed in conjunction with industry to address the complex nature of occupational health and safety in the workplace.</p>', `total_course_duration` = '1.5 years flexible delivery (78 weeks)', `intakes` = 'Autumn 2026; Autumn 2026\nSpring 2026\nSummer 2026/2027 2026; Autumn 2026, NURS Autumn A 2026, NURS Spring A 2026; Autumn 2026, Spring 2026; Autumn 2026, Spring 2026, Summer 2026/2027; February, June and September; Jan 2027 Intake: 03 Aug 2026 to 26 Oc', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10202;
UPDATE `courses` SET `apply_form` = 'https://www.uow.edu.au/study/courses/graduate-diploma-in-occupational-health-and-safety/', `course_description` = '<h4>Course Information</h4> <p>The Graduate Diploma in Occupational Health and Safety (OH&amp;S) is a course for students holding an undergraduate degree or graduate certificate in either OH&amp;S or Occupational Hygiene. This degree was developed with industry to address the complex nature of occupational health and safety in the workplace.</p>', `total_course_duration` = '1 year flexible delivery (52 weeks)', `intakes` = 'Autumn 2026; Autumn 2026\nSpring 2026\nSummer 2026/2027 2026; Autumn 2026, NURS Autumn A 2026, NURS Spring A 2026; Autumn 2026, Spring 2026; Autumn 2026, Spring 2026, Summer 2026/2027; February, June and September; Jan 2027 Intake: 03 Aug 2026 to 26 Oc', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10203;
UPDATE `courses` SET `apply_form` = 'https://www.uow.edu.au/study/courses/graduate-certificate-in-education/', `course_description` = '<h4>Course Information</h4> <p>The Graduate Certificate in Education is designed for educators seeking a short, flexible degree that can be tailored to their needs and interests. The course suits graduates and professionals who are looking to diversify or change their career direction in fields such as staff training and development, or policy and planning.</p>', `total_course_duration` = '6 months online/off-campus (26 weeks), 6 months full-time (26 weeks)', `intakes` = 'Autumn 2026; Autumn 2026\nSpring 2026\nSummer 2026/2027 2026; Autumn 2026, NURS Autumn A 2026, NURS Spring A 2026; Autumn 2026, Spring 2026; Autumn 2026, Spring 2026, Summer 2026/2027; February, June and September; Jan 2027 Intake: 03 Aug 2026 to 26 Oc', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10204;
