UPDATE `courses` SET `apply_form` = 'https://www.flinders.edu.au/study/courses/bachelor-health-sciences-master-occupational-therapy?source=ecs-dom-home', `course_description` = '<h4>Course Information</h4> <p>Develop the knowledge and skills required to become registered and work as an occupational therapist. The degree has a strong focus on preparing you for interprofessional practice, and on becoming a contemporary health professional able to work across a variety of settings and with a wide range of clients.</p> <h5>Course Structure</h5> <p>To qualify for the Bachelor of Health Sciences, Master of Occupational Therapy, a student must complete 180 units with a grade of P or NGP or  better in each topic.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Year 12 or equivalent qualificationsor mature age entry (STAT)or TAFE/VET qualificationsor higher education transfersor completion of a foundation studies program.; Police Check.; Criminal History Check.; English language skills</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS overall 7.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS overall 7.0</li></ul>', `total_course_duration` = '5 years full-time (260 weeks)', `assessment_style` = 'assignment', `intakes` = 'April, November; February; February, July; February, July, October; January, May, August; July; June, October; March; March , July; March, July; March, July, October; March, October; Monthly intakes', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10283;
