UPDATE `courses` SET `apply_form` = 'https://www.flinders.edu.au/study/courses/master-health-clinical-research?source=ecs-dom-study', `course_description` = '<h4>Course Information</h4> <p>The Master of Health and Clinical Research program is a Higher Degree by Research pathway for professionals in any health field, giving graduates specialised knowledge and skills for research, and is a pathway to studying a PhD.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>To be accepted for admission to the Master of Health and Clinical Research, an applicant must:; have a bachelor s degree with Honours from an Australian university (which must include relevant studies and field of research), or the equivalent qualification as approved by the relevant authorised delegate, or a bachelor s degree with five years of clinical or industry work experience, and; meet the English language requirements specified by the University, and; satisfy the University that they are reasonably likely to be able to successfully complete the requirements of the award within the maximum duration.</li></ul>', `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'March, July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10285;
UPDATE `courses` SET `apply_form` = 'https://www.flinders.edu.au/study/courses/postgraduate-clinical-rehabilitation', `course_description` = '<h4>Course Information</h4> <p>The Master of Clinical Rehabilitation is designed to provide students from any health professional background the opportunity to deepen their advanced skills and theoretical knowledge base in a variety of areas of clinical rehabilitation practice, apply these new skills in a range of clinical settings, and to contribute to the current and future body of knowledge in clinical rehabilitation.</p> <h5>Course Structure</h5> <p>To qualify for the Master of Clinical Rehabilitation - 2 years, a student must complete 72 units with a grade of P or NGP or  better in each topic.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants must normally hold one of the following:; The Graduate Certificate in Clinical Rehabilitation or the Graduate Diploma in Clinical Rehabilitation; An approved degree or equivalent qualification from an approved tertiary institution in the same discipline and have not less than two years work experience in a relevant clinical area</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'March, July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10286;
