UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants must have one of the following:; Normally hold a degree or equivalent qualification from an approved tertiary institution and have not less than two years professional experience in the health or aged care sector following completion of the degree or equivalent qualification; Hold either the Graduate Certificate in Health Administration or equivalent, or the Graduate Diploma in Health Administration or equivalent from Flinders University and have not less than two years professional experience in the health or aged care sector</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'March, July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10288;
