UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>The course specialisation equips graduates of the program to be eligible for registration as a psychologist with the Psychology Board of Australia. The requirements of such courses are made explicit by the Australian Psychology Accreditation Council.</p> <h5>Course Structure</h5> <p>To qualify for the Master of Psychology (Clinical), a student must complete 72 units with a grade of P or NGP or  better in each topic.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants must hold a honours degree or equivalent qualification from an approved tertiary institution with a 1st or upper 2nd Class standard in the field of psychology.</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'April, November; February; February, July; February, July, October; January, May, August; July; June, October; March; March , July; March, July; March, July, October; March, October; Monthly intakes', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10298;
