UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>The overall aim of the course is to prepare students for professional practice as an Accredited Exercise Physiologist (AEP). Graduates will be able to contribute to interdisciplinary health interventions using exercise as part of the management strategy of disease, dysfunction and injury across a range of public and private settings and work within an interdisciplinary environment including rural and remote areas.</p> <h5>Course Structure</h5> <p>To qualify for the Master of Clinical Exercise Physiology, a student must complete 72 units with a grade of P or NGP or  better in each topic.</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS overall 6.5</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'April, November; February; February, July; February, July, October; January, May, August; July; June, October; March; March , July; March, July; March, July, October; March, October; Monthly intakes', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10337;
