UPDATE `courses` SET `apply_form` = 'https://handbook.flinders.edu.au/courses/current/GCCBH', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Applicants must:; Hold a bachelor degree or equivalent in a health related area, e.g. behavioural science, counselling, medicine, nursing, occupational therapy, psychology or social work or; Hold a bachelor degree in a non health related area with a minimum of two years full time equivalent relevant work experience in counselling, psychology, or behavioural science or; Hold a bachelor degree in a non health related area with evidence of continuous professional development (PD) in counselling, or post degree courses related to counselling, or psychology or; Have three years full time equivalent work experience in counselling, psychology, or behavioural science.</li></ul>', `total_course_duration` = '6 months full-time (26 weeks)', `assessment_style` = 'assignment', `intakes` = 'April, November; February; February, July; February, July, October; January, May, August; July; June, October; March; March , July; March, July; March, July, October; March, October; Monthly intakes', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10361;
