UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>If you have a background in teaching or educational administration, or have a professional interest in education, this course has been designed for you.  Assessment consists of a thesis of up to 40,000 words which constitutes 100% of the examination for the degree and is examined externally. Applicants without prior relevant research training will be required to take 60 credit points of research training coursework subjects in the first semester (FTE) of the degree.  Please refer to the School of Education staff page for potential supervisors and their areas of expertise. Once you have identified a potential supervisor, you&#x27;ll need to get in touch with them to see if they are available and if they would be a good fit for your research project before you apply.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Postgraduate: Prerequisites - Course specific requirements - The minimum academic requirement for entry to a Master of Education (Research) at La Trobe University is a three-year Bachelor</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 79</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 6.5</li><li><strong>TOEFL iBT:</strong> TOEFL Overall minimum score: 79</li></ul>', `total_course_duration` = '2 years full-time (104 weeks), 4 years part-time (208 weeks)', `assessment_style` = 'mixed', `intakes` = '1 February 2027; Anytime; Jan, May, Sept; January 2027; July 2026; LTU Term 2 (March 2026), LTU Term 4 (July 2026); March, June; Semester 1; Semester 1 (March 2025), Semester 2 (July 2025), Summer (November 2025); Semester 1 (March 2026), Semester 2 ', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10389;
