UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Providing pathways for Year 12 students</li><li>Bachelor of Health Science / Master of Clinical Chiropractic</li><li>Bachelor of Laws Combined Degrees</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS One Skill Retake 6.0 Overall</li><li><strong>PTE Academic:</strong> Pearson Test of English (PTE) 50 Overall</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS One Skill Retake 6.0 Overall</li><li><strong>PTE Academic:</strong> Pearson Test of English (PTE) 50 Overall</li></ul>', `total_course_duration` = '104 weeks', `assessment_style` = 'assignment', `intakes` = 'February, July; January, May, August; January, May, September; January, September; July; Semester 1 2026, Semester 1 2027; Semester 1 2027; Semester 1 2027, Semester 2 2027; Semester 2 2026, Semester 1 2027, Semester 2 2027; Semester 2 2027; Septembe', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10583;
UPDATE `courses` SET `apply_form` = 'https://www.murdoch.edu.au/course/undergraduate/b1404', `course_description` = '<h4>Course Information</h4> <p>Do you remember your favourite teacher from primary school? Perhaps it was someone you learned a lot from, they taught you new ways of thinking or inspired you in some way. You could be that special teacher for future generations.Get the qualification you need to teach students from Years 1 to 6 as you study areas of the primary curriculum including English, Mathematics, Science, Humanities and Social Sciences, Health and Physical Education and the Arts. You will also study effective learning, teaching and assessment practices.To expand your career opportunities, you can choose to specialise in Mathematics and Numeracy Education, English and Literacy Education, Inclusive Education for work in special education schools and centres, and Indonesian or Japanese teaching in primary schools.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Australian year 12 or equivalent.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic IELTS One Skill Retake 6.5 Overall</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic IELTS One Skill Retake 6.5 Overall</li></ul>', `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10584;
UPDATE `courses` SET `apply_form` = 'https://www.murdoch.edu.au/course/undergraduate/b1405', `course_description` = '<h4>Course Information</h4> <p>Playing with slime, building block towers and painting with spaghetti are more than childs play. International research has shown that learning through play is vital for helping children develop their creativity, resilience, wellbeing and more. In this course youll explore play-based learning and get hands-on experience with a range of teaching and learning methods.Youll explore areas of the primary curriculum including English, Mathematics, Science, Humanities and Social Sciences, Health and Physical Education and the Arts, with a focus on early childhood learning and development.As you complete your degree, youll build an online portfolio to share your experience with future employers. You could follow this degree with a Master of Education (Coursework) or Master of Education (Research) to expand your career opportunities and build your expertise even further.</p> <h5>Course Structure</h5> <p>Total credit points: 96</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Australian year 12 or equivalent.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic IELTS One Skill Retake 6.5 Overall</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic IELTS One Skill Retake 6.5 Overall</li></ul>', `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10585;
UPDATE `courses` SET `apply_form` = 'https://www.murdoch.edu.au/course/undergraduate/b1417', `course_description` = '<h4>Course Information</h4> <p>Would you like to build a career out of making a difference to peoples lives? Nurses do just that by providing healthcare in times of need</p> <h5>Course Structure</h5> <p>Total credit points: 72</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS overall score of 7.0</li></ul>', `total_course_duration` = '3 years full-time (156 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1 2027; Semester 2 2026, Semester 1 2027, Semester 2 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10586;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Build a career in nursing and make a lasting difference to people when they need care the most.</p> <p>Find yourself in a position to contribute to the health and wellbeing of all people, playing an important role in providing people with care through the most challenging, rewarding, and delicate moments that life has to offer.</p> <p>Become industry-ready by gaining hands-on experience in our fully equipped simulation suites.</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic 7.5 Overall</li><li><strong>PTE Academic:</strong> PTE 76 Overall</li></ul>', `total_course_duration` = '52 weeks', `assessment_style` = 'assignment', `intakes` = 'February, July; January, May, August; January, May, September; January, September; July; Semester 1 2026, Semester 1 2027; Semester 1 2027; Semester 1 2027, Semester 2 2027; Semester 2 2026, Semester 1 2027, Semester 2 2027; Semester 2 2027; Septembe', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10587;
