UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>a three year Bachelors degree and a Graduate Diploma, or equivalent qualifications as recognized by UWA, or; a four year Bachelor of Education or Graduate Diploma in Education or Master of Teaching, or an equivalent qualification as recognized by UWA, or; a Bachelors degree requiring at least four years of full-time study and; at least two years of professional experience in a relevant occupation.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic require an overall score of at least 7.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic require an overall score of at least 7.5</li></ul>', `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1, Semester 2', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10635;
UPDATE `courses` SET `apply_form` = 'https://www.uwa.edu.au/study/courses/master-of-public-health', `course_description` = '<h4>Course Information</h4> <p>You will gain a strong foundation in the core fields of epidemiology, biostatistics, qualitative research methods, health economics and health promotion, plus the broader social context in which health programs are planned, delivered and evaluated. This course is available by: coursework; coursework and 24-point dissertation; or coursework and 24-point practicum. Students may choose a research project that includes conducting a review of a body of scientific literature, writing a literature review and a detailed project proposal, development of instruments, an ethics committee application and preparing an analysis plan.</p> <h5>Course Structure</h5> <p>Credit Points 72</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>a bachelors degree, or an equivalent qualification, as recognized by UWA or; a Graduate Certificate in Population Health Studies 91230, Graduate Certificate in Environmental Health 92210, Graduate Certificate in Communicable Diseases Epidemiology 91220, or an equivalent qualification, as recognized by UWA and; the equivalent of a UWA weighted average mark of at least 60 percent.; Applicants who have or have had a progress status of Suspended or Excluded against courses 92550 or 92560 are not eligible for admission.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score of 6.5, with no band less than 6</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score of 6.5, with no band less than 6</li></ul>', `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1, Semester 2', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10636;
