UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Audiology is the clinical science involving the prevention, assessment and rehabilitation of hearing loss and associated communication disorders. The course provides students with extensive supervised clinical placements in a variety of workplace settings. Employment prospects for Audiologists who graduate from UWA are excellent both within Australia and overseas. Graduates are eligible for full membership of Audiology Australia.</p> <h5>Course Structure</h5> <p>Credit Points 96</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic with an overall score of at least 7.0</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10639;
