UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>a Bachelor of Medicine and Bachelor of Surgery, or an equivalent qualification, as recognized by UWA or; a bachelors degree in a health, biomedical or biological sciences-related discipline, or an equivalent qualification and; at least one year of relevant professional experience or; completed the Graduate Certificate in Health Professions Education or Graduate Diploma in Health Professions Education at UWA and; the equivalent of a UWA weighted average mark of at least 65 per cent in all core units.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic require an overall score of at least 7.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic require an overall score of at least 7.0</li></ul>', `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10650;
