UPDATE `courses` SET `apply_form` = 'https://www.uwa.edu.au/study/courses/graduate-certificate-in-population-health-studies', `course_description` = '<h4>Course Information</h4> <p>This certificate course allows you maximum flexibility to tailor your studies in population health to meet your personal or professional interests and requirements. This course provides students with an introduction to the fundamental concepts of public health and how public health works to create healthier populations.  Students will learn fundamental concepts in a range of public health areas such as epidemiology, biostatistics, qualitative research methods, health economics and health promotion, plus the biological, environmental, economic and social determinants of health.</p> <h5>Course Structure</h5> <p>Credit Points 24</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall 6.5, no band less than 6</li><li><strong>PTE Academic:</strong> PTE Overall 64, no band score less than 60 Prerequisite: a bachelor&#x27;s degree, or an equivalent quali</li><li><strong>TOEFL iBT:</strong> TOEFL IBT Overall 82, 22 for writing, 20 for speaking, 20 for listening, and 18 for reading</li></ul>', `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'mixed', `intakes` = 'Semester 1, Semester 2', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10652;
UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>a bachelors degree, or equivalent as recognized by UWA and; the equivalent of a UWA weighted average mark of at least 50 percent and; met the prerequisite for the chosen specialization; For the Environmental Management or Environmental Economics specializations an applicant must have completed prior studies at a tertiary level in either science, engineering, economics, natural resource management, urban and regional planning, or policy studies; or a related cognate discipline, as recognized by UWA; For the Catchments and Water or Environmental Rehabilitation or Sensing and Data Science specializations an applicant must have completed prior studies at a tertiary level in either earth, environmental, engineering, biological or physical sciences; or a related cognate discipline, as recognized by UWA; For the Marine and Coastal specialization an applicant must have completed prior studies at a tertiary level in either marine, environmental, engineering, biological or physical sciences; or a related cognate discipline, as recognized by UWA</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score of 6.5, with no band less than 6</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score of 6.5, with no band less than 6</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1, Semester 2', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10653;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This course is suitable for graduates from any field, seeking a career in the health industry as a professional public health practitioner or researcher. You will gain a strong foundation in the core fields of epidemiology, biostatistics, qualitative research methods, health economics and health promotion, plus the broader social context in which health programs are planned, delivered and evaluated. The Master of Public Health with Specialization offers the chance to specialize in Public Health Foundations, Applied Public Health or Public Health Methodology.</p> <h5>Course Structure</h5> <p>Credit Points 96</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score of 6.5, with no band less than 6</li></ul>', `total_course_duration` = '2 years full-time (104 weeks), 5.5 years part-time (286 weeks)', `assessment_style` = 'assignment', `intakes` = 'Semester 1, Semester 2', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10654;
UPDATE `courses` SET `apply_form` = 'https://www.handbooks.uwa.edu.au/coursedetails?code=31520', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic require an overall score of at least 7.5, a minimum score of 7</li></ul>', `total_course_duration` = '1.5 years full-time (78 weeks)', `assessment_style` = 'mixed', `intakes` = 'Beginning of year and mid-year; February; February and July; February, July; January; Semester 1; Semester 1, Semester 2; Trimester 1, Trimester 2, Trimester 3', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10655;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Youll learn to be a psychologist who has the necessary academic and practical foundation, skills and experience to be able to develop into a competent clinician grounded in the scientist-practitioner tradition. You will be skilled at developing therapeutic relationships with your clients and be competent to work productively and to the benefit of a wide range of clients across a broad variety of settings.</p> <h5>Course Structure</h5> <p>Credit Points 72</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6.5 no sub-band less than 6</li><li><strong>PTE Academic:</strong> PTE-A overall score of 58 Minimum of 48 in Listening</li></ul>', `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'mixed', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10656;
UPDATE `courses` SET `apply_form` = 'https://www.uwa.edu.au/study/courses/doctor-of-philosophy-and-master-of-clinical-psychology', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>an accredited bachelors honours degree in psychology with at least an upper second class Honours, or an equivalent qualification, as recognized by the Psychology Board of Australia or the Australian Psychology Accreditation Council. The Honours degree in psychology must be completed within the past 10 years at the time of application or you must be provisionally or generally registered as a psychology with AHPRA at the time of application and; Applicants must be eligible for provisional registration as a psychologist with the Psychology Board of Australia. and; Applicants must have secured PhD supervision, with at least one supervisor from the School of Psychological Science at the time of submitting their application.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Minimum scores: Overall 7.0</li><li><strong>PTE Academic:</strong> PTE Academic Minimum scores: Overall 66</li><li><strong>TOEFL iBT:</strong> TOEFL iBT Minimum scores: Overall 94</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Minimum scores: Overall 7.0</li><li><strong>PTE Academic:</strong> PTE Academic Minimum scores: Overall 66</li><li><strong>TOEFL iBT:</strong> TOEFL iBT Minimum scores: Overall 94</li></ul>', `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'mixed', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10657;
