UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>If youre looking to upskill in clinical psychology and youve completed a masters degree or equivalent in clinical neuropsychology and are qualified with the Psychology Board of Australia (PsyBA) this bridging course allows you to do that. Youll be eligible for endorsement as a clinical psychologist with the PsyBA and the Australian Health Practitioner Regulation Board (AHPRA).</p> <h5>Course Structure</h5> <p>Credit Points 48</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>an accredited Master of Clinical Neuropsychology, or an accredited Doctor of Psychology (Clinical Neuropsychology), or an equivalent qualification, as recognized by UWA and; completed a thesis project in their Masters or Doctoral program with a content area relevant to the field of clinical psychology; Applicants must be eligible for provisional registration as a psychologist with the Psychology Board of Australia, which includes meeting the Boards English language registration standard.</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'mixed', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10664;
