UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This Combined Bachelors and Masters (CBM) course is designed to provide a holistic understanding of the use of exercise as a modality in the treatment of musculoskeletal, cardiovascular, metabolic and other chronic and complex conditions. Students may structure a course that is best tailored to their future requirements and area of specialization.</p> <h5>Course Structure</h5> <p>Credit Points 192</p>', `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'mixed', `intakes` = 'Semester 1', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10685;
