UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of support workers who complete specialised tasks and functions in aged services; either in residential, home or community based environments. Workers will take responsibility for their own outputs within defined organisation guidelines and maintain quality service delivery through the development, facilitation and review of individualised service planning and delivery.  Workers may be required to demonstrate leadership and have limited responsibility for the organisation and the quantity and quality of outputs of others within limited parameters.To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p> <h5>Course Structure</h5> <p>18 units: 15 core; 3 elective</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate IV in Marketing &amp; Communication</li><li>Age Requirement:Minimum 18 years of age at course commencement.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 6.0 overall no less than 5 Academic Requirement: Certificate IV in Marketing &amp; Commu</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 6.0 overall no less than 5 Academic Requirement: Certificate IV in Marketing &amp; Commu</li></ul>', `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'every term', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10728;
