UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Influence the next generation and guide young people to learn and grow. The Bachelor of Education (Primary) provides you with the qualifications to teach in primary schools from foundation year to Year 6.</p> <p>This course is an initial teacher education course and qualifies you for professional registration which is administered in Queensland by the Queensland College of Teachers. You will demonstrate evidence of meeting the Australian Professional Standards for Teachers (Graduate career stage) throughout the course of study.</p> <p>On successful completion of the course, you will be eligible for employment in primary school contexts throughout Australia.</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 7.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS 7.5</li></ul>', `total_course_duration` = '4 years', `assessment_style` = 'mixed', `intakes` = 'Term 1 2027; Throughout the year', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10742;
