UPDATE `courses` SET `apply_form` = 'https://www.ecu.edu.au/degrees/courses/graduate-diploma-in-environmental-science', `course_description` = '<h4>Course Information</h4> <p>Designed for professionals who require the skills and knowledge to integrate environmental planning, conservation and monitoring into the broader decision-making of their organisations. The course covers the areas of environmental impact assessment, planning and monitoring in the context of our major ecosystems, and emphasizes the global, regional and local nature of environmental issues. Students also learn about environmental management systems, environmental auditing, risk assessment and water demand management.</p> <h5>Course Structure</h5> <p>Total Credit Points 120</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Bachelor degree or; Equivalent prior learning including at least five years relevant professional experience.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic Overall band minimum score of 6.5 no individual band less than 6</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic Overall band minimum score of 6.5 no individual band less than 6</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks), 1 year online/off-campus (52 weeks)', `assessment_style` = 'assignment', `intakes` = '2027; February, July; February, July and November; February, June and October; February, June, October; January, May, and August', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10819;
