UPDATE `courses` SET `apply_form` = 'https://www.ecu.edu.au/degrees/courses/master-of-nursing-research', `course_description` = '<h4>Course Information</h4> <p>Thinking about a career in research? In this course youll do a deep dive into your chosen nursing discipline. You will develop your understanding of that discipline and learn contemporary research methods to help you undertake a significant independent research investigation, under the supervision of nursing leaders.</p> <h5>Course Structure</h5> <p>Total Credit Points 60</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic with a minimum overall score of 7.0</li></ul>', `total_course_duration` = '2 years full-time (104 weeks), 4 years part-time (208 weeks), 2 years online/off-campus (104 weeks)', `assessment_style` = 'assignment', `intakes` = '2027; February, July; February, July and November; February, June and October; February, June, October; January, May, and August', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10841;
