UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>A sonographer is a highly skilled medical imaging professional who operates an ultrasound machine to perform diagnostic medical sonographic examinations. The demand for ultrasound as a first line investigation has increased across all care settings, creating a shortage of sonographers in Australia. In this course, youll acquire knowledge and skills in applied anatomy, physiology and pathophysiology, application and operation of ultrasound imaging systems, ultrasound image recognition and comprehension, patient assessment, and more.</p> <h5>Course Structure</h5> <p>Total Credit Points 360</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>AQF Diploma or equivalent; Undergraduate Certificate; Successfully completed 0.5 EFTSL of study at bachelor level or higher at an Australian higher education provider (or equivalent); Special Tertiary Admissions Test; University Preparation Course; Indigenous University Orientation Course or; Aboriginal University Readiness Assessment.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic with a minimum overall score of 7.5 with no individual band score less than 7</li><li><strong>PTE Academic:</strong> PTE Academic with a minimum overall score of 72</li><li><strong>TOEFL iBT:</strong> TOEFL iBT with a minimum total score of 102</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic with a minimum overall score of 7.5 with no individual band score less than 7</li><li><strong>PTE Academic:</strong> PTE Academic with a minimum overall score of 72</li><li><strong>TOEFL iBT:</strong> TOEFL iBT with a minimum total score of 102</li></ul>', `total_course_duration` = '3 years full-time (156 weeks), 5 years part-time (260 weeks)', `assessment_st