UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This coursework-based program equips you with advanced knowledge in management, leadership, and strategic decision-making, tailored specifically for the educational context. Graduates will be able to effectively manage resources, foster innovation, and lead educational teams to deliver exceptional outcomes, positioning themselves as influential leaders in Australia’s evolving educational landscape.</p> <h5>Course Structure</h5> <p>Total Credit Points 120</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic Overall band minimum score of 6.5 no individual band less than 6</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = '2027; February, July; February, July and November; February, June and October; February, June, October; January, May, and August', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10851;
