UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>The healthcare industry needs skilled professionals with both science and management skills.</p> <p>From chronic disease and mental health to aging and wellbeing, the systems, communities and research behind our healthcare industry have diverse challenges to solve.</p> <p>The Bachelor of Health Sciences prepares you for a career at the forefront of the healthcare industry through two distinct majors:Health PromotionandHealth Services.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate IV – Separate evidence of</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic (International English Language Testing System) Writing 6</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic (International English Language Testing System) Writing 6</li></ul>', `total_course_duration` = '156 weeks', `assessment_style` = 'assignment', `intakes` = 'May', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 10853;
