UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Our Werribee campus is where Heathdale was first born in 1982. Easily accessible in the western suburbs of Melbourne, this vibrant campus caters for students from Kindergarten to Year 12 through a Primary and Secondary school.</li><li>Secondary School is Year 7 - Year 12</li><li>The Secondary School incorporates students from Year 7 through to Year 12 and includes two Learning Modules: Year 7 to Year 9 and Year 10 to Year 12.</li><li>Year 10 to Year 12 Learning Module</li></ul>', `enrolment_fee` = 110.0, `total_course_duration` = '364 weeks', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11143;
