UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>MINIMUM ELIGIBILITY REQUIREMENTS You must demonstrate that you have achieved one of the following:; A NSW Higher School Certificate (HSC) with English at HSC band 4 level or its equivalent. If you do not have a band 4 in English, you may need to complete an IELTS test at your own expense and achieve a band 6 in English to be eligible for entry to this degree OR; A Certificate IV in Tertiary Preparation or its equivalent OR; A Certificate IV or higher vocational qualification OR; Successful completion of at least one year full-time (or equivalent) study in a course at a higher education institution; SPECIAL ADMISSIONS: If you are unable to meet the entry requirements, you may be eligible for special admission.; INTERNATIONAL APPLICANTS: International applicants must meet proof of eligibility and course entry requirements. In addition, international applicants whose first language is not English must demonstrate English proficiency at a minimum IELTS level of 6.5 with a minimum level of 6 in any one band. For further information please visit the TAFE NSW International (https://www.tafensw.edu.au/international) website for details on fees and enrolment processes for international students.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS test at your own expense and achieve a band 6</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS test at your own expense and achieve a band 6</li></ul>', `total_course_duration` = '4 years full-time (208 weeks), 8 years part-time (416 weeks)', `assessment_style` = 'assignment', `intakes` = 'April, 2026; Feb, Jul; February, 2026; February, July, 2026; July; July, 2026', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11152;
UPDATE `courses` SET `apply_form` = 'https://www.tafensw.edu.au/international/course-details/-/i/CF344BC5767B92F0A262C8D300177F62/CHC43015/Certificate-IV-in-Ageing-Support', `total_course_duration` = '36 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'April, 2026; Feb, Jul; February, 2026; February, July, 2026; July; July, 2026', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11153;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of a variety of workers who use a range of factual, technical and procedural knowledge to provide assistance to health professional staff for the care of clients. Health services assistance involves the worker in direct client contact under supervision. No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p> <h5>Course Structure</h5> <p>7 core and 8 elective units.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate IV in Kitchen Management (SIT40521)</li></ul>', `total_course_duration` = '6 months full-time (26 weeks), 18 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'April, 2026; Feb, Jul; February, 2026; February, July, 2026; July; July, 2026', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11154;
