UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Prep to Year 12 Application Process</li><li>ESL Program from Year 7 to Year 10</li><li>at no additional cost, integrated within the mainstream school. The ESL program focuses on improving grammar, vocabulary, and the four macro skills of reading, writing, listening, and speaking, ensuring students can achieve their full potential in all subjects. The ESL Program is mandatory for all International Students from Year 7 to Year 10.</li><li>Importantly, EAL English also satisfies the requirement of “English” in any university course that lists English as a prerequisite.</li></ul>', `enrolment_fee` = 300.0, `total_course_duration` = '208 weeks', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11272;
