UPDATE `courses` SET `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall minimum score: 7.5</li></ul>', `total_course_duration` = '2 years full-time (104 weeks), 4 years part-time (208 weeks), 2 years online/off-campus (104 weeks)', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11298;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This program provides foundational understandings of the Secondary school contexts (Years 7-12) in state, Catholic and independent schools, with a particular emphasis on teaching from a Christian perspective. The course equips students with effective teaching and learning strategies to apply their knowledge, expertise and experience to engage the adolescent learner. Students are equipped to integrate Christian worldview perspectives into their teaching.</p> <h5>Course Structure</h5> <p>160 credit points; field placement in each semester.</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic 7.5</li></ul>', `total_course_duration` = '2 years full-time (104 weeks), 4 years part-time (208 weeks), 2 years online/off-campus (104 weeks)', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11299;
UPDATE `courses` SET `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: Overall 6.0, Writing 6</li><li><strong>PTE Academic:</strong> Pearson Test of English: Total 54, Writing 54, No score less than 42</li></ul>', `total_course_duration` = '43 weeks', `assessment_style` = 'assignment', `intakes` = 'January, April, August; January, August; January, May, August; January, May, September; March, August, November; Multiple', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11300;
UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Beyond academic results, universities value evidence that students have actively explored their interests through wider reading, competitions, volunteering, work experience, research, or independent projects.</li><li>Unlike the Australian system, where university applications are largely based on an ATAR received at the end of Year 12, UK applications begin during Year 12 using predicted results and require students to apply directly to specific courses.</li><li>&quot;A competitive application isn&#x27;t built in the final months of Year 12. It&#x27;s developed over several years through informed subject choices, sustained curiosity, and genuine engagement.&quot;</li><li>Career education at Korowa | Year 10 World of Work Week</li></ul>', `enrolment_fee` = 200.0, `total_course_duration` = '312 weeks', `assessment_style` = 'assignment', `intakes` = 'January, April, October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11301;
