UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>is designed to enhance your learning experience, and provide you with the underpinning knowledge necessary to prepare you for studies in Nursing or health related fields at university level. introduces you to the biological, social and cultural elements involved in health care. It is specially designed for students who wish to major in Nursing, Nutrition, Biomedical Science, Speech Pathology, Sports Science or Psychology. Students who complete the ECC Diploma of Health Science (Year 2) will be eligible for admission to a range of Health Science degrees at ECU. The range of credits granted varies depending upon the degree you choose. A minimum of 50% pass in all units is required for progression to ECU.</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic 5.5 with no band less than 5.0</li><li><strong>PTE Academic:</strong> Pearson Test of English Academic 42 with no score less than 36</li><li><strong>TOEFL iBT:</strong> TOEFL iBT 46 (R8 L7 S16 W18)</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic 5.5 with no band less than 5.0</li><li><strong>PTE Academic:</strong> Pearson Test of English Academic 42 with no score less than 36</li><li><strong>TOEFL iBT:</strong> TOEFL iBT 46 (R8 L7 S16 W18)</li></ul>', `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, July; February, June, October; Stage 2: February, July / Stage 1: April, October', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11331;
