UPDATE `courses` SET `apply_form` = 'https://www.accco.com.au/course/diploma-of-early-childhood-education-and-care-chc50125/', `course_description` = '<h4>Course Information</h4> <p>Full-time: 52 weeks - 8 study hrs/week + 2 practical days/week Part-time: 104 weeks - 4 study hrs/week + 1 practical day/week. For more details, see FAQs.</p> <p>Complete 280 hours in a regulated early childhood service in Australia - at your current centre if you’re working, or we can help you find a paid position.</p> <p>Scroll down to the How Much section to see the fees for your state.</p>', `total_course_duration` = '52 weeks', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11634;
