UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>Course fees are indicative and should be used as a guide.Speak to a counsellorto get an accurate price.</p> <p>The application deadline isn&#x27;t availableSpeak to an IDP counsellorfor more detailed information</p> <p>If you aren&#x27;t eligible for the above entry requirements, you might have a chance to explore pathway options atAcademia International. If you want to find out more, speak to our counsellors.</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 6</li></ul>', `materials_fee` = 150.0, `total_course_duration` = '2 Year', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11685;
