UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>The Graduate Diploma of Disability was developed in line with the National Disability Insurance Scheme (NDIS) practice standards and quality indicators and is grounded in the international human rights framework of the United Nations Convention on the Rights of Persons with Disabilities (UNCRPD) and its expression in Australias National Disability Strategy. The course will emphasize and recognize the distinctively caring and pastoral nature of disability and care by utilizing a Christian framework that is also inclusive and respectful of other faiths.</p> <h5>Course Structure</h5> <p>48 credit points</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: 6.5 with no band less than 6.0 Prerequisite: Previously successfully comple</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks), 1 year online/off-campus (52 weeks)', `intakes` = 'February and July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11724;
