UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of individuals in a range of community settings and peoples&#x27; homes, who provide support in a manner that empowers people with disabilities to achieve greater levels of independence, self-reliance, community participation and wellbeing. Workers promote a person-centred approach, work according to and may contribute to an individualised plan, and work without direct supervision. They may be required to supervise and/or coordinate a small team.</p>', `enrolment_fee` = 200.0, `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'May', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11729;
