UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Minimum ATAR of 63.00 (or equivalent eg.OP of 15 or less).; Completion or partial completion of an Australian Qualifications Framework AQF Level 7 qualification at an accredited university or higher education provider.; Successful completion of bridging or enabling course, or another recognised tertiary preparation course.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score of 7.0 with a minimum score of 7 in listening, reading, and speaking and a minimum score of 6</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score of 7.0 with a minimum score of 7 in listening, reading, and speaking and a minimum score of 6</li></ul>', `total_course_duration` = '3 years full-time (156 weeks)', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11746;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>The Bachelor of Science/Bachelor of Teaching (BSc/BTch) course is for those wanting to teach in Christian, independent and state school systems in both Australia and overseas. Avondales BSc/BTch is a highly practical degree that is designed to provide you with the necessary knowledge and skills for a career in secondary science and mathematics teaching.</p> <h5>Course Structure</h5> <p>Thirty-two 6 credit point units (192 credit points) studied over eight semesters</p> <h5>Study & Career Pathways</h5> <p>Credit is given for prior learning appropriate to course requirements. An honours component is available.</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score of 7.5, with a minimum score of 7</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score of 7.5, with a minimum score of 7</li></ul>', `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11747;
