UPDATE `courses` SET `apply_form` = 'https://www.avondale.edu.au/course/bachelor-of-arts-bachelor-of-teaching-secondary/', `course_description` = '<h4>Course Information</h4> <p>The Bachelor of Arts/Bachelor of Teaching (Secondary) (BA/BTch (Sec)) course is designed to equip you with the necessary skills needed to teach in Christian, independent and state high school systems in both Australia and overseas. Many Avondale graduates are highly valued in the Australian education sector. It is Avondales aim to graduate teachers who are reflective, creative and confident in the classroom.</p> <h5>Course Structure</h5> <p>Thirty-two 6 credit point units (192 credit points) studied over eight semesters full-time or the equivalent part-time.</p> <h5>Study & Career Pathways</h5> <p>Credit is given for prior learning appropriate to course requirements. Honours course is available.</p>', `entry_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score of 7.5, with a minimum score of 7</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score of 7.5, with a minimum score of 7</li></ul>', `total_course_duration` = '4 years full-time (208 weeks)', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11752;
