UPDATE `courses` SET `apply_form` = 'https://www.etea.edu.au/advanced-diploma-of-nursing/', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of enrolled nurses with advanced skills who work in a specialised area of nursing practice under the direct or indirect supervision of a registered nurse. Enrolled nurses integrate and adapt specialised, technical and theoretical knowledge to address a diverse range of clinical situations and challenges in their area of specialisation. They contribute to the continuous improvement of clinical practice using research and participation in broader organisational quality processes. Enrolled nurses retain responsibility for their own actions while remaining accountable to the registered nurse for all delegated functions.</p>', `total_course_duration` = '2 years flexible delivery (104 weeks)', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11820;
UPDATE `courses` SET `apply_form` = 'https://www.etea.edu.au/chc42021-certificate-iv-in-community-services/', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>English (PTE):PTE Academic score of 52 or</li><li>Certificate III in Automotive Electrical Technology</li><li>Age Requirement:Minimum 18 years of age at course commencement.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS score of 6</li><li><strong>PTE Academic:</strong> PTE PTE Academic score of 52</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS IELTS score of 6</li><li><strong>PTE Academic:</strong> PTE PTE Academic score of 52</li></ul>', `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11821;
