UPDATE `courses` SET `apply_form` = 'https://www.rhodescollege.vic.edu.au/portfolio-posts/certificate-iii-in-work-health-and-safety/', `course_description` = '<h4>Course Information</h4> <p>This qualification is suitable for people who take on work health and safety (WHS) responsibilities in addition to their main duties. They may provide technical advice and support to a team. The qualification reflects the role of skilled operators who apply a broad range of competencies in varied work contexts.</p>', `materials_fee` = 499.0, `total_course_duration` = '32 weeks', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11875;
