UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>The fee you pay at TasTAFE will depend on the course you choose and may vary depending on the level of government subsidy available, the cost of delivery, any previous study you have undertaken and/or your personal circumstances.</p> <p>Our fee estimator will give you an indication of the type of fee you might expect to pay, but is intended as a guide only and doesn’t include other costs associated with your course. Please contact us on1300 655 307to confirm your fee.</p> <p>Are you an Australian citizen, a Permanent resident or a New Zealand citizen?</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Overall 6.0 no band less than 5</li><li><strong>PTE Academic:</strong> PTE Overall 47 (no communicative skills less than 36)</li></ul>', `total_course_duration` = '52 Weeks', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11910;
