UPDATE `courses` SET `apply_form` = 'https://www.nantien.edu.au/courses/postgraduate-courses/health-and-social-wellbeing/graduate-certificate/', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Either a bachelor degree with a major in health, human services, social sciences, liberal arts, or education, or relevant working experience and professional training over at least 3 years for example in the health sector or social services or education; all students are required to demonstrate a minimum level of proficiency in English language; the minimum level of English proficiency is a pass in the IELTS (Academic) test with a minimum score of 6.5 with no sub-band score less than 6.0 (equivalent measures of English language proficiency are acceptable)</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic test with a minimum score of 6.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic test with a minimum score of 6.5</li></ul>', `total_course_duration` = '6 months full-time (26 weeks), 12 months part-time (52 weeks)', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11968;
