UPDATE `courses` SET `apply_form` = 'https://apsi.edu.au/courses/community-services/diploma-of-community-services/', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of community services workers involved in the delivery, management and coordination of person-centred services to individuals, groups, and communities.</p> <p>At this level, workers have specialised skills in community services and work autonomously within their scope of practice under broad directions from senior management.</p> <p>Workers support people to make change in their lives to improve personal and social wellbeing and may also have responsibility for the supervision of other workers and volunteers. They may also undertake case management and program coordination.</p>', `total_course_duration` = '64 weeks', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 11978;
