UPDATE `courses` SET `apply_form` = 'https://sheridan.edu.au/index.php/study/med', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>4-year Bachelor of Education and 2 years full-time equivalent relevant professional experience, or 3-year undergraduate degree and minimum 1-year postgraduate teacher education award (e.g. GradDipEd or MTeach) and 2 years full-time equivalent relevant professional experience, or successful completion of the Sheridan Graduate Certificate of Education.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic 6.5 with individual Reading and Writing bands of no less than 6</li><li><strong>PTE Academic:</strong> Pearson Test of English (PTE Academic) 58 (Speaking/Writing not less than 58, Listening/Reading not less than 54)</li><li><strong>TOEFL iBT:</strong> TOEFL (Internet based) 86 (no band less than 20)</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic 6.5 with individual Reading and Writing bands of no less than 6</li><li><strong>PTE Academic:</strong> Pearson Test of English (PTE Academic) 58 (Speaking/Writing not less than 58, Listening/Reading not less than 54)</li><li><strong>TOEFL iBT:</strong> TOEFL (Internet based) 86 (no band less than 20)</li></ul>', `total_course_duration` = '1 year full-time (52 weeks), 2 years part-time (104 weeks)', `assessment_style` = 'assignment', `intakes` = 'February and July', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12057;
