UPDATE `courses` SET `apply_form` = 'https://protea.edu.au/chc52015-diploma-of-community-services-cricos-111855g/', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate IV in Project Management Practice – BSB40920 (CRICOS: 103926H)</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS of 5.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS of 5.0</li></ul>', `total_course_duration` = '78 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'Any week', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12106;
UPDATE `courses` SET `apply_form` = 'https://charter.edu.au/courses/english-for-healthcare-and-nursing', `course_description` = '<h4>Course Information</h4> <p>The program is tailored to give students the language skills to work in healthcare settings, preparing them for the professional language needs of the industry. Students will focus on nursing topics and professional communication skills relevant to their career path.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Students require a minimum English level of IELTS 4.5 or equivalent. You can take our placement test to check if the course is suitable for you.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 4.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 4.5</li></ul>', `total_course_duration` = '26 weeks full-time', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12107;
UPDATE `courses` SET `apply_form` = 'https://charter.edu.au/courses/diploma-of-community-services', `course_description` = '<h4>Course Information</h4> <p>The CHC52025 Diploma of Community Services provides you with the skills and knowledge to deliver, manage, and coordinate person-centred programs and services for individuals, groups, and communities.</p> <p>TheCHC52025Diploma of Community Services prepares you for a rewarding career supporting individuals, families, groups, and communities. You will learn to deliver, coordinate, and manage person‑centred services that improve wellbeing and create positive change.</p> <p>Graduates develop specialised skills to work independently, advocate for clients, support diverse communities, coordinate programs, and take on leadership roles. You may also gain experience in case management, supervising staff or volunteers, and program planning.</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate III in Early Childhood Education and Care</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 5.5</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 5.5</li></ul>', `total_course_duration` = '1 year', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12108;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of support workers who complete specialised tasks and functions in aged services; either in residential, home or community based environments. Workers will take responsibility for their own outputs within defined organisation guidelines and maintain quality service delivery through the development, facilitation and review of individualised service planning and delivery.  Workers may be required to demonstrate leadership and have limited responsibility for the organisation and the quantity and quality of outputs of others within limited parameters.To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p> <h5>Course Structure</h5> <p>18 units: 15 core; 3 elective</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 5.5</li></ul>', `total_course_duration` = '38 weeks', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12109;
