UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of individuals who work in operational or team leading roles in health administration.The skills in this qualification must be applied in accordance with Commonwealth and State or Territory legislation, Australian standards and industry codes of practice.No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS minimum overall score of 6.0</li><li><strong>PTE Academic:</strong> PTE minimum overall score of 50</li><li><strong>TOEFL iBT:</strong> TOEFL minimum overall score of 60</li></ul>', `total_course_duration` = '12 months flexible delivery (52 weeks)', `assessment_style` = 'assignment', `intakes` = '5 Oct 2026, 2 Nov 2026, 4 Jan 2027', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12124;
