UPDATE `courses` SET `apply_form` = 'https://www.heli.edu.au/graduate-certificate-in-higher-education-academic-practice/', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Academic IELTS: 6.5 or higher overall with a writing score of at least 6.5 with no band lower than 6.0; or IBT (Internet-based TOEFL) overall score of 79 with a writing section minimum of 21 and speaking 18; or Cambridge Certificate of Proficiency in English (CPE): Overall score 180, writing and speaking 180; or Cambridge Certificate of Advanced English (CAE): Overall 176 with a writing and speaking minimum score of 169: or PTE Academic Module with a minimum score of 58 with a writing and speaking section minimum of 50 English For Academic Purposes Level 2 (EAP 2): Upper Intermediate ‘A’ grade or higher with IELTS 6.5 requirement</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: 6.5</li><li><strong>PTE Academic:</strong> PTE Academic Module with a minimum score of 58</li><li><strong>TOEFL iBT:</strong> TOEFL overall score of 79</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: 6.5</li><li><strong>PTE Academic:</strong> PTE Academic Module with a minimum score of 58</li><li><strong>TOEFL iBT:</strong> TOEFL overall score of 79</li></ul>', `enrolment_fee` = 200.0, `total_course_duration` = '6 months online/off-campus (26 weeks), 6 months full-time (26 weeks), 1 year part-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'Feb, Jun, Sep', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12556;
