UPDATE `courses` SET `apply_form` = 'https://www.hills.qld.edu.au/learning/primary-school/international-baccalaureate-primary-years-program', `course_description` = '<h4>Course Information</h4> <p>“The International Baccalaureate aims to develop inquiring, knowledgeable and caring young people who help to create a better and more peaceful world through intercultural understanding and respect.</p> <p>To this end the organisation works with schools, governments and international organisations to develop challenging programmes of international education and rigorous assessment.</p> <p>These programmes encourage students across the world to become active, compassionate and lifelong learners who understand that other people, with their differences, can also be right.”</p>', `enrolment_fee` = 115.0, `total_course_duration` = '364 weeks', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12577;
