UPDATE `courses` SET `apply_form` = 'https://wmit.edu.au/course/international-students/diploma-of-community-services-melbourne/', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>18 years or older at commencement of course. IELTS (Academic) band score 6.0 or equivalent. Completion of Australian Year 12 or equivalent.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic band score 6.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS Academic band score 6.0</li></ul>', `enrolment_fee` = 250.0, `total_course_duration` = '2 years full-time (104 weeks)', `assessment_style` = 'mixed', `intakes` = 'Monthly Intake', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12593;
UPDATE `courses` SET `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of support workers who complete specialised tasks and functions in aged services; either in residential, home or community based environments. Workers will take responsibility for their own outputs within defined organisation guidelines and maintain quality service delivery through the development, facilitation and review of individualised service planning and delivery.  Workers may be required to demonstrate leadership and have limited responsibility for the organisation and the quantity and quality of outputs of others within limited parameters.To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p> <h5>Course Structure</h5> <p>18 units: 15 core; 3 elective</p>', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Certificate III in Individual Support (Aging &amp; Disability)</li><li>Age Requirement:Minimum 18 years of age at course commencement.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>PTE Academic:</strong> PTE Academic: Minimum overall score of 50, with at least 42 in each of the four skills</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>PTE Academic:</strong> PTE Academic: Minimum overall score of 50, with at least 42 in each of the four skills</li></ul>', `enrolment_fee` = 250.0, `materials_fee` = 500.0, `total_course_duration` = '52 weeks full-time', `assessment_style` = 'assignment', `intakes` = 'Monthly intakes', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12594;
