UPDATE `courses` SET `apply_form` = 'https://mite.edu.au/certificate-iv-in-disability-support/', `course_description` = '<h4>Course Information</h4> <p>This qualification reflects the role of individuals in a range of community settings and peoples&#x27; homes, who provide support in a manner that empowers people with disabilities to achieve greater levels of independence, self-reliance, community participation and wellbeing. Workers promote a person-centred approach, work according to and may contribute to an individualised plan, and work without direct supervision. They may be required to supervise and/or coordinate a small team.</p>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 5.5 overall, with no band less than 5</li><li><strong>PTE Academic:</strong> PTE Academic 42 with no band less than 36</li></ul>', `total_course_duration` = '52 weeks full-time', `assessment_style` = 'mixed', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12715;
