UPDATE `courses` SET `apply_form` = 'https://thames.edu.au/course/chc50121-diploma-of-early-childhood-education-and-care/', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Entry to this qualification is open to individuals who:hold a CHC30121 Certificate III in Early Childhood Education and Care or CHC30113 Certificate III in Early Childhood Education and Care.</li></ul>', `total_course_duration` = '78 weeks full-time', `assessment_style` = 'assignment', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 12851;
