UPDATE `courses` SET `apply_form` = 'https://lhe.edu.au/courses/bachelor-of-community-services-bcs-crs1401730', `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Age requirements; Minimum of 18 years of age on course commencement date.; Qualifications - (One of the following); Australian secondary education qualification, or equivalent qualification from an overseas institution.; Completed or partly completed qualification at AQF level 5 (Diploma) or above from a higher education institution or an equivalent overseas higher education qualification.; Completed Vocational Education and Training (VET) qualification at AQF Level 3 (Certificate III) or above from a vocational education institution or an equivalent overseas vocational education qualification.; Special Tertiary Admission Test (STAT) percentile rank or equivalent.; Completed foundation studies or preparatory program that is recognised for admission purposes.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: 6.0</li><li><strong>PTE Academic:</strong> Pearson Test of English (PTE) Academic (PTE-A): 50 (with not less than 50 in subsets reading and writing)</li><li><strong>TOEFL iBT:</strong> TOEFL iBT: 60 (with min 18 in writing)</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS: 6.0</li><li><strong>PTE Academic:</strong> Pearson Test of English (PTE) Academic (PTE-A): 50 (with not less than 50 in subsets reading and writing)</li><li><strong>TOEFL iBT:</strong> TOEFL iBT: 60 (with min 18 in writing)</li></ul>', `total_course_duration` = '3 years flexible delivery (156 weeks)', `assessment_style` = 'assignment', `intakes` = 'March, 2026', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 13116;
UPDATE `courses` SET `entry_requirements` = '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Age requirements:; Learners must be a minimum age of 18 years or above at the time of course commencement.; Qualifications - (One of the following):; Completion of a bachelor’s degree or higher in any field and IELTS result of 6.5 with no band less than 6.0. However, regarding the English Language requirement, special alternative admission arrangements are as follows:; Minimum academic standards apply to all students, but they can apply for a English test waiver if they can demonstrate:; Work experience of four or more years in full-time employment (in an early childhood context) where the language of employment, both oral and written is English (evidence from the employer is required).; Study experience if applicant has completed at least 3 years of full-time studies in a university where English is the main language of study (evidence from the University is required).</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS result of 6.5 with no band less than 6.0</li></ul>', `english_requirements` = '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS result of 6.5 with no band less than 6.0</li></ul>', `total_course_duration` = '1 year full-time (52 weeks)', `assessment_style` = 'assignment', `intakes` = 'February, 2026', `updated_at` = '2026-11-02 16:20:46' WHERE `id` = 13117;
