-- 3. International Student Scholarships (Course ID 0 = Institution-Wide)
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'ASEAN $10,000 Early Acceptance Scholarship', 'This early acceptance scholarship is awarded to talented international students from the ASEAN region who intend to pursue a coursework degree at Macquarie University, offsetting approximately 25% of their annual tuition fees. Among one of the most g', 'AUD $10000/year', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/asean-10-000-early-acceptance-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'ASEAN Partner Institution Scholarship', 'To recognise the strong relationship between Macquarie University and institutions in the ASEAN region, this ASEAN Partner Scholarship is awarded to prospective students from the region with a quest for knowledge. The scholarship amount is valued up ', 'AUD $15000/year', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/asean-partner-institution-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'Actuarial Excellence Grant - Undergraduate', 'The Actuarial Excellence Grant is a merit-based grant for students commencing a Bachelor\'s degree in Actuarial Studies.', 'Up to AUD $2500', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/actuarial-excellence-grant-undergraduate', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'Bangladesh $10,000 Early Acceptance Scholarship', 'This scholarship offers talented international students from Bangladesh AUD $10,000 per year towards their studies at Macquarie University. The scholarship is available for the full duration of an eligible Bachelor\'s and Master\'s coursework degree. F', 'AUD $10000/year — Applicants will be assessed automatically for this scholarship. Successful candidates will receive the scholarship with their Course Letter of Offer.', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/bangladesh-10-000-early-acceptance-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'English Language Scholarship for Sponsored Students', 'The English Language Scholarship is awarded to students who wish to study an undergraduate or postgraduate course and improve their English.', '100% of English Language Program tuition fees for up to 10 weeks', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/english-language-scholarship-for-sponsored-students/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'Faculty of Science and Engineering Women in STEM Scholarship', 'Recognising excellence in Science, Information Technology and Engineering, this scholarship is to fund female-identifying scholars based on excellence and equity, to encourage and support female-identifying scholars to undertake a career in STEM.', 'Up to AUD $5000', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/faculty-of-science-and-engineering-women-in-stem-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'India $10,000 Early Acceptance Scholarship', 'This scholarship is awarded to eligible students from India who are commencing a coursework degree at Macquarie University.', 'See scholarship details', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/india-10-000-early-acceptance-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'Macquarie Advantage Humanitarian Scholarship', 'The Macquarie Advantage Humanitarian Scholarship provides full tuition fee support for students from refugee and asylum‑seeking backgrounds to undertake undergraduate study at Macquarie University.This scholarship is awarded for the full duration of ', '100% of total tuition fees', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/macquarie-advantage-humanitarian-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
