INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'Macquarie University Alumni Scholarship', 'This scholarship is awarded to all eligible Macquarie University alumni international students for postgraduate studies.', '10% of total tuition fees', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/macquarie-university-alumni-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
