INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'Macquarie University EPIISOD Macquarie Park Accommodation Scholarship - Partial scholarship', 'EPIISOD Macquarie Park provides purpose-built student accommodation. Enjoy a vibrant student lifestyle in the heart of Macquarie Park, just a short walk to campus and only minutes by metro to the Sydney CBD - take a virtual tour of the accommodation ', 'The Scholarship will cover partial fee ($350 student contribution per week) of the accommodation fees for up to 52 weeks in EPIISOD accommodation.', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/macquarie-university-epiisod-macquarie-park-accommodation-scholarship-partial-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
