INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'Partner Institution Scholarship', 'To recognise the strong relationship between Macquarie University and its partner institutions, the Partner Institution Scholarship is awarded to high performing prospective students with a quest for knowledge. The competitive scholarship is valued u', 'AUD $15000/year — This scholarship is valid for the full duration of the course. AUD $7,500 will be credited each session.', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/partner-institution-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'SQA Undergraduate Research Scholarship', 'The program aims to provide students partway through their undergraduate degree with an opportunity to develop their research skills and inspire them to consider further quantum technology research or related activities. Candidates undertake an excit', 'Up to AUD $3333 — One-off payment.', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/sqa-undergraduate-research-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
