INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 127, 'Vice-Chancellor\'s International Scholarship', 'The Vice-Chancellor’s International Scholarship (VCIS) is awarded to recognise academic excellence for international students. This is a highly competitive scholarship based on academic merit and is awarded to talented students intending to pursue a ', 'AUD $10000/year', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/vice-chancellor-s-international-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
