INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 128, 'Australian Government Research Training Program (RTP) Stipend Scholarship - International', 'The Australian Government Research Training Program (RTP) Stipend Scholarship provides a living allowance for high-quality research higher degree students. They are awarded on academic merit and research experience and/or potential.', 'Up to AUD $132111 — The Australian Government Research Training Program (RTP) Stipend Scholarship provides a living allowance for high-quality research higher degree students. They are awarded on academic merit and research experience and/or potentia', 'https://www.une.edu.au/scholarships/higher-degree-research-scholarships/australian-government-research-training-program-rtp-stipend-scholarship-international', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 128, 'Bursaries', 'UNE offers eligible commencing international students a bursary in the form of a 20% fee reduction of the published 2025 annual international tuition fees for their first year of study.', 'See scholarship details', 'https://www.une.edu.au/international/fees-and-scholarships/scholarships-and-other-financial-support/bursaries', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 128, 'Machine Learning modelling to analyse medical and educational data including imaging, video and text-based reports.', 'The project is looking at developing research-based models for data analytics using AI and Machine learning techniques in the domains of medical and educational data analytics. These models will assist and facilitate the medical professionals with ma', 'Up to AUD $129017', 'https://www.une.edu.au/scholarships/higher-degree-research-scholarships/machine-learning-modelling-to-analyse-medical-and-educational-data-including-imaging-video-and-text-based-reports.', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 128, 'Zero Net Emissions Agriculture CRC Scholarship (guidance for on-farm greenhouse gas accounting)', 'Australian agriculture faces growing pressure to quantify, report, and reduce its greenhouse gas (GHG) emissions. Yet the methodological foundations for on-farm GHG accounting remain inconsistent across industry calculators, national inventory method', 'Up to AUD $132111 — This scholarship supports a PhD candidate to develop nationally consistent, practical guidance for on-farm greenhouse gas accounting in Australian agriculture, as part of the Zero Net Emissions Agriculture CRC. The research will e', 'https://www.une.edu.au/scholarships/higher-degree-research-scholarships/zero-net-emissions-agriculture-crc-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
