INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 1, 'Autism Inclusion Equity Scholarship Blacktown Campus', 'This scholarship was established to support students with autism who will be commencing undergraduate studies at ACU\'s Blacktown campus.', 'Up to AUD $4000 — This scholarship is valued at $4,000, to be paid in one lump sum.', 'https://acu.smapply.io/prog/autism_inclusion_equity_scholarship_blacktown_campus/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
