INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Department of Marketing Honours Scholarship', 'The Marketing Honours Scholarship recognises outstanding academic achievement and supports high-performing students entering the Bachelor of Commerce (Honours) program majoring in Marketing at Monash University. This scholarship provides financial su', 'Up to AUD $6000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/department-of-marketing-honours-scholarship-6288', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Econometrics Honours Memorial Scholarship', 'These prestigious scholarships are awarded in memory of the tragic events that took place during October 2002 in the Department Econometrics and Business Statistics, and its honours students. A major fundraising campaign was launched by the Econometr', 'Up to AUD $15000 — $15,000 for one year only (48 credit points of study).', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/econometrics-honours-memorial-scholarship-5586', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Engineering Accommodation Scholarship', 'Elevate your Engineering Experience with our Accommodation Scholarship! Immerse yourself in a vibrant, supportive community of students while receiving financial support for your housing needs. Choose from a range of comfortable accommodation options', 'See scholarship details', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-accommodation-scholarship-6238', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Engineering Industry Teams Scholarship', 'Industry Teams is a supervised industry project where a team of students work collaboratively with Monash University and/or an industry partner to address a defined project need. Based primarily at the Monash Innovation Labs, each project involves a ', 'Up to AUD $4500 — $4,500 per student paid over 6 months only ($2,250 paid over 2 consecutive quarters).', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-industry-teams-scholarship-6279', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Engineering International High Achievers Scholarship', 'The Engineering International High Achievers Scholarship is introduced to recognise high achieving international students.', 'Undergraduate - $15,000 per 48 credit points, paid towards your tuition fees, up to four years.; Postgraduate - $15,000 per 48 credit points, paid towards your tuition fees.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-international-high-achievers-scholarship-6204', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Engineering Masters Pathway Scholarship', 'A scholarship for high-achieving Year 12 students intending to enrol in the Bachelor of Engineering (Honours) and Master of Engineering pathway program. Up to 10 scholarships valued at up to $30,000 are available each year.', 'Up to AUD $6000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-masters-pathway-6056A', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Eric Dubsky Memorial Engineering Leadership Scholarship', 'Eric Dubsky was an electrical engineer who immigrated to Australia from Nazi occupied Austria shortly before the outbreak of World War II in 1939. Initially with his father and then as chairman and managing director he developed a small manufacturer ', 'Up to AUD $30000 — $10,000 per annum for a maximum of three years.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/eric-dubsky-memorial-5719', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Faculty of IT International Merit Scholarship', 'This scholarship is for international students committed to studying at the Faculty of Information Technology at Monash. It aims to attract and reward high achieving international students from India, Sri Lanka and Bangladesh to the faculty. This sch', '20% off tuition fees paid for the duration of the course.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/faculty-of-it-international-merit-scholarship-6232', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Finance Honours Grant', 'This scholarship supports academically outstanding students undertaking the Bachelor of Commerce (Honours) majoring in Finance.', 'Up to AUD $6000 — $6000 one-off payment.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/finance-honours-scholarship-6128', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Freemasons John Dann Music Scholarship', 'The Freemasons John Dann Music Scholarship was established to support talented students within the Sir Zelman Cowen School of Music and Performance at Monash University.', 'Up to AUD $6000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/freemasons-john-dann-music-scholarship-6226', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Ian Little Honours Scholarship', 'A scholarship for students intending to pursue an economics honours degree at Monash Business School: Bachelor of Commerce (Honours) or Bachelor of Economics (Honours). Based on academic achievement, you will be awarded a $15,000 scholarship if selec', 'Up to AUD $15000 — $15,000 paid for one year only.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/ian-little-honours-scholarship-5769', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Information Technology Industry-Based Learning Placement Grant', 'This grant is awarded to high achieving students in the Faculty of Information Technology who undertake a 22 week placement with an industry partner. The grants provide support to the recipients as they benefit from the industry-based experience gain', 'Up to AUD $19000 — $19,000; 22 week placement with one of the industry partners of the Faculty of Information Technology.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/information-technology-ibl-placement-grant-5607', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Klaus Abbink Honours Scholarship', 'This scholarship is awarded in memory of Klaus Abbink, a Professor in Economics at Monash and a Director of The Monash Laboratory for Experimental Economics (MonLEE). Professor Abbink was regarded as a great supervisor and teacher for his students, a', 'Up to AUD $15000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/klaus-abbink-honours-scholarship-6241', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'MD-PhD Industry Leaders Scholarship (for returning MD-PhD students)', 'This scholarship is awarded to Monash University medical students who have demonstrated a commitment to becoming a clinician scientist by undertaking the Monash University intercalated MD-PhD pathway. The successful recipients must have been enrolled', '$15,000 to be paid to students who submit their PhD thesis before the FY32 census date in the year that they return to their BMedSc/MD degree.; $7,500 to be paid to students who submit their PhD thesis between the FY32 census date and the Semester 2 ', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/md-phd-industry-leaders-scholarship-for-returning-md-phd-students-6271', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Master of Applied Econometrics PHD Pathway Scholarship', 'Are you passionate about econometric model building, estimation and forecasting for economic decision-making ? Elevate your career in economics with the Master of Applied Econometrics (with PhD pathway) scholarship. This prestigious opportunity is de', 'Up to AUD $15000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/master-of-applied-econometrics-phd-pathway-scholarship-6269', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Master of Commerce Scholarship', 'The Master of Commerce is a research-oriented programme preparing students for a PhD and an academic career. Offered as part of an Integrated PhD program, the MCom may be completed in one or two years, depending on the specialisation and the student\'', 'Tuition fees paid, plus an allowance of $37,145 (the equivalent to the 2026 PhD stipend rate).', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/master-of-commerce-scholarship-6161', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Maxwell King PhD Scholarship', 'The Maxwell King Scholarship (MKS) is named after Professor Maxwell King, who has made an outstanding contribution to graduate research at Monash University, including eight years as Pro Vice-Chancellor (Research and Research Training). This prestigi', 'Up to AUD $52352', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/maxwell-king-phd-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Medicine and Artificial Intelligence Honours Scholarship', 'The Monash Interdisciplinary Research Academy of Medical AI (MIRAMA) is a collaborative Honours initiative that brings together expertise from the Faculty of Medicine, Nursing and Health Sciences (FMNHS), the Faculty of Information Technology (FIT), ', 'Up to AUD $6000 — $6000 per 48 credit points of study for one year honours only.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/medicine-and-artificial-intelligence-honours-scholarship-6301', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Medicine, Nursing and Health Sciences Equity Travel Grant', 'This scholarship is available to one student enrolled in the Bachelor of Medicine and Bachelor of Surgery (MBBS) and one student enrolled in another degree in the Faculty of Medicine, Nursing and Health Sciences. It is awarded on the basis of achieve', 'Up to AUD $2000 — $2000 one-off payment.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/medicine-nursing-and-health-sciences-equity-travel-grant-5647', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Microbiology in Water Engineering Scholarship', 'The Microbiology in Water Engineering scholarship be introduced to encourage students to begin thinking about the interdisciplinary of planetary health and in particular health related water microbiology. The scholarship will support students who are', 'Up to AUD $5000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/microbiology-in-water-engineering-scholarship-6142', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Monash Academy of Performing Arts Orchestral Scholarship', 'The Monash Academy of Performing Arts Orchestral Scholarship intends to support and develop the student cohort of Monash Academy Orchestra.', 'Up to AUD $3000 — $3000 for one year only (48 credit points of study)', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-academy-of-performing-arts-orchestral-scholarship-6137', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Monash Graduate Impact 2030 Scholarship', 'These scholarships are awarded to students whose research aligns with one of the University Global Challenges (e.g. Thriving Communities, Climate Change and Geopolitical Security) as outlined in Impact 2030. The scholarship is available to support st', 'Up to AUD $53608', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-graduate-impact-2030-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Monash Graduate Scholarship', 'Monash Graduate Scholarships (MGS) are provided by Monash University to support domestic and international students undertaking Research Doctorate and Research Masters degrees. A MGS is available to help support students with living costs whilst stud', 'Up to AUD $36063 — $35,013 p.a (2024 rate)', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-graduate-scholarship-mgs', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Monash Humanitarian Scholarship', 'Are you an asylum seeker on a bridging visa? If you are a high-achieving student with the ambition to change your future through undergraduate study at Monash University, you may be eligible for the Monash Humanitarian Scholarship. You will receive 1', 'Full course fees plus up to $30,000 allowance; An allowance of $6000 per year (48 credit points of study) until the minimum credit points for your undergraduate degree are completed.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-humanitarian-scholarship-7004', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Monash International Leadership Scholarship', 'International students from all countries who have received an undergraduate course offer from Monash will automatically be considered for the Monash International Leadership Scholarship. As a scholarship recipient you will receive a 100% tuition spo', '100% course fees paid until the minimum number of points for your degree are completed (excludes OSHC, accommodation and living costs).', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-international-leadership-scholarship-5571Z', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Monash International Merit Scholarship', 'International students from all countries who have received an undergraduate course offer from Monash will automatically be considered for the Monash International Merit Scholarship. As a scholarship recipient, you will receive $15,000 per annum for ', '$15,000 per annum (48 credit points of study) paid per year until the minimum number of points for your degree is completed (For scholarships awarded from 2026).; $10,000 per annum (48 credit points of study) paid per year until the minimum number of', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/international-merit-5770', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Monash International Tuition Scholarship (MITS)', 'Monash International Tuition Scholarships (MITS) are provided by Monash University to support international students undertaking Research Doctorate and Research Masters degrees. A MITS covers the course tuition fees that would otherwise be payable by', 'Monash International Tuition Scholarship covers the cost of:; course tuition fees AND; a single Overseas Student Health Cover (OSHC) policy.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/international-tuition-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Monash Jazz Music Scholarship', 'A $6000 award for outstanding Monash music students specialising in jazz. This scholarship is established from funds received from an anonymous donor.', 'Up to AUD $6000 — $6000 per annum (48 credit points of study) paid for a maximum of one year only.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-jazz-music-scholarship-5680', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Monash Mauritius Award', 'The Monash Mauritius Award provides support to new international students at Monash University, Australia.', '15% or 20% tuition fee reduction applied annually for the duration of your program for up to 3 years (144 credit points).', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-mauritius-award-6308', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Monash Peer Mentoring Leaders Scholarship', 'The Peer Mentoring Leaders Scholarship is awarded to Monash Peer Mentoring Coordinators each year in recognition of their service and leadership in the peer mentoring community. Peer Mentoring Coordinators work closely with the Faculty and Portfolio ', 'Up to AUD $6000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-peer-mentoring-leaders-scholarship-7104', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
