INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Monash University-Vietnam Government PhD Scholarship', 'This joint scholarship program supports high-achieving Vietnamese candidates to undertake a PhD at Monash University. Applicants can elect to study at a Monash campus in Australia or be based at a Vietnamese University, jointly supervised as an exter', 'Varies - see benefits', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-university-vietnam-government-phd-scholarship-project-89', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
