INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Nicholas Auden International Study Scholarship', 'This scholarship assists outstanding JD or Bachelor of Laws students to undertake an international pathway programs. The scholarship was introduced in 2014, as part of the Faculty\'s 50th anniversary celebrations.', 'Up to AUD $10000 — $10,000 paid in one instalment for one year only. To be used only for travel and living expenses and course fees for the relevant pathway program being undertaken by the recipient.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/nicholas-auden-international-study-scholarship-5804', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Nutrition Science Scholars Scholarship', 'The Nutrition Science Scholars Scholarship has been introduced to recognise the excellence of our students who will be enrolled in the Bachelor of Nutrition Science (Scholar Program).As a Scholar Scholarship student, you’ll be guaranteed entry into o', 'AUD $3000/year — $3000 per 48 credit points of study for the minimum number of credit points required to complete the degree to a maximum of three years', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/nutrition-science-scholars-scholarship-6234', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Pharmacy and Pharmaceutical Science International Merit Scholarship', 'This scholarship is for international students committed to studying Pharmacy or Pharmaceutical Science at Monash. It aims to attract and reward high achieving international students to the faculty.', '50% of tuition fees paid per year until the minimum credit points for your degree are completed (awarded to the highest achieving student in each of the four course groups nominated).; 25% of tuition fees paid per year until the minimum credit points', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/pharmacy-international-merit-scholarship-5745', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Raydon Graduate Research Scholarships', 'These prestigious top up scholarships are available to help support graduate research students studying in relevant Humanities and Social Sciences study areas with living costs whilst studying at a Monash campus in Australia. The Raydon Scholarships ', 'Up to AUD $23837 — Raydon scholarships provide a living allowance top up (stipend).', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/raydon-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Research Training Program (RTP) Stipend', 'Research Training Program (RTP) Scholarships are provided by the Australian Government to support both domestic and international students undertaking Research Doctorate and Research Masters degrees. As part of this program, a RTP Stipend (living all', 'AUD $36063/year — The RTP Stipend provides: a living allowance (stipend), and; a relocation allowance, if eligible.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/research-training-program-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Resident Advisor Scholarship', 'This scholarship recognises the commitment to the residential community made by volunteer Resident Advisors, who live in Monash University Accommodation.', 'Up to AUD $6139 — Up to $6139', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/mrs-residential-advisor-scholarship-5692', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Ross Booth Honours Scholarship', 'This scholarship is awarded in memory of Ross Booth (1952-2024), a long-serving member of the Department of Economics and Course Director of the BCom and BEc at the Clayton and Malaysia campuses. An enthusiastic supporter of the BCom Honours program,', 'Up to AUD $15000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/ross-booth-honours-scholarship-6272', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Sir James McNeill Postgraduate Research Scholarship', 'The Sir James McNeill Postgraduate Research Scholarship (SJMN) is funded by a private trust and was established in memory of the late Sir James McNeill, who had a long association with Monash University. This prestigious scholarship is available for ', 'AUD $52352/year', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/sir-james-mcneill-postgraduate-research-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Sir John Monash Scholarships for Excellence', 'This scholarship is offered to the 10 highest-achieving international students studying Australian Year 12 or International Baccalaureate in Australia. If you have an ATAR of 98.00+ or equivalent, you will be automatically considered for this scholar', 'Up to AUD $40000 — $10,000 per annum (48 credit points of study), up to a maximum of four years.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/Sir-John-Monash-Scholarships-for-Excellence-7200', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Skilled Industry Placement Scholarship', '-', 'Up to AUD $14300 — $14,300 paid in three instalments.; 24 week placement with one of the host sites in the SKILLED clinical trials internships program.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/skilled-industry-placement-6166', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Summer and Winter Vacation Research Scholarship Program', 'Summer and winter research scholarships are run over the summer and winter breaks. If you’re interested in a research career or furthering your studies through an honours program, this is a great opportunity to get ahead over the holidays.', 'The value varies', 'https://www.monash.edu/study/fees-scholarships/scholarships/summer-winter', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'TNE Engineering Achievement Scholarship', 'Are you a high-achieving student from a partner university looking to pursue engineering excellence at Monash University? At Monash, we believe in recognising talent from around the world and fostering global connections in engineering education. Tha', 'Up to AUD $6000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/tne-engineering-achievement-scholarship-6251', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Team Monash Elite Student Performer Grant', 'The Team Monash Elite Student Performer Grant is designed to support talented students studying at Monash to represent the University in the areas of Sport, Performing Arts and related disciplines. This grant aims to assist students who perform at a ', 'Up to AUD $1000 — $100 to $1000 one-off payment and/or a Monash Sport gym membership.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/team-monash-elite-student-performer-grant-5609', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'The Koto Dream Scholarship', 'The Koto Dream Scholarship is designed to support outstanding Know One, Teaching One (KOTO) alumni who demonstrate strong academic potential, leadership capacity, and a clear commitment to social impact, enabling them to pursue undergraduate studies ', '100% tuition sponsorship for course duration (maximum of three years)', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/the-koto-dream-scholarship-6291', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'UEC Excellence Award', 'The UEC Excellence Award is awarded by Monash to three of the highest achieving commencing students from the Unified Examination Certificate (UEC) schools network in Malaysia. It underscores our commitment to seek out, reward and support students who', 'Up to AUD $30000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/uec-excellence-award-6275', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Verrocchi Charity Fund Pharmacy Prato Scholarship', 'The scholarship provides support to students in the Faculty of Pharmacy and Pharmaceutical Sciences undertaking an international immersion through the Monash Global Campus Intensive program in Prato. This program builds the cultural competence and gl', 'Up to AUD $6000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/verrocchi-charity-fund-pharmacy-prato-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Vice Chancellor\'s ASEAN Award', 'The Vice-Chancellor\'s ASEAN Award supports high-achieving undergraduate students to study at Monash, reinforcing our deep commitment and connection to the region - socially, economically and culturally. The program is designed to ease the full cost o', '20% tuition fees paid up to 3 years.', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/vice-chancellors-asean-award-6280', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Vice-Chancellor ASEAN Award for Onshore School Leavers', 'The Monash Vice Chancellor ASEAN Onshore School Leavers award for International Students celebrates high-achieving international students with nationalities from ASEAN countries enrolling in an undergraduate (coursework) degree at a Monash campus in ', 'Up to AUD $76719 — 20% tuition fees paid per annum for up to 3 years', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/vice-chancellor-asean-award-for-onshore-school-leavers-6286', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Vice-Chancellor International School Leaver Award', 'The Monash Vice Chancellor School Leavers Award for International Students celebrates high-achieving international students enrolling in an undergraduate (coursework) degree at a Monash campus in Australia.', 'Up to AUD $15000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/vice-chancellor-international-school-leaver-award-6287AB', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Wilson Transformer Company Engineering Leadership Scholarship', 'This scholarship is awarded to a high-achieving student who is currently enrolled in third year of an electrical and computer systems engineering degree in the Faculty of Engineering.', 'Up to AUD $20000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/wilson-transformer-company-scholarship-5817B', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 129, 'Women in Engineering Scholarship', 'At Monash, we support bright young women who wish to study engineering. If you are a high-achieving student intending to pursue an undergraduate degree at Monash in engineering, you may be eligible for this scholarship. No application is required. Yo', 'Up to AUD $6000', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/women-in-engineering-scholarship-5583', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 132, 'Australian Government Research Training Program (RTP) Scholarships', 'The Australian Government Research Training Program (RTP) stipends are provided to support the general living costs of both domestic and overseas students undertaking research doctorate degrees.', 'The Australian Government Research Training Program (RTP) stipends are provided to support the general living costs of both domestic and overseas students undertaking research doctorate degrees.', 'https://bond.edu.au/scholarship/australian-government-research-training-program-rtp-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 132, 'Bond Business School Postgraduate Bursaries', 'The Bond Business School Postgraduate Bursaries were designed to provide financial assistance to new postgraduate students enrolling in programs within the Bond Business School. Bursaries are provided to those who can demonstrate their positive contr', 'As a Bond Business School Postgraduate Bursary recipient, you will be awarded with a cash payment of $4,200 to help with your living expenses while you study at Bond University (paid in two equal instalments).As a Postgraduate Bursary applicant, you ', 'https://bond.edu.au/scholarship/bond-business-school-postgraduate-bursaries', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 132, 'Bond University Canadian Juris Doctor 25th Anniversary Scholarship', 'Bond University has proudly been training aspiring Canadian lawyers for 25 years. Since 2001, graduates have gone on to establish successful careers as legal practitioners and professionals across Canada and all over the world. To celebrate 25 years ', 'Valued at 25% tuition remission, all Canadian students who submit an application for Bond’s Juris Doctor, to commence in any semester between September 2025 and September 2027', 'https://bond.edu.au/scholarship/bond-university-canadian-juris-doctor-25th-anniversary-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 132, 'Bond University College (BUC) Academic Excellence Scholarship', 'Each semester, the Bond University College (BUC) Academic Excellence Scholarship recognises and rewards an outstanding student from the Bond University College Foundation Program (CRICOS 063151G) who has achieved exceptional academic results. The sch', 'Provides a 25% tuition fee reduction for the duration of the recipient’s undergraduate degree at Bond University.', 'https://bond.edu.au/scholarship/bond-university-college-buc-academic-excellence-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 132, 'Bond University Postgraduate Research Scholarship', 'Bond University values its higher degree research student cohort and provides a substantial level of direct financial support to many students. Bond University allocates funds to support the financial costs of fee offset (waiver) and living stipends.', 'See scholarship details', 'https://bond.edu.au/scholarship/bond-university-postgraduate-research-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 132, 'Excellence Scholarship', 'Excellence Scholarships are awarded to those who demonstrate high academic achievement, as well as leadership skills and community involvement. As an Excellence Scholar, you will be awarded with 50% tuition remission for any single or approved combin', 'Provides 50% tuition remission for any single or approved combined undergraduate degree (excluding the Bond Medical Program and Diploma entry students).', 'https://bond.edu.au/scholarship/excellence-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 132, 'International Stand Out Scholarship', 'Bond International Stand Out Scholarships provide tuition remission scholarships to standout students applying to study at an undergraduate or postgraduate level. International Stand Out Scholarships are awarded on the basis of academic merit, and ar', 'See scholarship details', 'https://bond.edu.au/scholarship/international-stand-out-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 132, 'International Undergraduate Excellence Scholarship', 'Bond International Undergraduate Excellence Scholarships provide tuition remission scholarships to high academic achievers, applying to study a bachelor’s degree.International Undergraduate Excellence Scholarships are awarded on the basis of academic', 'See scholarship details', 'https://bond.edu.au/scholarship/international-undergraduate-excellence-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 132, 'Leadership Scholarship', 'Our Leadership Scholarships aim to recognise current Year 12 students who have outstanding leadership experience and community involvement with a partial-fee tuition remission scholarship. Leadership Scholarships are awarded to students who demonstra', 'Provides 25% tuition remission for any single or approved combined undergraduate degree (excluding the Bond Medical Program and Diploma entry students).', 'https://bond.edu.au/scholarship/leadership-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 132, 'Transformer Scholarship', 'The Transformer is a co-curricular program that enable students to innovatively tackle real-world problems that matter. It attracts motivated, self-directed individuals who want to work in collaborative, interdisciplinary teams on challenging project', 'Provides 50% tuition remission for any undergraduate degree including approved combined programs up to 320 credit points (excluding the Bond Medical Program), or postgraduate degree (excluding research degrees).', 'https://bond.edu.au/scholarship/transformer-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 133, 'IB Diploma', 'Scholarships available for RMSC students in year 11 from 2022', 'AUD $1500/year — AUD $1500 cost is for the 2 year Diploma. The cost covers student subject and registration fees which are paid to the IBO', 'https://search.studyaustralia.gov.au/scholarship/ib-diploma/3006f5822ee407b8a9608c894608a13e', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 134, 'Regional bursary for TAFE international students', 'Your adventure awaits! Enjoy long stretches of perfect coastline in the mid west, forests and mountains in the south west, or tropical deserts and sandy beaches in the north. The WA Regional TAFE International Student Bursary gives international stud', 'Up to AUD $5000', 'https://www.tafeinternational.wa.edu.au/tafe-courses/regional-bursary-tafe-international-students?', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'A.G. McCready Memorial Scholarship', 'Established in 1996 by Mrs I.C. McCready in memory of her late husband Alfred Glen McCready, who was admitted to the degree of Bachelor of Arts with First Class Honours in Classics and awarded the University Medal for outstanding merit in 1940 and wh', 'Equal to the annual income from the fund', 'https://scholarships.uq.edu.au/scholarship/ag-mccready-memorial-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'ARC Centre of Excellence for Indigenous Futures Top-Up Scholarship', 'The Indigenous Futures Centre is excited to support the next generation of Indigenous researchers. In addition to offering an attractive top-up scholarship and research support funds, the Centre provides its PhD candidates with training, mentoring an', '$20,000 per annum; $5000 per annum research support funds', 'https://scholarships.uq.edu.au/scholarship/arc-centre-excellence-indigenous-futures-top-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'Alumni Pride Scholarship', 'Established in 2024 through a gift from Alumni Friends, Professor Heather Zwicker and collective donors under the Queensland Commitment scheme and maintained by income generated from an underlying endowment fund. Alumni Friends of The University of Q', 'Up to AUD $4500 — $4,500 (limited to the annual income from the fund)', 'https://scholarships.uq.edu.au/scholarship/alumni-pride-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'Archibald Scholarship', 'This scholarship was founded in 1911 by an initial gift of $1,000 from the beneficiaries in the estate of the late Honourable John Archibald, MLC.', 'Up to AUD $10000 — The scholarship is valued at $10,000 for 1 year.', 'https://scholarships.uq.edu.au/scholarship/archibald-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'Au Family Scholarship', 'Established in 2025 through an absolute gift from the Au Family.', 'Up to AUD $6300', 'https://scholarships.uq.edu.au/scholarship/au-family-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'Barbara Hebden Music Bursary', 'This scholarship was established in 2016 by an endowed bequest from the estate of UQ alumna and music critic, Barbara Jean Hebden OAM (BA 1952).', 'Equal to the annual income from the fund.', 'https://scholarships.uq.edu.au/scholarship/barbara-hebden-music-bursary', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'Business Scholarship for Chinese Students', 'Established in 2013 by the Chin Family Trust.', 'Up to AUD $1000', 'https://scholarships.uq.edu.au/scholarship/business-scholarship-chinese-students', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'Business School Honours Tuition Fee Reduction Scholarship', 'The purpose of this scholarship is to attract and encourage high-achieving students to the Business School Honours program.', 'Up to AUD $10000', 'https://scholarships.uq.edu.au/scholarship/business-school-honours-tuition-fee-reduction-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'Business School Master of Business Analytics - Women in STEM Scholarship', 'The Postgraduate Coursework Master’s Scholarship was established to encourage and support high performing women to undertake postgraduate study related to digital transformation, thus retaining and improving the representation of women in the STEM wo', 'Up to AUD $5000', 'https://scholarships.uq.edu.au/scholarship/business-school-master-business-analytics-women-stem-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'CONACYT Mexican Scholarship Program', 'The CONACYT Mexican Scholarship aims to provide Mexican citizens with funding to support studies overseas at the point of admission or while they are undertaking studies abroad to enhance their skills in areas of Science, Technology and Innovation an', 'Partially funded tuition fees, living allowance; Master maximum 2 years, PhD maximum 4 years', 'https://scholarships.uq.edu.au/scholarship/conacyt-mexican-scholarship-program', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'CSC-UQ PhD Scholarship (China Scholarship Council)', 'Successful applicants who are offered a place in the University\'s PhD program and are supported by their School will also receive a Tuition Fee Scholarship (for up to four years) that covers your PhD tuition fees, along with a living allowance top up', 'Living allowance, health insurance in Australia, one return airfare from China to Australia, your Australian Student Visa application fees, and a UQ tuition fee scholarship', 'https://scholarships.uq.edu.au/csc', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'Calboonya Legacy Information Technology and Computer Science Scholarship', 'Established in 2019 this scholarship is maintained by a gift from a UQ Bachelor of Computer Science (1979) alumni husband and wife, who in recognition of the encouragement they received to pursue their education would like to leave a legacy for stude', 'Up to AUD $4500', 'https://scholarships.uq.edu.au/scholarship/calboonya-legacy-information-technology-and-computer-science-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'Florence Davey Pianoforte Scholarship', 'This Scholarship was first established in 1983 and was funded by donations in excess of $50,000 from Miss Florence M. Davey. The Scholarship fund continues to be maintained by UQ on trust. Miss Florence M. Davey, Associate, Licentiate and Fellow of T', 'AUD $10000/year', 'https://scholarships.uq.edu.au/scholarship/florence-davey-pianoforte-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'Graduate School Scholarships (UQGSS) - includes Research Training Program (RTP)', 'These scholarships include a living stipend to support you as you complete a research project for your Doctor of Philosophy, Master of Philosophy or a research-focused professional doctorate at UQ.', 'AUD $35000/year — 3.5 years with the possibility of 1 extension in line with UQ and RTP Scholarship Policy', 'https://scholarships.uq.edu.au/scholarship/graduate-school-scholarships-uqgss-%E2%80%93-includes-rtp', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 135, 'Howard and Gladys Sleath Scholarship', 'Established in 1998 following Howard Sleath\'s bequest of 50% of his estate to the University of Queensland. Mr Howard Sleath was well-known to instrumentalists throughout Australia for the excellence of his craftsmanship and skill as a maker of strin', 'Up to AUD $10000 — Equal to the annual income from the fund.', 'https://scholarships.uq.edu.au/scholarship/howard-f-and-gladys-sleath-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
