INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 136, 'Elvita Eveline Clough Cancer Research Scholarship', 'Stipend scholarship to support PhD students within the Faculty of Medicine and Health.', 'The Scholarship will provide a stipend allowance equivalent to the University of Sydney Research Training Program (RTP) Stipend rate (indexed on 1 January each year) up to 3.5 years, subject to satisfactory academic performance.', 'https://www.sydney.edu.au/scholarships/c/elvita-eveline-clough-cancer-research-scholarship.html', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
