INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 136, 'George Harris Scholarships (Chemistry)', 'A $400 scholarship for a PhD student within School of Chemistry who have contributed to the teaching activities.', 'Up to AUD $400 — This scholarship is valued at $400 and is paid as a lump sum payment upon award.', 'https://www.sydney.edu.au/scholarships/d/george-harris-scholarships--chemistry-.html', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 136, 'Henry Bertie and Florence Mabel Gritton Research Scholarships', 'A University of Sydney RTP rate scholarship to support a student willing to undertake research at the University of Sydney.', 'This scholarship will provide an annual stipend allowance equivalent to the University of Sydney RTP rate (indexed on 1 January each year) for up to three years and six months, subject to satisfactory academic performance', 'https://www.sydney.edu.au/scholarships/d/henry-bertie-and-florence-mabel-gritton-research-scholarships.html', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 136, 'Henry Langley Scholarship', 'Stipend scholarship to support postgraduate research in the Faculty of Medicine and Health.', 'The Scholarship will provide a stipend allowance equivalent to the University of Sydney Research Training Program (RTP) Stipend rate (indexed on 1 January each year) up to 3.5 years, subject to satisfactory academic performance.', 'https://www.sydney.edu.au/scholarships/c/henry-langley.html', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 136, 'James Millner Scholarship in Pharmacy', 'A stipend allowance awarded to a PhD student conducting research in pharmacy at the Faculty of Medicine and Health, University of Sydney.', 'USYD RTP rate p.a. (up to 3.5 years)', 'https://www.sydney.edu.au/scholarships/c/james-millner-scholarship-in-pharmacy.html', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 136, 'Sydney Global Mobility Joint PhD Travel Scholarship', 'A $5000 scholarship to assist students to complete the offshore component of their Joint PhD Program.', 'Up to AUD $5000 — This scholarship will provide a one-off payment of $AUD 5000 for one year.', 'https://www.sydney.edu.au/scholarships/e/sydney-global-mobility-joint-phd-travel-scholarship.html', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 136, 'Sydney International Student Award', 'The Sydney International Student Award celebrates our diverse and talented community of international students. We want to help motivated applicants to achieve their personal and academic goals, by supporting their study at the University of Sydney.', 'Recipients will be awarded a University contribution of 20 percent of their tuition fee for the duration of their course.', 'https://www.sydney.edu.au/study/fees-and-loans/scholarships/sydney-international-student-award.html', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 139, 'TAFE SA INT Scholarships', 'TAFE SA 2026 International Scholarship Programs are designed to support international students and enhance access to high‑quality vocational education and training in South Australia.\r\n\r\nThe 2026 scholarships recognise academic commitment and support', 'full tuition fees', 'https://www.tafesa.edu.au/international/before-starting/int-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'AGSM Emerging Female Leaders Scholarship', 'The AGSM Emerging Female Leaders Scholarship will enable high potential female leaders to complete a world-class MBA.', 'Minimum of two scholarships are available per year.', 'http://www.business.unsw.edu.au/agsm/scholarships-prizes/mba-full-time-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'AGSM Excellence Scholarship', 'The AGSM Excellence Scholarship will give MBA candidates who have a proven track record of academic and professional excellence an opportunity to participate in AGSM’s Full-Time MBA program.', 'Minimum of six scholarships available.\r\n\r\nFull and partial tuition fee waivers are available for eligible candidates.', 'http://www.business.unsw.edu.au/agsm/scholarships-prizes/mba-full-time-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'AGSM Global Reach Scholarship', 'The AGSM Global Reach Scholarship gives exceptional students from diverse international backgrounds access to AGSM’s Full-Time MBA program located in Sydney.', 'Minimum of six scholarships available, with one recipient per country. These scholarships may be awarded in any admissions round.\r\n\r\nFull and partial tuition fee waivers are available for eligible candidates.', 'http://www.business.unsw.edu.au/agsm/scholarships-prizes/mba-full-time-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'Academic Achievement Awards (AAA)', 'The Academic Achievement Award (AAA) has been established to encourage academically gifted students who have completed an Australian Year 12 qualification from NSW and ACT high schools to undertake undergraduate study at UNSW.2', 'Up to AUD $5000 — $5,000 available for 1 year', 'http://www.scholarships.unsw.edu.au/scholarships/id/1', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'Australia\'s Global University Award (PUCA1026)', 'Australia\'s Global University Award (PUCA1026)', '$10,000 for one year. Payment will be made directly towards tuition fees in the second term of the first year of study.', 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'International Scientia Coursework Scholarship (PUCA1025)', 'International Scientia Coursework Scholarship (PUCA1025)', 'Offer 1: Full tuition fee scholarship paid directly towards tuition fees for the minimum duration of program\r\nOffer 2: $20,000 per annum paid directly towards tuition fees for the minimum duration of program', 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'International Student Award', 'The International Student Award has been established to assist students from low income and developing countries to access education at a highly ranked Australian university. It is available to eligible new students commencing in 2025 and 2026 and pr', 'Provides a 15% contribution directly towards tuition fees.', 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'Lee Whitmont Award in Marketing', 'The purpose of the Scholarship is to support current UNSW students undertaking an undergraduate degree in marketing.', 'Up to AUD $5000 — The scholarship is valued at $4,000 for 1 year.', 'http://www.scholarships.unsw.edu.au/scholarships/id/142', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'Lily and Dr Ben K.C. Chng Scholarship (UGCE1129)', 'The purpose of the Scholarship is to support and encourage students from Singapore to undertake full-time undergraduate study at UNSW Arts, Design and Architectures’ School of Built Environment.', '$5,000 per annum payable for normal minimum duration of degree towards tuition fees.', 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'Scientia Scholarship', 'The UNSW Scientia Scholarship has been established to encourage students who achieve a raw ATAR* score (or equivalent) of 99.90 or above in an Australian Senior Secondary Certificate, or equivalent qualification, to undertake full-time undergraduate ', 'The scholarships are valued at $10,000 per year for the minimum duration of the degree.', 'https://www.scholarships.unsw.edu.au/scholarships/id/102', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'Summer Vacation Research Scholarship', 'Put your summer holidays to good use with a six-week Summer Vacation Research Scholarship. You’ll gain valuable research experience working with our renowned supervisors to participate in a research project. If you’re a talented undergraduate science', 'Each scholarship is $3800 for a six-week research project.', 'https://www.unsw.edu.au/science/student-life-resources/student-opportunities/research-integrated-learning/summer-vacation-research-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 141, 'UNSW Business School International Pathways Award (PUCA1023)', 'UNSW Business School International Pathways Award (PUCA1023)', '$15,000 paid directly towards tuition fees for 1 year.', 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
