INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 142, 'UTS Onshore Postgraduate International Scholarship', 'The purpose of the UTS Onshore Postgraduate International Scholarship is to attract commencing international students already in Australia to enroll in a postgraduate coursework program at UTS.', '25% of UTS tuition fees', 'https://www.uts.edu.au/scholarship/uts-onshore-postgraduate-international-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 142, 'UTS Study Abroad Excellence Scholarship', 'UTS offers merit-based Study Abroad Excellence Scholarship for commencing Study Abroad students. Selection is based on academic excellence in the most recently completed tertiary qualification recognized by UTS for entry in the Study Abroad program. ', 'Up to AUD $2000 — $1,000 - $2,000; Duration 1 Session', 'https://www.uts.edu.au/scholarship/uts-study-abroad-excellence-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
