INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2026 Accommodation Bursary', 'Recipients of the Accommodation Bursary will receive a discounted weekly rental rate equivalent to 50% of the standard published rental fee for eligible on-campus accommodation. The bursary is applicable for two consecutive semesters (in-semester per', 'Recipients of the Accommodation Bursary will receive a discounted weekly rental rate equivalent to 50% of the standard published rental fee for eligible on-campus accommodation.', 'https://www.federation.edu.au/study/scholarships/details/international/accommodation-bursary/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2026 Early Bird Bursary', 'Accept an offer from Federation and pay the deposit as listed on your offer by the given date to receive a one-off bursary in your second year of study.', 'This bursary is awarded as a tuition fee discount in your third semester of study.', 'https://www.federation.edu.au/study/scholarships/details/international/early-bird-bursary/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2026 Federation Merit Scholarship', 'This scholarship is awarded in instalments with the first instalment awarded to successful recipients at the time of offer. Ongoing scholarship instalments will be allocated to awardee\'s student fee account prior to the following census date and on c', 'The scholarship covers 20% of the tuition fees and is initially awarded for a period of two semesters.', 'https://www.federation.edu.au/study/scholarships/details/international/federation-merit-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2026 Federation Pathways Scholarship', 'Federation University Australia is pleased to offer a Pathways Scholarship to international students who commence in a Federation University pathway course in 2026.', 'The Federation Pathways Scholarship is equivalent to 20% of the annual tuition fees of a pathway course such as Foundation or Higher Education Diploma.', 'https://www.federation.edu.au/study/scholarships/details/international/federation-pathways-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2026 Federation Pathways Scholarship', 'By studying a pathway course, such as a Higher Education Diploma, you may receive a percentage off your tuition fee. Get rewarded for boosting your skills and confidence as you prepare for undergraduate study.', 'See scholarship details', 'https://www.federation.edu.au/study/scholarships/details/international/federation-pathways-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2026 Paid Placement Support Guarantee', 'Federation provides support for international students who have mandatory placement units but are not doing Co-op courses. With a minimum payment for the placement hours required in their course - up to $10,000 for undergraduates and $5,000 for postg', 'Up to AUD $10000', 'https://www.federation.edu.au/study/scholarships/details/international/placement-support-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2026 Partner Scholarship', 'The Partner Scholarship is designed to support international students who transfer from Federation partner offshore locations to Australia to complete their studies or begin a new degree. Recipients will get a 20% tuition fee discount.', 'This scholarship is awarded in instalments, with the first instalment awarded to successful recipients at the time of offer. Ongoing scholarship instalments will be allocated to awardee’s student fee account prior to census date each semester.', 'https://www.federation.edu.au/study/scholarships/details/international/partner-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2026 Stanford Advanced Materials College Scholarship', 'As a trusted supplier of advanced materials for industries such as aerospace, technology, healthcare, and energy, Stanford Advanced Materials (SAM) has long been focused on the industrial applications and development trends of rare metals. To explore', 'Up to AUD $1000', 'https://www.samaterials.com/stanford-advanced-materials-college-scholarship.html?utm_source=EDM&utm_medium=scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2027 Accommodation Bursary', 'This scholarship is offered to support international students who choose to live in Federation\'s on-campus accommodation in Victoria. Students will receive 50% off the cost of weekly rent for their first year, and 25% off standard accommodation rates', 'Up to AUD $7278 — New international students joining the FedLiving community at our Mt Helen and Berwick campuses may be eligible for up to $1,000 per semester (for a maximum of two semesters, subject to $550 acceptance fee).', 'https://www.federation.edu.au/study/scholarships/details/international/2027-accommodation-bursary/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2027 Global Achiever Scholarship', 'This tuition fee scholarship provides eligible international students 15% off annual tuition fees for the duration of their course. This scholarship cannot be combined with other tuition fee scholarships.', 'See scholarship details', 'https://www.federation.edu.au/study/scholarships/details/international/2027-global-achiever-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2027 Global Merit Scholarship', 'International students may receive 25% off their annual tuition fees for the duration of their course, based on academic merit. Achieve an average of 75% or equivalent in previous studies to be eligible.', 'See scholarship details', 'https://www.federation.edu.au/study/scholarships/details/international/2027-global-merit-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2027 Paid Placement Support Guarantee', 'This scholarship supports international students who have mandatory placement units but are not doing Co-op courses. Students receive $10,000 (undergraduate) or $5,000 (postgraduate) in instalments to support them while completing their placement.', 'Up to AUD $10000', 'https://www.federation.edu.au/study/scholarships/details/international/2027-placement-support-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, '2027 Partner Scholarship', 'This scholarship supports international students who transfer from an offshore Federation partner provider to one of our campuses in Victoria. Whether continuing their studies in Australia or start a new course, recipients will receive 20% off annual', 'See scholarship details', 'https://www.federation.edu.au/study/scholarships/details/international/2027-partner-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, 'Bridging the distance: Using sport technology to enhance high-performance pathways for rural athletes', 'Overarching Aim of the PhD:Athletes from regional and rural Australia face significant barriers in accessing high-performance sport pathways, including limited access to coaching, sport science support, and elite competition environments. Advances in', 'Up to AUD $50000', 'https://www.federation.edu.au/study/scholarships/details/research/bridging-the-distance-using-sport-technology-to-enhance-high-performance-pathways-for-rural-athletes/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, 'Foundation for Rural and Regional Renewal: Diversity in Regional Telehealth Bursaries', 'The Foundation for Rural & Regional Renewal is the only national foundation specifically focused on ensuring the social and economic strength of Australia\'s remote, rural and regional communities. We understand the big picture, and the fine grain, an', 'See scholarship details', 'https://www.federation.edu.au/study/scholarships/details/foundation-scholarships/foundation-for-rural-and-regional-renewal-diversity-in-regional-telehealth-bursaries2/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 3, 'Vice-Chancellor\'s Award (Semester 1 2027)', 'The Vice-Chancellor\'s Award is a 50% tuition fee scholarship that recognises and supports outstanding academic achievers from specific regions of Asia.', 'See scholarship details', 'https://www.federation.edu.au/study/scholarships/details/international/vice-chancellors-award-semester-1-2027/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 4, 'International Excellence Scholarship', 'The International Excellence Scholarship 2026 has been established to attract high-performing students to study at the University of Newcastle. This scholarship acknowledges applicants with a strong academic background and provides an ongoing incenti', '20% of gross annual international tuition fee', 'https://www.newcastle.edu.au/scholarships/UNI_053', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 4, 'Ma and Morley Scholarships', 'The Ma & Morley Scholarship Program is a transformative experience offered to students of the University of Newcastle who want to change the world. This revolutionary scholarship program was born to honour the life changing and enduring friendship be', 'Up to AUD $75000 — Up to $75,000', 'http://www.newcastle.edu.au/scholarships/ma-and-morley-scholarship-program', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 4, 'Natural History Illustration Scholarship', 'This is a donor funded scholarship established from a bequest from the late Margaret Senior to recognize excellence in an Illustration major for a University of Newcastle student. The scholarship will be awarded in March to the student who completed ', 'Up to AUD $10000 — This scholarship provides a total benefit of $10,000 for one year. Payment will be made in instalments of $5000 in Semester 1 and 2', 'http://www.newcastle.edu.au/scholarships/EXT_099', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 144, 'Australia Awards Scholarship', 'Swinburne has been involved in the Australia Awards scholarship program for over 15 years. Currently, there are more than 30 Australia Award students enrolled at the university. The Australia Awards are scholarships funded by the Australian Governmen', 'Australia Awards scholarships are comprehensive and include a number of different benefits and entitlements.\r\n\r\nA full list of entitlements can be found at the Australia Awards website or Australia Awards Scholarship Policy Handbook.\r\n\r\nKey entitleme', 'https://www.swinburne.edu.au/study/options/scholarships/338/australia-awards-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 144, 'International Aviation Women\'s Association Scholarship', 'The International Aviation Womens Association (IAWA) is a non-profit association with members in 38 countries, representing 257 major companies and aviation authorities. IAWA is dedicated to promoting the advancement of women in the aviation and aero', 'The scholarship is valued at US$5,000 and a free scholar membership for one year only.', 'https://www.swinburne.edu.au/study/options/scholarships/385/international-aviation-womens-association--iawa--scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 144, 'Judith Kinnear Student Travel Scholarship 2027', 'The Judith Kinnear Student Travel Scholarship supports a postgraduate student in a Masters degree (by Research) or Doctorate degree (PhD) within Swinburne\'s School of Engineering or School of Science, Computing and Emerging Technologies. Named after ', 'Up to AUD $5000', 'https://www.swinburne.edu.au/courses/scholarships/judith-kinnear-student-travel-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 144, 'Pio and Marisa Iovenitti Memorial Engineering Excellence Scholarship 2027', 'The Pio and Marisa Iovenitti Memorial Scholarship honours Associate Professor Pio Iovenitti\'s contribution to Swinburne for over 30 years and his wife Marisa’s support. Pio was a respected leader, mentor and scholar within the School of Engineering, ', 'Up to AUD $10000', 'https://www.swinburne.edu.au/courses/scholarships/pio-and-marisa-iovenitti-memorial-engineering-excellence-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 144, 'Research Training Program Stipend - RTP Stipend', 'Research Training Program (RTP) Stipend scholarships are awarded to candidates of exceptional research potential, enrolled in a Higher Degree by Research (HDR) course of study, to assist with general living costs. These scholarships are available to ', 'Up to AUD $35499', 'https://www.swinburne.edu.au/study/options/scholarships/214/research-training-program-stipend---rtps/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 144, 'Stanley Liebich Memorial Scholarship 2027', 'The Stanley Liebich Memorial Scholarship was first established in December 1940, in memory of the late Stanley Ormond Crossley Liebich. This scholarship supports a student from a disadvantaged background enrolled in the Bachelor of Engineering (Honou', 'Up to AUD $7500', 'https://www.swinburne.edu.au/courses/scholarships/stanley-liebich-memorial-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 144, 'Steve Ashton Scholarship for the Architectural Profession (SASAP) 2026', 'The Steve Ashton Scholarship for the Architectural Profession (SASAP) honours Steve Ashton, co-founder of Ashton Raggatt McDougall (ARM Architecture). As a career architect, Steve undertook a Graduate Diploma of Business Administration at Swinburne t', 'Up to AUD $30000 — The scholarship is worth up to $30,000 per annum for full-time enrolled recipients for the standard full-time duration of the program, and up to $15,000 per annum for part-time enrolled recipients for the standard part-time. Paymen', 'https://www.swinburne.edu.au/study/options/scholarships/519/steve-ashton-scholarship-for-the-architectural-profession--sasap--2025/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 144, 'Swinburne Research Stipend Scholarships', 'Swinburne Research Stipend (SRS) scholarships are awarded to candidates of exceptional research potential undertaking doctoral studies.  The awards are provided to assist with general living costs.   Successful scholarship applicants are automaticall', 'Up to AUD $35000', 'https://www.swinburne.edu.au/study/options/scholarships/510/swinburne-research-scholarships/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 144, 'Swinburne University Postgraduate Research Award', 'SUPRAs are awarded to students of exceptional research potential undertaking doctoral studies. The awards are provided to assist with general living costs. Tuition fees are also covered by the award. SUPRA scholarships are available to both future an', 'Up to AUD $35500', 'https://www.swinburne.edu.au/study/options/scholarships/221/swinburne-university-postgraduate-research-award/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
