INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 5, 'AI Enabled Geothermal Utilisation for Sustainable Buildings', 'Supporting a PhD candidate as part of the REACH Trailblazer Program to initiate and conduct research in AI-enhanced optimisation of geothermal building systems.', 'AUD $45550/year — a stipend of $45,550 per annum tax exempt (2025 rate); a relocation allowance of $500–1,500 (for single to family) for students moving from interstate; contribution to research purposes including travel of $1,500 per annum for three', 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/phd-scholarship-ai-enabled-geothermal-systems-in-buildings', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
