INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 5, 'Deakin-Bayreuth Cotutelle - Product design engineering for sports', 'Supporting a PhD candidate to advance research in personalised product design and engineering for sports in Australia (Deakin University) and Germany (University of Bayreuth).', 'AUD $37450/year — a stipend of $37,450 per annum tax exempt (2026 rate); at least 12 months of the total period of the program at University of Bayreuth.', 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-bayreuth-cotutelle-product-design-engineering-for-sports', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
