INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 5, 'Deakin-Coventry Cotutelle: Health risks from microplastic exposure', 'Supporting a PhD candidate to research health risks related to microplastics between Australia (Deakin University) and the United Kingdom (Coventry University). Deakin is the lead institution.', 'AUD $37450/year — a stipend of $37,450 per annum tax exempt (2026 rate); a relocation allowance of $500–1,500 (for single to family) for students moving from interstate.; at least 12 months of the total period of the program at Coventry University.; ', 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/coventry-deakin-cotutelle-health-risks-from-microplastic-exposure', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
