INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 5, 'Moderate Islam in Indonesian foreign policy', 'Supporting a PhD candidate to analyse Indonesia’s “moderate Islam,” its global standing, and impacts of one-way Islamic knowledge flows.', 'AUD $37450/year — a stipend of $37,450 per annum tax exempt (2026 rate)', 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/phd-scholarship-moderate-islam-in-indonesian-foreign-policy', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 5, 'Modernising Australian building water services', 'Supporting a PhD candidate investigating sustainable water service design for Australian healthcare buildings.', 'AUD $37450/year — a stipend of $37,450 per annum tax exempt (2026 rate); a fixed top-up of $10,000 per annum tax exempt; a relocation allowance of $500–1,500 (for single to family) for students moving from interstate', 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/hdr-scholarship-modernising-australian-building-water-services', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 5, 'Purification of silk proteins for next generation protein-based materials', 'Supporting a PhD candidate to develop a new method to purify silk proteins using liquid chromatography.', 'AUD $37450/year', 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/phd-scholarship-next-generation-protein-based-materials', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 5, 'Research Training Program    Scholarship (RTP)  / Deakin University Postgraduate Research  Scholarship (DUPR)', 'RTP scholarships are funded by the Australian Government, while DUPR scholarships are funded by Deakin. Both are available to domestic and international candidates. Only top-ranked applicants will be offered an RTP.', 'See scholarship details', 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/rtp-and-duprs', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 5, 'Upscaling seagrass restoration in Victoria', 'Supporting two PhD candidates as part of the REACH Trailblazer Program to initiate and conduct research in upscaling seagrass restoration in Victoria to support the national emissions target.', 'AUD $45550/year — a stipend of $45,550 per annum tax exempt (2025 rate); a relocation allowance of $500–1,500 (for single to family) for students moving from interstate; contribution to research purposes including travel of $1,500 per annum for three', 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/hdr-scholarship-upscaling-seagrass-restoration-in-victoria', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 5, 'Vietnam Scholarship', 'Contact Deakin Universisty for more information', '20% of the student contributions (tuition fees)', 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/vietnam-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 5, 'Warrnambool Campus International Bursary', 'Contact Deakin University for more information', '20% of the student contributions (tuition fees)', 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/warrnambool-campus-international-bursary', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 5, 'Youth futures after mobility', 'Supporting a PhD candidate to undertake a research project as part of a new Australian Research Council funded Discovery Project: Youth Futures after Mobility (YFAM).', 'AUD $37450/year — stipend of $37,450 per annum tax exempt (2026 rate); stipend of $37,450 per annum tax exempt (2026 rate)', 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/phd-scholarship-youth-futures', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 145, 'Alumni scholarships', 'The Flinders University Alumni Scholarship rewards eligible international graduates of the Universitys undergraduate and postgraduate programs with a 20% full duration scholarship to study another undergraduate or postgraduate degree at Flinders.', '20% full duration scholarship to study another undergraduate or postgraduate degree at Flinders', 'https://www.flinders.edu.au/international/apply/scholarships/alumni', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 145, 'LATAM English Excellence Scholarship  English for Academic Purposes (EAP)', '-', '30% reduction in tuition fees.; Scholarship value is the percentage reduction specified above.', 'https://www.flinders.edu.au/content/dam/documents/study/international/flinders-university-academy/english-studies-express-scholarship-terms-and-conditions-2026.pdf', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'Early Bird Acceptance Grant - International Students', 'International students applying for an undergraduate or postgraduate course to study at La Trobe University can be rewarded a bonus grant for completing their admission process early. Recipients will automatically be eligible to receive an Early Bird', 'Up to AUD $2000 — 5% of the First year Tuition fees', 'https://www.latrobe.edu.au/study/scholarships/other/early-bird-acceptance-grant-international-students', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'Graduate Research PhD Project Scholarships', 'La Trobe University is offering a number of graduate research scholarship packages consisting of a generous stipend, tuition fee scholarship, and allowances to support outstanding graduate researchers applying for a PhD project. Apply now to join our', 'AUD $36000/year', 'https://www.latrobe.edu.au/study/scholarships/other/graduate-research-phd-project-scholarships2', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'La Trobe Analytics and Insights Scholarship - 30%', 'Data is shaping our future, as industries everywhere rely on expert data analysts to make smarter decisions. With a degree in analytics, you\'ll learn to approach complex problems, spot trends, and turn numbers into meaningful insights. From business ', '30% reduction in course fees', 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-analytics-and-insights-scholarship-30', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'La Trobe Analytics and Insights Scholarship - 50% and 100%', 'Data is shaping our future, as industries everywhere rely on expert data analysts to make smarter decisions. With a degree in analytics, you\'ll learn to approach complex problems, spot trends, and turn numbers into meaningful insights. From business ', 'A reduction of 50 or 100% off the total course tuition fee', 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-analytics-and-insights-scholarship-50-and-100', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'La Trobe Artificial Intelligence Scholarship - 30%', 'La Trobe University has a bold ambition to transform research, education, and student experience by applying an \'AI-first\' approach, supported by a new partnership with Microsoft Australia and New Zealand and leading cyber security provider CyberCX. ', 'See scholarship details', 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-artificial-intelligence-scholarship-30', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'La Trobe Artificial Intelligence Scholarship - 50% and 100%', 'La Trobe University has a bold ambition to transform research, education, and student support by applying an \'AI-first\' approach, supported by a new partnership with Microsoft Australia and New Zealand and leading cyber security provider CyberCX. Art', 'A reduction of either 50% or 100% off the total course tuition fee.', 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-artificial-intelligence-scholarship-50-and-100', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'La Trobe Flexible Research Scholarship (Flex) - Candidates With Disabilities', 'In order to maximize opportunities for students with disabilities to study higher degrees by research, La Trobe University is offering the Flexible Research Scholarship to eligible applicants with disabilities, who already hold a Research Training Pr', 'Up to AUD $36000 — Up to 18 month extension to RTP or LTGRS stipend for doctoral candidates and up to 8 month extension for research masters candidates', 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-flexible-research-scholarship-flex-candidates-with-disabilities', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'La Trobe Health Innovation Scholarship - 30%', 'Join a university that\'s in the top 150 Worldwide for Public Health. La Trobe leads in future-focused healthcare with our digital health courses. Students can gain valuable expertise in specialisms such as Big Data analytics, virtual healthcare, Inte', '30% reduction in course fees', 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-health-innovation-scholarship-30', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'La Trobe High Achiever Scholarship', 'La Trobe University values academic excellence. High-achieving international students considering applying for an undergraduate or postgraduate course will be automatically considered for this scholarship. The La Trobe High Achiever Scholarship rewar', 'Up to 25% reduction in course fees', 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-high-achiever-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'La Trobe Humanitarian Scholarship', 'La Trobe University recognises the important contribution that people from refugee and asylum seeker backgrounds make to the Australian community.', '100% of tuition fees and $5000 per annum cost-of-living scholarship.', 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-humanitarian-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'La Trobe Vice Chancellor Scholarship', 'At La Trobe, we recognize and support future leaders who are driven to make a difference. The Vice Chancellor Scholarship is our most prestigious scholarship, awarded to individuals who have excelled not only in their studies but also in extracurricu', 'A reduction of either 50% or 100% off the total course tuition fee.', 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-vice-chancellor-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'Placement Travel Bursary', 'The Office of the Provost is offering support to help students undertaking placement with the costs involved in travelling long distances and finding suitable accommodation.', 'Up to AUD $1365', 'https://www.latrobe.edu.au/study/scholarships/other/placement-travel-bursary', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 146, 'Wominjeka - Study Abroad Scholarship', 'Embark on a transformative journey with La Trobe University\'s Study Abroad Scholarship. Wominjeka - meaning "Welcome" and "Come With Purpose" in Woiwurrung, the language of the Wurundjeri people - reflects the spirit of La Trobe and the values we uph', 'A reduction of 25% off the total course tuition fee', 'https://www.latrobe.edu.au/study/scholarships/other/wominjeka-study-abroad-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'A G Whitlam International Undergraduate Merit Scholarship', 'The A G Whitlam International Undergraduate Merit Scholarship is offered to talented international students who are enrolling in the Bachelor of Commerce.', 'Up to 50% fee remission for the duration of the Bachelor of Commerce (up to 300 points).', 'http://scholarships.unimelb.edu.au/awards/ag-whitlam-international-undergraduate-merit-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Ann and Peter Law Scholarship for Cello', 'The Ann and Peter Law Scholarship for Cello is offered to students enrolled in a Bachelor of Music specialising in Cello who are experiencing financial need.', 'Up to AUD $7600', 'https://scholarships.unimelb.edu.au/awards/ann-and-peter-law-scholarship-for-cello', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Australian Government Research Training Program Scholarships (RTP)', 'The Research Training Program Scholarship is supported by the Australian Commonwealth Government and the University of Melbourne, and offered to high-achieving domestic and international research students.', 'See scholarship details', 'https://scholarships.unimelb.edu.au/awards/research-training-program-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Australian Industrial Relations Commission (AIRC) Centennial Prize', 'The Australian Industrial Relations Commission Centennial Prize was established in 2006 and is offered to students with the best essay or thesis in the field of Industrial Relations or Labour History.', 'Up to AUD $1000 — At least $1000.', 'https://scholarships.unimelb.edu.au/awards/airc-centennial-prize', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Bachelor of Commerce Global Scholarship', 'The Commerce Global Scholarships is offered to high-achieving students from countries deemed to be under-represented in the Bachelor of Commerce.', 'The scholarship provides 20% fee sponsorship for the duration of the course (300 credit points).', 'https://scholarships.unimelb.edu.au/awards/bachelor-of-commerce-global-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Brian Entwisle Scholarship', 'The Brian Entwisle Scholarship was established with a gift from Brian Roger Entwisle and is awarded to students who are enrolled in the Doctor of Medicine and are experiencing disadvantaged circumstances. Preference is given to students who have a di', 'Up to AUD $48000', 'https://scholarships.unimelb.edu.au/awards/brian-entwisle-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'C S Soper and Joan Rydon Scholarship', 'The C. S. Soper and Joan Rydon Scholarship was established in memory of Emeritus Professor Charles Samuel Soper, and is offered to talented Honours students studying Economics who are specialising in economic theory or mathematical economics.', 'Up to AUD $7500 — This scholarship provides a one-off payment of approximately $7500 (depending on the available income from the gift).', 'http://scholarships.unimelb.edu.au/awards/cs-soper-and-joan-rydon-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Califole Melbourne Medical School Scholarship', 'The Califole Melbourne Medical School Scholarship is offer to students who are enrolled in the Doctor of Medicine, have completed their secondary schooling in a state or territory government school, and are experiencing financial disadvantage. Prefer', 'Up to AUD $60000', 'https://scholarships.unimelb.edu.au/awards/califole-melbourne-medical-school-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Cassidy Scholarship', 'The Cassidy Scholarship is offered to talented undergraduate or graduate students studying Music, Theatre, Production or Music Theatre.', 'Up to AUD $6000', 'https://scholarships.unimelb.edu.au/awards/cassidy-bequest-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Cbus Super Mavis Robertson Scholarship', 'The Cbus Super Mavis Robertson Scholarship is offered to Bachelor of Commerce students who are experiencing disadvantaged circumstances. Preference is given to female students.', 'Up to AUD $26000', 'https://scholarships.unimelb.edu.au/awards/cbus-super-mavis-robertson', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
