INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'David Ashton Scholarship', 'The David Ashton Scholarship is supported by the Melbourne Botany Foundation and is offered to high-achieving graduate researchers who are enrolled in the Doctor of Philosophy in the Faculty of Science and undertaking research in the field of Botany.', 'Up to AUD $6000', 'https://scholarships.unimelb.edu.au/awards/david-ashton-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'David Ashton Travel Award', 'The David Ashton Travel Award was established with a gift from David Hungerford Ashton to the University of Melbourne Botany Foundation and is awarded to students who are enrolled in the Bachelor of Science (Degree with Honours) or a graduate coursew', 'Up to AUD $2500', 'https://scholarships.unimelb.edu.au/awards/david-ashton-travel-award', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
