INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Melbourne Chancellor\'s Scholarship', 'This scholarship is offered to high-achieving students in recognition of their outstanding academic achievement during their Australian Year 12 or International Baccalaureate (IB) undertaken in Australia.', 'Up to AUD $32500 — International students: A 50% tuition fee remission for the standard full-time duration of a Bachelor degree course. Melbourne Global Scholars Award of up to $2,500 for an approved period of overseas study as an Exchange or Study A', 'https://scholarships.unimelb.edu.au/awards/melbourne-chancellors-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
