INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Melbourne Research Scholarship', 'This scholarship is offered to high-achieving domestic and international students who are enrolling in a graduate research degree.', '100% fee remission and up to $135,000', 'https://scholarships.unimelb.edu.au/awards/melbourne-research-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
