INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Stawell Scholarship', 'The Stawell Scholarship has been established to support Graduate Researchers within the field of Engineering in the Faculty of Engineering and Information Technology with a project of a proposal that will enhance their research outcomes.', 'Up to AUD $6600', 'https://scholarships.unimelb.edu.au/awards/stawell-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Suzanne and Geoffrey Dawson Scholarship', 'The scholarship is awarded to a high-achieving student enrolled in the Professional Learning Capstone as part of a Master of Teaching, and pursuing research in the field of education, the outcome of which is likely to enhance the advancement of socia', 'Up to AUD $6000', 'https://scholarships.unimelb.edu.au/awards/suzanne-and-geoffrey-dawson-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
