INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'Wilfred Prest Travelling Fellowship', 'The Wilfred Prest Travelling Fellowship is open to students or graduates of the Faculty of Business and Economics who will undertake postgraduate studies in the field of Economics at an overseas university or research institution.', 'Up to AUD $16000 — Each fellowship is paid in two equal instalments: the first upon acceptance of the scholarship and evidence of full-time enrolment at the overseas university or research institution, and the second upon evidence of continued full-t', 'https://scholarships.unimelb.edu.au/awards/wilfred-prest-travelling-fellowship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 147, 'William Bardsley Award', 'The William Bardsley Award is offered to students who are enrolled in the Bachelor of Music or Master of Music specialising in violin performance and are experiencing financial need.', 'Up to AUD $800', 'https://scholarships.unimelb.edu.au/awards/w-bardsley-award', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 6, 'Australia Awards Scholarships', 'Australia Awards Scholarships are long-term awards administered by the Australian Department of Foreign Affairs and Trade that aim to contribute to the development needs of Australia\'s partner countries in line with bilateral and regional agreements.', 'See scholarship details', 'https://www.jcu.edu.au/international-students/scholarships-and-financial-aid/australia-awards-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 6, 'International Excellence Scholarship', 'The JCU International Excellence Scholarship provides a 25% tuition fee reduction throughout the entire duration of approved full degree study programs, provided recipients maintain a strong GPA each semester.\r\n\r\nScholarship eligibility is automatica', '25% off tuition fee', 'https://www.jcu.edu.au/scholarships/search/international-excellence-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 6, 'Robert Logan Memorial Grant', 'Established in 1975 from a bequest from the estate of the late Dr Robert Logan, Senior Lecturer in Biochemistry at the University from 1968 to 1973, the income derived from the bequest maintains the awards.', 'AUD $14000/year — The value of the travelling and research grant will be determined by the Selection Committee (up to $14,000 annually). The grant will provide assistance to honours and post-graduate students in The Academy conducting research in the', 'https://www.jcu.edu.au/scholarships/search/robert-logan-memorial-grant', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 6, 'Tom and Dorothy Cook Scholarships in Public Health and Tropical Medicine', 'The original Cook family migrated from England to Australia in 1837. 75 years later Tom\'s father purchased land in Mackay and in 1915 built a family home, which is currently known as Greenmount Homestead. In 1950 Tom Cook wed Dorothy Drysdale, a succ', 'Up to AUD $117250', 'https://www.jcu.edu.au/scholarships/search/tom-and-dorothy-cook-scholarships-in-tropical-health', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
