INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'College of Design and Social Context Student Bursary', 'This bursary provides financial assistance to international students studying in the College of Design and Social Context (DSC).', 'Up to AUD $5000 — The total value of the bursary is a AU$5,000, one-off payment towards future tuition fees to be paid after the first census date into student\'s university account.', 'https://www.rmit.edu.au/scholarships/international-scholarships/college-of-design-and-social-context-student-bursary#overview', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'English to Foundation Studies/Fast Track Pathway Bursary', 'If you plan to study an English language pathway to either an RMIT Foundation Studies or Fast Track program in 2027, you may qualify for our English to Foundation Studies/Fast Track Pathway Bursary.', '10% of the tuition fee for Academic English.', 'https://www.rmit.edu.au/scholarships/international-scholarships/english-pathway-bursary#overview', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'External Scholarships (Sponsorship)', 'RMIT welcomes students who have scholarship funded by their home government (sponsored students). RMIT currently has over 800 sponsored students. They are enrolled in a wide range programs in all study levels. Prospective sponsored students need to m', 'See scholarship details', 'https://www.rmit.edu.au/scholarships/international-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'FUNED - RMIT Scholarship', 'If you are an international student from Mexico applying for a Masters by Coursework program at RMIT University, you may be eligible for this jointly funded scholarship by RMIT and the Mexican Foundation for Education, Technology and Science (FUNED).', 'Up to AUD $12000 — RMIT UP Academic English Bursary for Latin American students if you are required to study ELICOS; tuition fee support by RMIT to the value of 25% of the tuition fees for Masters by Coursework program for a maximum of two years.', 'https://www.rmit.edu.au/scholarships/international-scholarships/funed-rmit-scholarship#overview', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'Fast Track University Pathway Academic Scholarship', 'This scholarship provides financial assistance to high achieving Fast Track University Pathway international students.', 'Up to AUD $5000 — The total value of the scholarship is a AU$5,000, one-off payment towards future tuition fees to be paid after the first census date into student\'s university account.', 'https://www.rmit.edu.au/scholarships/international-scholarships/fast-track-university-pathway-academic-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'Foundation Academic Scholarships', 'This scholarship provides financial assistance to high achieving Foundation Studies international students.', 'Up to AUD $5000 — The total value of the scholarship is AU$5,000, one-off payment towards future tuition fee to be paid after the first census date into student\'s university account.', 'https://www.rmit.edu.au/scholarships/international-scholarships/foundation-academic-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'Future Leaders Scholarship', 'Provides students from India and the subcontinent with a 20% tuition fee reduction for eligible Bachelor and Masters programs that have received an offer from 2026.', 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible program(s)* as outlined in your offer letter.', 'https://www.rmit.edu.au/scholarships/international-scholarships/future-leaders-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'Gavin Teague Memorial Scholarship', 'For students enrolled in the Bachelor of Fine Arts program who can demonstrate artistic merit and circumstances which impact their study worth up to $1,300.', 'Up to AUD $1300', 'https://www.rmit.edu.au/scholarships/coursework/gavin-teague', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'Medibank Excellence Scholarship', 'The Medibank Excellence Scholarship is available to international students studying Australian Year 12 or International Baccalaureate in Australia. In addition to receiving AU$12,000 successful applicants will have the opportunity to attend Medibank ', 'Up to AUD $12000 — The total value of the scholarship is AU$12,000, to be paid to recipient\'s Australian bank account in AU$6,000 installments after the census date of each semester of the first year.', 'https://www.rmit.edu.au/scholarships/international-scholarships/medibank-excellence-scholarship#overview', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'Medibank High Achiever International Scholarship', 'This scholarship, valued at AU$20,000, is available to international students studying Australian Year 12 or International Baccalaureate in Australia.', 'Up to AUD $20000 — The total value of the scholarship is AU$20,000, to be paid to recipient\'s Australian bank account in AU$10,000 installments after the census date of each semester of the first year.', 'https://www.rmit.edu.au/scholarships/international-scholarships/medibank-high-achiever-international-scholarship#overview', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'Pathway Scholarship for China', 'This scholarship supports students from China to study a Bachelor program at RMIT University in Melbourne, Australia.', 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible Bachelor program(s) as outlined in your offer letter.', 'https://www.rmit.edu.au/scholarships/international-scholarships/pathway-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT David Phillips Memorial Scholarship', 'For students enrolled full-time in the ELICOS English for Academic Purposes (EAP) Program who can demonstrate hardship; worth $5,000.', 'Up to AUD $5000 — This scholarship provides $5,000 as a one-off payment. A short student report must be completed before payment is made to the successful recipient.', 'https://www.rmit.edu.au/scholarships/coursework/david-phillips', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT English Language Bursary for Latin American Students', 'For 2025 and 2026 commencement: 35% of the total program fee for an ELICOS program (you pay $355 per week after the discount)', '35% of the total program fee for an ELICOS program (you pay $338 per week after the discount)', 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-english-bursary-for-latin-american-students', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT John Bush Memorial Scholarship', 'For Thailand born students studying full-time in an undergraduate or postgraduate by coursework program who can demonstrate circumstances which impact their study; worth up to $10,000.', 'Up to AUD $30000 — This scholarship provides up to $10,000 for one year ($5,000 per semester).', 'https://www.rmit.edu.au/scholarships/coursework/bush', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT MAI Foundation Scholarship', 'For commencing first-year students who are passionate about business, law or construction/project development, and who can demonstrate circumstances which impact their study; worth up to $50,000.', 'Up to AUD $50000 — The scholarship provides $10,000 per year for the standard duration of program.', 'https://www.rmit.edu.au/scholarships/coursework/mai-foundation', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT UP Academic English Bursary for Asia', 'If you are a citizen of Cambodia, Japan, Laos, South Korea, Taiwan, Thailand or Vietnam this bursary provides a tuition fee discount on your Academic English course.', '10% of the total program fee in 2026 study period for an Academic English course (you pay $491 per week after the discount); 20% of the total program fee in 2027 study period for an Academic English course (you pay $452 per week after the discount)', 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-english-bursary-for-asia#overview', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT UP Academic English Bursary for Latin America, Spain and Türkiye', 'If you are a citizen of a Latin American country, Spain or Türkiye this bursary provides a tuition fee discount on your Academic English course.', '35% of the total program fee for an Academic English course (you pay $355 per week after the discount); 40% of the total program fee for an Academic English course (you pay $339 per week after the discount)', 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-english-bursary-for-latin-american-students#overview', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT UP General English Bursary for Asia', 'If you are a citizen of Japan, South Korea, Taiwan or Thailand this bursary provides a tuition fee discount on your General English language course.', 'For 2026 commencement: 20% of the total fee in 2026 study period for the General English course., You pay $436 per week after the discount. For 2027 commencement: 20% of the total fee in 2027 study period for the General English course., You pay $452', 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-general-english-bursary-for-asia', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT UP General English Bursary for Latin America, Europe and Türkiye', 'If you are a citizen of a Latin American country, the European Union (EU) or Türkiye, this bursary provides a tuition fee discount on your General English language course.', '40% of the total course fee', 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-general-english-bursary-latin-america-eu-turkey#overview', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT UP IELTS Preparation Bursary for Asia', 'If you are a citizen of Japan, South Korea, Taiwan or Thailand this bursary provides a tuition fee discount on your IELTS Preparation course.', '20% of the total course fee', 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-ielts-preparation-bursary-for-asia', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT UP IELTS Preparation Bursary for Latin America, Europe and Türkiye', 'If you are a citizen of a Latin American country, the European Union (EU) or Türkiye, this bursary provides a tuition fee discount on your IELTS Preparation course.', '40% of the total course fee', 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-ielts-preparation-bursary-latin-america-eu-turkey', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT University Top-up Scholarship for Vietnam Government (Project 89)', 'This top-up scholarship program is available to talented Vietnamese students aims to address Vietnam\'s future industry and workforce needs, prioritising key research areas such as digital technologies, physics, biotechnologies and energy & environmen', 'a tuition fee scholarship of up to $25,000 USD; a stipend scholarship of $1,120 USD per month; an international return airfare and travel allowances; Overseas Student Health Cover (OSHC) for the time spent in Australia (up to $1,000 USD per year).', 'https://www.rmit.edu.au/scholarships/international-scholarships/vietnam-government-project-89-rmit-scholarship#overview', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'RMIT Vietnam Alumni Postgraduate Scholarship', 'This scholarship is awarded to RMIT Vietnam alumni who will commence Master by Coursework program at RMIT Australia.', '10% tuition fee reduction for the program duration outlined on your offer letter.', 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-vietnam-alumni-postgraduate-scholarship#overview', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'Sallie Mae private student loans', 'Sallie Mae Student Loans can be used for tuition fees and material fees associated with your course.', 'The loan amount you can apply for is capped by the ‘cost of attendance’, which is calculated by RMIT. The cost of attendance includes tuition fees and living expenses for an academic year. The loan amount is distributed in two equal payments, paid ou', 'https://www.rmit.edu.au/scholarships/international-scholarships/us-financial-aid', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'School of Art Honours Travelling Grant', 'For art honours students who can demonstrate outstanding academic achievement; worth up to $4,000.', 'Up to AUD $4000', 'https://www.rmit.edu.au/scholarships/coursework/school-art-travel', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'School of Education Academic Merit Scholarship for China', 'This scholarship supports outstanding students from China to pursue their academic goals in education or teaching discipline at RMIT University in Melbourne, Australia.', 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible program(s) as outlined in your offer letter.', 'https://www.rmit.edu.au/scholarships/international-scholarships/school-of-education-academic-merit-scholarship#overview', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 149, 'Vice-Chancellor PhD Scholarship', 'Scholarships are awarded on the basis of academic excellence and research potential to local and international candidates undertaking a research doctoral degree.', 'a stipend of $47,821 per annum pro rata (full-time study) which represents a generous RMIT top-up of approximately $12,000 above the RTP rate; a research support allowance of $5,000 per annum to support research activities; International candidates i', 'https://www.rmit.edu.au/scholarships/research/vcps', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 9, '2026 VU Sydney & Brisbane Global Diversity Scholarship', 'The 2026 VU Sydney and VU Brisbane Diversity Scholarship provides an additional 10% tuition fee reduction for students enrolling in our undergraduate, postgraduate, and higher education diploma programs in IT and Business. This 10% reduction is offer', '10% reduction of the course tuition fee the duration of the course. (Applied in addition to the 22.5% VU Sydney and Brisbane 2026 International Scholarship)', 'https://www.vu.edu.au/vu-sydney/study-at-vu-sydney/vu-sydney-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 9, 'Australia Awards Scholarships', 'Australia Awards scholarships are long-term development awards, offered by the Australian Government and administered by the Department of Foreign Affairs and Trade (DFAT). They aim to contribute to the long-term development needs of Australia\'s part', 'Tuition fees, living allowance, Overseas Student Health Cover and academic support.', 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 9, 'Early Childhood Education International Scholarship (2025)', 'The 2025 Early Childhood Education International Scholarship supports new international students who plan to commence an Early Childhood Education course in 2025. \r\n\r\nDo not miss this incredible opportunity to get a world-class qualification from a g', '-Graduate Diploma in Early Childhood Education (EGEC): 20% tuition fee reduction for the entire standard duration of eligible courses (calculated from the date of commencement to the course end date in the letter of offer). – Only applicable for Febr', 'https://www.vu.edu.au/vu-sydney/study-at-vu-sydney/vu-sydney-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 9, 'STEM Accommodation Scholarship', 'Enjoy a stress-free start to your studies and save up to $15,500 with the unique STEM Accommodation Scholarship at Victoria University (VU).  Our exciting merit-based scholarship offers eligible international students free accommodation at UniLodge V', 'Successful undergraduate applicants will receive one year (52 weeks) of free accommodation at UniLodge VU, valued at $15,548. / Successful postgraduate applicants will receive six months (26 weeks) of free accommodation at UniLodge VU, valued at $8,5', 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 9, 'VU Block Model International Scholarship', 'At Victoria University (VU), were committed to supporting your success. Our unique VU Block Model® International Scholarship offers all eligible international students up to 30% off tuition fees for the entire first year. Study well and youll have th', 'Up to 30% off your first year tuition fees – based on merit. Study well and youll have the chance to keep or increase the scholarship for the full duration of your course.', 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships/vu-block-model-international-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 9, 'VU Global Research Scholarship', 'At Victoria University (VU), we’re committed to empowering the next generation of research leaders. Our exciting new VU Global Research Scholarship offers eligible international students 20% off tuition fees for the entire duration of a masters by re', 'The VU Global Research Scholarship is valued at 20% off tuition fees for the entire duration of your masters by research degree at Victoria University.', 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 9, 'VU Sydney & Brisbane 2026 International Scholarship', 'The VU Sydney & Brisbane 2026 International Scholarship provides students with up to a 22.5% reduction in tuition fees. Students commencing our undergraduate, postgraduate and higher education diploma programs are eligible for this scholarship. The S', '22.5% off the course tuition fees for the full course duration.', 'https://www.vu.edu.au/vu-sydney/study-at-vu-sydney/vu-sydney-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 150, 'Alumni 10% Fee Tuition Discount', 'Ready to return to Murdoch to achieve your postgraduate degree? As an alumnus you\'re an important part of our community, so to help support your study goals we\'re offering a 10% reduction in postgraduate fees on eligible courses.', '10% tuition fee deduction', 'https://www.murdoch.edu.au/study/scholarship/alumni-10-fee-tuition-discount', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 150, 'Alumni 25% Fee Tuition Discount', 'Have you recently joined our alumni community and are ready to start postgraduate study? To help support your goals, we’re offering a 25% reduction in postgraduate fees if you’ve finished your undergraduate or Masters level degree in the past 12 mont', '25% tuition fee deduction', 'https://www.murdoch.edu.au/study/scholarship/alumni-25-fee-tuition-discount', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 150, 'International Futures Scholarship - 2026', 'Murdoch is offering a 25% fee reduction scholarship for International students enrolled in eligible courses commencing in 2026.', '25% tuition fee reduction', 'https://www.murdoch.edu.au/study/scholarship/international-futures-scholarship---2026', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
