INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 10, 'Kent Higher Education Bursary for International Students', 'A limited offering for international students who are enrolling into Kent’s higher education Bachelor degree courses. Students must have applied through authorised Kent Agents at both the Sydney and Melbourne campuses.', 'Up to AUD $300 — The bursary awards applicants with a $300 per unit reduction in tuition fees for the first 24 units enrolled.', 'https://kent.edu.au/scholarships/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 10, 'Kent International Student Scholarship', 'A scholarship for international students who are commencing a full-time undergraduate Higher Education course. Students must have achieved sound academic standing and results in their previous studies.', 'The scholarship is a 30% reduction in tuition fees for the duration of their course. Each scholarship application is assessed on a case-by-case basis with final selection by the Chief Executive Officer.', 'https://kent.edu.au/scholarships/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
