INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'A smart CPR feedback device for cardiac arrest (PhD scholarship)', 'This PhD project focuses on developing the first-ever closed-loop cardiopulmonary resuscitation (CPR) feedback device. The device uses non-invasive sensors to measure blood oxygenation in the brain and tells the CPR provider how to adjust their compr', 'AUD $33637/year', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/a-smart-cpr-feedback-device-for-cardiac-arrest-phd-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Alex Muir Learning Potential Fund Scholarship', 'The Alex Muir Learning Potential Fund scholarship was established by Dr Christopher and Mrs Dymphna Muir in loving memory of their son Alex. The scholarship is awarded to disadvantaged students studying engineering to assist them to reach their poten', 'Up to AUD $5000 — a scholarship of $5,000 for one year, paid in two instalments of $2,500.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/alex-muir-learning-potential-fund-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Australia Awards Scholarship', 'As an Australia Awards student you need to attend a five-week Introductory Academic Program (IAP). It’s a chance for you to get help with enrolment, learning skills, language expectations and our technology and teaching systems. You will receive prog', 'See scholarship details', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/australia-awards-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Australian South Sea Islander Community Foundation Scholarship', 'The Australian South Sea Islander Community Foundation was established by the Queensland Government in 2001 as a perpetual fund to provide scholarships to Australian South Sea Islander undergraduate students.', 'You will receive an Australian South Sea Islander Community Foundation Scholarship. The value and number of scholarships will vary annually depending on funding. These scholarships are subject to annual funding.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/australian-south-sea-islander-community-foundation-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'BDO Learning Potential Fund Scholarship', 'The Learning Potential Fund provides support through scholarships and bursaries to students in financial need. The Brisbane office of global accounting firm BDO has become the first business organisation to partner with QUT in creating scholarships f', 'Up to AUD $5000 — a scholarship of $5,000 for one year, paid in two instalments of $2,500.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/bdo-learning-potential-fund-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Bachelor of Arts Impact Scholarship', 'The Bachelor of Arts Impact Scholarship is awarded to high-achieving school leavers and eligible gap year students starting our Bachelor of Arts degree. This scholarship is targeted at high achievers to enable their continued success at QUT through f', 'Up to AUD $15000', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/bachelor-of-arts-impact-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Brian Gray Scholarship', 'The Brian Gray Scholarship program provides up to four scholarships valued at $15,000 each to support students in finance, economics, actuarial science, econometrics, statistics or related disciplines who intend to focus full-time on their studies an', 'Up to AUD $15000 — The Brian Gray Scholarship program will fund up to four scholarships annually, to the value of $15,000 each.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/brian-gray-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'China Scholarship Council Scholarship', 'A scholarship for future research students studying in any faculty.', 'a tuition fee waiver for the duration of your course, which is normally 1.5 years for masters students and 3 years for doctoral students.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/china-scholarship-council', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Clayton Adam Florence Wilson Award for Biomechanics and Spine Research', 'The Clayton Adam Florence Wilson Award is available to promote spine research at QUT, and honours the stellar contribution to scientific innovation in spine research made by our former Research Director, Professor Clayton Adam. Clayton joined QUT in ', 'See scholarship details', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/CAFW-Award', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Data61 PhD Scholarship', 'At CSIRO\'s Data61, we aim to develop top-quality doctoral students who will prosper in careers in Australia’s data-skilled workforce. Our PhD scholarship program provides opportunities for outstanding postgraduate students with demonstrated academic ', 'a full scholarship which includes a base stipend at the Australian Government Research Training (RTP) Program base rate supplemented with a top-up scholarship of $10,000 per annum. Data61 PhD scholarships have a maximum term of 3 years and 6 months.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/data61-phd-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Dr Cherrell Hirst AO Learning Potential Fund Scholarship', 'The Dr Cherrell Hirst Learning Potential Fund Scholarship was established by Dr Cherrell Hirst as a tribute to her family. The scholarship aims to encourage disadvantaged and low-income female students to undertake an undergraduate degrees in health,', 'Up to AUD $7500', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/dr-cherrell-hirst-ao-learning-potential-fund-scholarship?international&contact-us', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Dr Laurie Cowled Learning Potential Fund Scholarship', 'The Learning Potential Fund provides support through scholarships and bursaries to students in financial need.Philanthropist Dr Laurie Cowled funds these scholarships with the intention of fostering the education of women, particularly from rural or ', 'Up to AUD $7500 — a scholarship of $7,500 for one year, paid in two instalments of $3,750.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/laurie-cowled-learning-potential-fund-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Dynamic soft matter materials PhD scholarship', 'As the successful applicant you will complete your PhD in the field of organic photochemistry for advanced reprogrammable material design.Based in our Science and Engineering Faculty, you will also spend time at our research hub at the Karlsruhe Inst', 'a minimum of $30,000 per year, for 3 yearsa QUT tuition fee sponsorship (for international students).', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/dynamic-soft-matter-materials-phd-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Equity Work Integrated Learning (WIL) Bursaries', 'If you\'re completing a work integrated learning (WIL) placement and experiencing financial hardship, you may be eligible for a bursary of up to $750.', 'Up to AUD $1000 — bursary of $300, $500, $750 or $1000 based on your demonstrated need.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/equity-work-integrated-learning-wil-bursaries', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Equity scholarships scheme', 'The QUT Equity Scholarships Scheme is an application-based scheme offered to students who experience financial difficulty. It is funded by significant contributions from the Learning Potential Fund. The scholarships and bursaries are offered to comme', 'Up to AUD $4200', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/equity-scholarships-scheme', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'International Merit Scholarship', 'A high achievement scholarship for future international undergraduate and postgraduate students.', 'a scholarship to cover 25% of your tuition fees for your first two semesters (one year) of study at QUT, provided you meet the minimum academic standards.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/international-merit-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'International Talent Scholarship', 'A new scholarship for 2026 that covers tuition fees, with eligibility based on your prior academic achievements.', 'You\'ll receive an ongoing scholarship to cover 20% of your tuition fees per semester of study at QUT', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/international-talent-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Investigation on Bubble Dynamics Under Electric Fields in Water Electrolysis Process', 'We are seeking a PhD candidate to investigate gas bubble dynamics under the influence of electric fields, with a particular focus on applications in electrochemical hydrogen production. The project will examine the physical mechanisms governing bubbl', 'AUD $37010/year', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/investigation-on-bubble-dynamics-under-electric-fields-in-water-electrolysis-process', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Kinder Collis Learning Potential Fund Scholarship', 'The Kinder Collis Learning Potential Fund Scholarship has been established by Ms Roslyn Kinder as a tribute to her partner.', 'Up to AUD $5000 — a scholarship of $5,000 for one year, paid in two instalments of $2,500.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/kinder-collis-learning-potential-fund-scholarship?international&contact-us', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Laurie and Gail Smith Learning Potential Fund Scholarship', 'The Learning Potential Fund provides support through scholarships and bursaries to students in financial need. The Laurie and Gail Smith Learning Potential Fund Scholarships were established by Laurie and Gail as a tribute to their family. These scho', 'Up to AUD $7500 — a scholarship of $7,500 for one year, paid in two instalments of $3,750.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/laurie-and-gail-smith-learning-potential-fund-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'QUT College English Language Concession', 'A tuition fee concession for commencing students from selected countries to study English for Academic Purposes or IELTS Advanced Program at QUT College.', 'A reduction of 25% from the tuition fee of your English for Academic Purposes (EAP) and IELTS Advanced programs at QUT College.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-college-english-language-concession', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'QUT College Merit Scholarship', 'This scholarship is sponsored by QUT College. It is available to international students who have demonstrated academic achievement or can demonstrate how they intend to commit to success in their future studies.', 'A scholarship to cover 25% of the tuition fees for the first semester of your Diploma or Foundation program at QUT International College. An invitation to a Pathway Scholarship ceremony, certificate of recognition, and access to extra-curricular prof', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-international-college-pathway-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'QUT Excellence Scholarship (Academic)', 'The QUT Excellence Scholarship is our premier offering for high achievers. We award more than 130 scholarships annually, worth more than $3.5 million.In addition to the financial support, the program helps you to make the most of your QUT experience ', 'Up to AUD $30000 — scholarships valued at $30,000 each for study in any discipline, scholarships valued at $30,000 each for courses in the Faculty of Science and Faculty of Engineering only.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/excellence-scholarship-academic', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'QUT Excellence Scholarship (Creative Arts)', 'The QUT Excellence Scholarship is our premier offering for high achievers. These scholarships recognise excellence in creative pursuits and signal QUT\'s intention to attract the best students to the creative arts discipline. In addition to the financ', 'Up to AUD $20000', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-excellence-scholarship-creative-arts', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'QUT Postgraduate Research Award (QUTPRA)', 'We are building research excellence by supporting students of exceptional research potential with QUTPRAs. The number of QUTPRAs offered varies from year to year.', 'A living allowance for three years, indexed annually ($27,596 in 2019). The scholarship is tax exempt for full-time students, and can be used to support living costs.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-postgraduate-research-award-qutpra', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'QUT and GoStralia! PhD Scholarship', 'Four scholarships are available for German applicants wishing to study in Science or Engineering', 'AUD $33637/year', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-and-gostralia!-phd-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'QUT-CSIRO PhD Scholarship in Deep Learning for Hyperspectral Image Classification', 'Hyperspectral imaging is one of the rapidly growing domains in remote sensing primarily due to the breadth of applications on a variety of areas, from plant disease detection to object tracking. For example, hyperspectral imaging provides an opportun', 'A scholarship between $37,000 and $40,000 per year for 3 years (consisting of a base stipend of $27,000 and a top-up between $10,000 and $13,000) with a possible extension of 6 months. Up to $5,000 per year for project costs (to be agreed between CSI', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-csiro-phd-scholarship-in-deep-learning-for-hyperspectral-image-classification', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Research Training Program (RTP) Stipend Scholarship', 'A scholarship for future postgraduate research students in any faculty.', 'AUD $38310/year', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/research-training-program-stipend', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Senex Energy Learning Potential Fund Scholarships', 'The Learning Potential Fund provides support through scholarships and bursaries to students in financial need. The Senex Energy Learning Potential Fund Scholarship was established by Senex Energy to encourage disadvantaged and low-income students fro', 'Up to AUD $5000 — a scholarship valued at $5,000 for one year paid in two installments of $2,500 each.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/senex-energy-learning-potential-fund-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Shaping the future of mobility in rural and remote regions (PhD scholarship)', 'Headquartered at the Queensland University of Technology (QUT), AVR3 is a pioneering research hub dedicated to advancing automated vehicle (AV) technologies specifically tailored for the unique challenges of rural, regional, and remote Australian roa', 'AUD $41555/year — You\'ll receive a stipend of $41,555 per annum for a maximum duration of 3.5 years while undertaking a QUT PhD (1.75 years for MPhil). The duration includes an extension of up to 6 months (PhD) or 3 months (MPhil) if approved for you', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/shaping-the-future-of-mobility-in-rural-and-remote-regions-phd-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Sir John Pidgeon Learning Potential Fund Scholarship', 'The Sir John Pidgeon Learning Potential Fund Scholarship was established by Ms Liz Pidgeon and Mr Graeme Wikman as a tribute to Sir John Pidgeon and to encourage disadvantaged and low-income students to undertake the Bachelor of Urban Development (Ho', 'Up to AUD $5000 — a scholarship valued at $5,000 for one year, paid in two instalments of $2,500 each.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/sir-john-pidgeon-learning-potential-fund-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'System-Level Multiphase Flow and Bubble Transport for Efficient Electrochemical Hydrogen Production', 'We are seeking a PhD candidate to investigate system-level multiphase flow processes in electrochemical hydrogen production. The project will focus on how operating conditions, porous transport layers, electrode properties, and gas bubble transport i', 'AUD $37010/year', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/system-level-multiphase-flow-and-bubble-transport-for-efficient-electrochemical-hydrogen-production', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'The Noel and Geraldine Whittaker Learning Potential Fund Scholarship', 'The Noel and Geraldine Whittaker Learning Potential Fund Scholarship was established to encourage disadvantaged and low-income students to study and undergraduate degree in the faculty of their choice at QUT.', 'Up to AUD $5000 — a scholarship valued at $5,000 for one year paid in two instalments of $2,500 each.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/the-noel-and-geraldine-whittaker-learning-potential-fund-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Tuition Fee Sponsorship (TFS) for research students', 'A sponsorship to help international student pay tuition fees.', 'See scholarship details', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/tuition-fee-sponsorship-tfs-for-research-students', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Understand and manipulate quantum geometry in kagome metals (PhD scholarship)', 'This PhD project will investigate quantum geometry-driven electronic transport in kagome lattices as a pathway beyond the scaling limits of conventional silicon electronics. By engineering crystal symmetry and magnetic order through controlled chemic', 'AUD $40000/year — You\'ll receive a stipend of $40,000 per annum for a maximum duration of 3.5 years while undertaking a QUT PhD. The duration includes an extension of up to six months if approved for your candidature. This is the full-time, tax exemp', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/understand-and-manipulate-quantum-geometry-in-kagome-metals-phd-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'Using Systems Engineering to Model Neuropathic Pain (PhD Scholarship)', 'Neuropathic pain effects "1 in every 10 adults over the age of 30". The treatments available for neuropathic pain can at best be described as having "moderate efficacy". Due to the nature of neuropathic pain, the ability to scientifically study and u', 'AUD $32500/year', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/using-systems-engineering-to-model-neuropathic-pain-phd-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 13, 'VIED PhD Scholarship', 'QUT is working with the Vietnam Ministry of Education and Training (MOET) through the Vietnam International Education Development (VIED) Office.', 'a full scholarship covering your tuition fees and living expenses for the duration of your three-year PhD.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/project-911-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 174, 'Browse CQUniversity Scholarships', 'We believe a quality education can be for everyone – regardless of background, location, or life circumstances. That’s why we offer a variety of scholarships and bursaries to cater for all student needs. This can include financial support to assist w', 'See scholarship details', 'https://www.cqu.edu.au/study/prepare/scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 174, 'CQUniversity ASEAN Student Scholarship', 'The CQUniversity ASEAN Student Scholarship is a highly competitive scholarship offering 50 per cent off tuition fees for eligible undergraduate, postgraduate coursework and research courses at CQUniversity Australia. This scholarship is limited and a', '50% off tuition fees', 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1271035/asean-student-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 174, 'Indonesia Student Scholarship', 'The Indonesia Student Scholarship supports Indonesian students in pursuing their study ambitions in Australia. By offering 50 per cent off tuition fees, this scholarship helps you focus on what matters most - achieving academic success and building a', '50% off tuition fees // Duration of course', 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1273751/indonesia-student-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 174, 'International Alumni Scholarship', 'The International Alumni Scholarship offers eligible international students the opportunity to continue their academic journey at CQUniversity Australia. Designed to support recent graduates, this scholarship provides a 15 per cent reduction in tuiti', '15 percent reduction in tuition fees for the duration of the course.', 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1253043/international-alumni-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 174, 'International Merit Scholarship', 'The International Merit Scholarship is available to all new international students who plan to enrol in undergraduate, postgraduate coursework, research, or packaged academic courses at any campus or online.', 'Valued at up to 25% of your course fees, this scholarship recognises strong academic performance and supports students committed to achieving excellence in their studies.', 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/745776/international-merit-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 174, 'Live, Earn and Learn Scholarship', 'The Live, Earn and Learn Scholarship is designed specifically for international students who have received an offer to study at our Rockhampton North campus.  Through this scholarship, you can excel academically while building practical experience in', '35% of accommodation cost and paid part-time work.', 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1188590/live-earn-learn-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 174, 'Research Training Program (RTP) Stipend Scholarship (Research)', 'RTP Stipend Scholarships are funded by the Australian Government. They provide funding allocated to students to assist with their living costs while undertaking a research higher degree.', 'Up to AUD $114000', 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/745610/research-training-program-rtp-stipend-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 174, 'Southeast Asia Excellence Scholarship', 'The Southeast Asia Excellence Scholarship offers a 25% course fee reduction to offshore international students from Southeast Asian countries.  It supports greater diversity by encouraging students from the region to pursue their studies in an inclus', '25% for new students', 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1247065/southeast-asia-excellence-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 176, 'Australian Government Research Training Program', 'The Commonwealth Governments Research Training Program (RTP) provides funding to universities to support the research training of both domestic and international higher degree research (HDR) candidates. The funding provided through the RTP offers the', 'AUD $35656/year — RTP Stipends are provided to assist with candidates’ general living costs and do not cover program tuition fees.', 'https://www.griffith.edu.au/research-study/scholarships/au-gov-research-training-program', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 176, 'Griffith International Scholarship for Griffith College Diploma to Degree (following completion of a Griffith College diploma)', 'Our Griffith College Diploma to Degree Scholarship rewards outstanding Griffith College Diploma graduates who are articulating into an undergraduate degree program at Griffith University.', '$3,000', 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/griffith-college-diploma-degree', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 176, 'Griffith University International Postgraduate Research Scholarship', 'Griffith University awards Griffith University International Postgraduate Research Scholarships (GUIPRS) via a competitive application process to candidates commencing or enrolled in a Higher Degree Research (HDR) program. The fee offset provided thr', 'Covers tuition fees for up to three and a half years for doctoral candidates and up to two years for research masters candidates.', 'https://www.griffith.edu.au/research-study/scholarships/guiprs', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 176, 'International Academic Merit Scholarship', 'Our International Academic Merit Scholarship recognises international students with strong academic results applying for undergraduate and postgraduate coursework programs at Griffith University.', '20% of tuition fees', 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/international-academic-merit-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 176, 'John Willett International Scholarship', 'The founding Vice Chancellor of Griffith University, Professor John Willett (1922 - 1993) is remembered by many people throughout Australia as an academic and organisation builder of insight, innovation and drive. In memory of Professor Willett\'s wor', '50% of tuition fees', 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/john-willett-international-endowed-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 176, 'Vice Chancellor\'s International Scholarship', 'Our Vice Chancellor\'s International Scholarship rewards exceptional international students applying for undergraduate and postgraduate coursework degree programs at Griffith University.', 'Valued at 50% of tuition fees.', 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/vice-chancellors-international-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 176, 'Vice-Chancellor\'s Academic Achievement Scholarship', 'Griffith offers these respected scholarships to outstanding students commencing their first-ever undergraduate degree in 2026. The Vice Chancellor\'s Academic Achievement Scholarships will be focused on excellence and will also consider the barriers t', 'Up to AUD $15000 — Maximum value of the scholarship is determined by the length of the undergraduate degree for which you are awarded, and is calculated at a rate of $625/10 CP. For example: $15,000 for a single degree (240 CP), $20,000 for a double ', 'https://www.griffith.edu.au/scholarships/scholarship-listings/vice-chancellors-academic-achievement-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 177, 'Incoming Study Abroad International Travel Grant - 2025', 'The University of Southern Queensland will offer grants to non-award international students commencing or continuing their enrolment in the Study Abroad program, in Trimester 1, Trimester 2 or Trimester 3 2025.', 'Up to AUD $2000', 'https://www.unisq.edu.au/scholarships/unisqi-incoming-study-abroad-international-travel-grant', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 177, 'International Student Support Scholarship - 2025', 'In 2025, the University of Southern Queensland (UniSQ) will offer scholarships to new international students studying on-campus, external or online. This scholarship is based on meeting the entry requirements for the program of study and maintaining ', 'Each scholarship will have a maximum value of 15% of the tuition fees for the duration of the approved award program and will be applied as a 15% reduction of the tuition fees. (Students are responsible for paying the remainder of the fees as per the', 'https://www.unisq.edu.au/scholarships/unisq-international-student-support-scholarship-2025', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 177, 'Predictive farming PhD Scholarship: improving risk management with AI-enhanced weather forecasts and crop models', 'This project will investigate artificial intelligence (AI) to improve weather forecasts and use crop models for making better farming decisions. The expected outcome is protocols for integrating AI-enhanced weather forecasts and crop models into farm', 'Up to AUD $47000 — Stipend of AUD $47,000 (2025 rate); A project expense and development package of up to $13,000 per annum.; Maximum period of tenure of an award is 4 years. Periods of study already undertaken towards the degree will be deducted fro', 'https://www.unisq.edu.au/scholarships/predictive-farming-phd-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 178, 'Alternative Study Path Scholarship', 'There’s more than one path to university. As an international student in Australia, you may be eligible for the Alternative Study Path Scholarship if you have completed studies onshore, or if you are in Australia and in the process of applying for a ', '15% of your total tuition costs', 'https://www.think.edu.au/studying-with-us/fees-scholarships/scholarships/international-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 178, 'Americas & European Health Scholarship', 'Does your passport say you re from Latin America or Europe? If so, you have the chance to take advantage of this scholarship, which gives you 15 percent off your total course tuition when you start studying Health at Think Education.', '15% of your total tuition costs', 'https://www.think.edu.au/studying-with-us/fees-scholarships/scholarships/international-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 178, 'Asia & Greater China Health Merit Scholarship', 'If you are from Asia or Greater China and are planning to combine an English language course with one of our Health degrees, you have the opportunity to apply for this regional scholarship. It will cover 20 per cent of your total course tuition.', '20% of your total tuition costs', 'https://search.studyaustralia.gov.au/scholarship/asia-greater-china-health-merit-scholarship/5595f4e6d4ce3cb71571fd83ffc0f094', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
