INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 195, 'Academic Scholarship', 'Wesley’s Academic Scholarships are awarded to students who demonstrate academic excellence across a broad range of disciplines. This is determined by the results of an Edutest exam and following an interview.', 'Successful applicants will be sent a letter of offer via email. To formally accept, applicants must sign the letter of offer and pay a one-off confirmation fee of $1200 and Tuition Contribution fee of $2800. These fees are non-refundable and non-tran', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/076267b43129a628477cc4cafe0a88c9', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 195, 'Academic Scholarship', 'Wesley’s Academic Scholarships are awarded to students who demonstrate academic excellence across a broad range of disciplines. This is determined by the results of an Edutest exam and following an interview.', 'Successful applicants will be sent a letter of offer via email. To formally accept, applicants must sign the letter of offer and pay a one-off confirmation fee of $1200 and Tuition Contribution fee of $2800. These fees are non-refundable and non-tran', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/d448550b05450449341c6e029d151a33', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 195, 'Academic Scholarships', 'Wesley’s Academic Scholarships are awarded to students who demonstrate academic excellence across a broad range of disciplines. This is determined by the results of an Edutest exam and following an interview.', 'Successful applicants will be sent a letter of offer via email. To formally accept, applicants must sign the letter of offer and pay a one-off confirmation fee of $1200 and Tuition Contribution fee of $2800. These fees are non-refundable and non-tran', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships/0d9e7ac790b6683098548d88033fd082', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 195, 'Elsternwick Lanuage Scholarship', 'The Language Scholarships are awarded to new students who demonstrate strong commitment to, and passion for, learning and developing proficiency in languages. They are only available at Wesley College’s Elsternwick Campus', 'Successful applicants will receive a letter of offer via email. To accept an Elsternwick Language Scholarship, applicants pay a one-off Confirmation Fee of $1200 and Tuition Contribution Fee of $2,800. These fees are non-refundable and non-transferra', 'https://search.studyaustralia.gov.au/scholarship/elsternwick-lanuage-scholarship/82291db76a94492599a41330fd80d3ea', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 195, 'Elsternwick Music Scholarship', 'Elsternwick Music Scholarships are awarded to new students who demonstrate strong commitment to and passion for music. Elsternwick Music Scholarships are only available at Wesley College’s Elsternwick Campus.', 'Successful applicants will receive a letter of offer via email. To accept an Elsternwick Music Scholarship, applicants pay a one-off Confirmation Fee of $1200 and Tuition Contribution Fee of $2,800. These fees are non-refundable and non-transferrable', 'https://search.studyaustralia.gov.au/scholarship/elsternwick-music-scholarship/8f4d29e8ab83cecc46a0e6ed7c6df908', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 195, 'General Excellence Scholarship', 'General Excellence Scholarships are awarded to students who demonstrate a high level of academic achievement as well as achievement in one or more of the following; sport (state or national standard), music, performance, art, leadership or community ', 'Successful applicants will be sent a letter of offer via email. To formally accept, applicants pay a one-off confirmation fee of $1200 and Tuition Contribution fee of $2800. These fees are non-refundable and non-transferrable.', 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarship/35013457c8bbd7b6459fb63e1b43b6b4', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
