INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 195, 'Glen Waverley Middle School Expansion Scholarship', 'Following the recent expansion and redevelopment of the campus and the Middle School, Wesley\'s Glen Waverley Campus is pleased to offer the Glen Waverley Middle School Expansion Scholarship. This scholarship is awarded to new students entering the mi', 'Successful applicants will be sent a letter of offer via email. To formally accept, applicants pay a one-off confirmation fee of $1200 and Tuition Contribution fee of $2800. These fees are non-refundable and non-transferrable.', 'https://search.studyaustralia.gov.au/scholarship/glen-waverley-middle-school-expansion-scholarship/97fa8301aec3edd2a027364a95f1230b', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
