INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 297, 'Year 7 Scholarships for Excellence', '', 'AUD $1000/year — Remission of tuition fees and allowances for books and basic uniform.', 'https://search.studyaustralia.gov.au/scholarship/year-7-scholarships-for-excellence/b109bd155ba3b8a402e373d84fe08a81', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 304, 'Academic and Music Excellence Scholarships', '', 'Scholarships are awarded following the results of the ACER Scholarship test sat in February in the year of eligibility. There are no set quotas. Scholarships are awarded dependent upon merit.', 'https://search.studyaustralia.gov.au/scholarship/academic-and-music-excellence-scholarships/6024e1cdd3dceb0c861363e96d4380ac', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 16, 'China Scholarship Council Research Scholarships', 'The China Scholarship Council Research Scholarship is a collaborative arrangement that provides support to candidates from the People\'s Republic of China to undertake a PhD at Western Sydney University. We encourage applications from candidates in al', '"Western Sydney University will provide a tuition fee waiver for successful applicants for a maximum period of up to 48 months.\r\n"', 'https://www.westernsydney.edu.au/schools/grs/scholarships/china_scholarship_council_research_scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 16, 'Lion Dr William Chiu Scholarship', 'Dr William Chiu established a program at Western Sydney University for young people to gain a deeper understanding of Chinese language and culture. As well as promoting cross-cultural understanding, his gift allowed the University to provide opportun', 'AUD $7500/year — $7,500 per year for the duration of the degree.', 'https://www.westernsydney.edu.au/opportunities/scholarships/all_uws_scholarships/LIONCHIU', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 16, 'Research Scholarships', 'Western Sydney University supports higher degree research candidates with a range of scholarship opportunities. Research scholarships are released periodically, and each type of scholarship has specific application dates, eligibility criteria and con', 'Up to AUD $105564', 'https://www.westernsydney.edu.au/schools/grs/scholarships/main_round_scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 306, 'Alphacrucis Higher Degree Scholarship', 'This scholarship provides financial support, in the form of a fee subsidy, to students undertaking HDR research at AC. This is a merit-based scholarship for students with a demonstrated record of academic excellence.', 'See scholarship details', 'https://www.ac.edu.au/research/higher-degree-research/funding-opportunities/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 306, 'Financial assistance scholarships', 'Enrolled HDR students facing financial difficulties may be eligible for a financial assistance scholarship, in the form of a fee subsidy. Students can apply at any time during their enrolment, typically for up to 2 semesters of financial support.', 'See scholarship details', 'https://www.ac.edu.au/research/higher-degree-research/funding-opportunities/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 306, 'HDR Travel Grant', 'This grant is available to assist HDR candidates with travel costs (up to $1500) associated with research-related activities that will enhance their thesis.', 'See scholarship details', 'https://www.ac.edu.au/research/hdr/funding-opportunities/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 306, 'Mission Australia Chaplaincy Research Scholarship', 'This scholarship is funded by a partnership between AC and Mission Australia, for qualitative research on community chaplaincy in Australia. The scholarship provides up to $60,000 of financial support for PhD students over 3 years (full-time).', 'AUD $60000/year', 'https://www.ac.edu.au/research/higher-degree-research/funding-opportunities/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 306, 'Thesis write-up scholarship', 'The purpose of this scholarship is to assist HDR candidates to write-up and submit their theses for examination. Typically the scholarship takes the form of a full tuition subsidy for one semester, for students who are in the final stage of completin', 'See scholarship details', 'https://www.ac.edu.au/research/hdr/funding-opportunities/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 309, 'Academic Scholarship Year 5', '', 'See scholarship details', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship-year-5/72a634c2d4023e853a2725e311783f96', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 309, 'Academic Scholarship Year 7', '', 'Partial remission of tuition fees for the duration of enrolment.', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship-year-7/ccf89b5e4a67674c9069f8001c856503', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 309, 'Cooerwull General Excellence Scholarship', '', 'The scholarship tenure applies up to the completion of schooling (Year 12).\r\n\r\nAwarded for academic excellence and potential, achievement and involvement in co-curricular activities, citizenship and leadership.', 'https://search.studyaustralia.gov.au/scholarship/cooerwull-general-excellence-scholarship/74ccc5b642dc71cf92994ba61498dbfd', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 309, 'Music Scholarship', '', 'Partial remission of tuition fees and full remission of music tuition fees for the chief instrument for the duration of enrolment.', 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/aa4b5133a9f23ec74c6f4456f2a5ace6', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 309, 'VCE Excellence Scholarship', '', 'Partial remission of tuition fees for the duration of enrolment.', 'https://search.studyaustralia.gov.au/scholarship/vce-excellence-scholarship/280f879edfda59a95929cf498300360e', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 310, 'Academic Scholarships', '', 'The School offers part remission of tuition fees for academically gifted students. The process involves an examination plus an interview with the Headmaster for short-listed candidates.', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships/af9761d6a7048d446ad7076e2111f838', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 310, 'Hone Scholarship for Music', '', 'The Hone Scholarship comprises full remission of academic tuition fees and music tuition fees for one instrument. Students must sit the academic examination in February as well as attend an audition. Those short-listed will be contacted by the Direct', 'https://search.studyaustralia.gov.au/scholarship/hone-scholarship-for-music/39c00e3e54a055207c29caff30258bdf', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 311, 'Principal\'s Scholarship', '', 'Variable', 'https://search.studyaustralia.gov.au/scholarship/principals-scholarship/7b01deab415c2906567e42e01fe911dc', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
