INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 311, 'Year 7 Academic Scholarship', '', 'Covers 50% of tuition fees for 2 years.', 'https://search.studyaustralia.gov.au/scholarship/year-7-academic-scholarship/f9b8188e292c25c80f049d7b07b57fc5', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 311, 'Year 9-12 Academic Scholarship (full)', '', 'Covers tuition fees for 4 years.', 'https://search.studyaustralia.gov.au/scholarship/year-9-12-academic-scholarship-full/eb3b2e6f17276e5ff751cd59a41a76b5', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 311, 'Year 9-12 Academic Scholarship (half)', '', 'Covers up to 50% of tuition fees for 4 years.', 'https://search.studyaustralia.gov.au/scholarship/year-9-12-academic-scholarship-half/06286a61d468da679bd21b53843bc9fa', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 317, 'INTERNATIONAL STUDENTS’ EQUITY BURSARY', 'International students can access a discount in course fees of up to 20%', 'See scholarship details', 'https://chc.edu.au/scholarships/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 317, 'LIFELONG LEARNING BURSARY', 'CHC values lifelong learning and is providing scholarships to selected alumni who have been accepted to commence an eligible CHC course in Semester 1 or Semester 2, 2025.\r\n\r\nThe scholarship is available to domestic students and international students', 'The scholarship is valued at a 10% reduction in the applicable tuition fees for the duration of enrolment in the course (domestic students) or for the standard full-time duration of the course (international students).', 'https://chc.edu.au/scholarships/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 318, 'Diploma and Pre-Masters Program International Student Award', 'If you start a Diploma or Pre-Masters Program in 2025 or 2026, you could be eligible to receive a 15% contribution towards your tuition fees, for the duration of your studies at UNSW.', '15% contribution towards your tuition fees, for the duration of your studies at UNSW', 'https://www.unswcollege.edu.au/content/dam/pdfs/unsw-college/international-student-award-diploma-pre-masters.pdf', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 318, 'Foundation Studies International Student Award', 'If you start a Foundation Studies program from 1 July 2025 or in 2026, you could be eligible to receive a 15% contribution towards your tuition fees, for the duration of your studies at UNSW.', '15% contribution towards your tuition fees, for the duration of your studies at UNSW.', 'https://www.unswcollege.edu.au/content/dam/pdfs/unsw-college/international-student-award-foundation-studies.pdf', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 319, 'Academic Scholarship', 'Only Australian citizen and Permanent Residents are eligible for the Scholarship.', 'See scholarship details', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/c48bbb91d90a326830a22df6c9b5b974', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
