INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 17, 'International Master of Physiotherapy Scholarship', 'The University of Notre Dame Australia (University) offers the International Master of Physiotherapy Scholarship to provide tuition assistance to international students enrolling in the Master of Physiotherapy program at the University of Notre Dame ', 'The value of the Scholarship is $7,500 fee reduction of annual indicative tuition fees for the full duration of the \r\nprogram.', 'https://www.notredame.edu.au/__data/assets/pdf_file/0037/437698/International-Master-of-Physiotherapy-Scholarship-Conditions.pdf', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 17, 'Notre Dame Australia International Business and Commerce Scholarship', 'The University of Notre Dame Australia (University) offers the International Business and Commerce scholarship to provide tuition assistance to international students enrolling in Undergraduate Business and Commerce programs at the University of Notr', 'The value of the Scholarship is $10,000 fee reduction of annual indicative tuition fees for the full duration of the program.', 'https://www.notredame.edu.au/__data/assets/pdf_file/0032/339944/NDA-International-Business-and-Commerce-Undergraduate-Scholarship-T-and-Cs.pdf', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 17, 'Notre Dame Australia International Scholarship Master of Social Work (Qualifying).', 'The University of Notre Dame Australia (University) offers the International Scholarship Master of Social Work \r\n(Qualifying) to provide tuition assistance to international students enrolling in the Master of Social Work \r\n(Qualifying).', 'The value of the Scholarship is 20 percent (20%) of annual indicative tuition fees for the full duration of the \r\nprogram. The Scholarship is awarded as a partial tuition fee waiver and does not cover costs such as living \r\nexpenses, accommodation, t', 'https://www.notredame.edu.au/__data/assets/pdf_file/0039/746976/TCs-Mof-Social-Work-Conditions-2026-updated.pdf', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 17, 'Notre Dame Australia International Welcome Scholarship (Undergraduate)', 'The University of Notre Dame Australia (University) offers the International Welcome Scholarship to provide tuition assistance to international students enrolling in Undergraduate programs at Notre Dame, excluding the Bachelor of Nursing.', 'The value of the Scholarship is 25 percent (25%) of annual indicative tuition fees for the full duration of the program.', 'https://www.notredame.edu.au/__data/assets/pdf_file/0029/258941/NDA-International-Welcome-Scholarship-Undergraduate-2022-T-and-Cs.pdf', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 17, 'Notre Dame Australia International Welcome Scholarship for Nursing', 'The University of Notre Dame Australia (University) offers the International Welcome Scholarship for Nursing\r\nto provide tuition assistance to international students enrolling in the Bachelor of Nursing program at Notre \r\nDame.', 'The value of the Scholarship is 20 percent (20%) of annual indicative tuition fees for the full duration of the \r\nprogram.', 'https://www.notredame.edu.au/__data/assets/pdf_file/0032/258944/NDA-International-Welcome-Scholarship-Nursing-2022-T-and-Cs.pdf', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
