INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 326, 'Access Scholarship (Enrolled Students Only)', 'The Kangan Institute Access Scholarship has been designed to provide opportunities for access to education. The scholarship is available to domestic and international students enrolled in any course at Kangan Institute. It is intended to alleviate fi', 'Up to AUD $1000 — Domestic Students: up to $500 per scholarship\r\nInternational Students: up to $1,000 per scholarship', 'https://www.kangan.edu.au/study-with-us/prospective-students/scholarships/access-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
