INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 18, 'Preparing for Success Pathway Scholarship', 'The Preparing for Success Pathway Scholarship which will assist students transition into their chosen degree. The scholarship supports students through an initial preparatory program (Preparing for Success Program) where the student gains skills requ', 'Up to AUD $2500', 'https://www.scu.edu.au/scholarships/preparing-for-success-pathway-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 18, 'Ralph Barclay Braun Memorial Scholarship', 'The Ralph Barclay Braun Memorial Scholarship is awarded to students who have a formal acceptance into the Bachelor of Science with Honours. Students must be based, full-time, at the National Marine Science Centre (NMSC) — and have a supervisor who is', 'Up to AUD $5000 — $5000', 'https://www.scu.edu.au/scholarships/ralph-barclay-braun-memorial-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 18, 'SCU Rugby Gold Rats Scholarship', 'The University’s Rugby Club, known as the Gold Rats, marked its 50th season in 2019. The club offers scholarships to students studying in a degree at the Lismore campus.', 'Up to AUD $3000', 'https://www.scu.edu.au/scholarships/southern-cross-university-rugby-gold-rats-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 18, 'Student Opportunities Fund', 'Southern Cross University is committed to helping provide exceptional students with exceptional opportunities to broaden their professional networks and opportunities. The Southern Cross Student Opportunities Fund will provide students with the oppor', 'Up to AUD $7500', 'https://www.scu.edu.au/current-students/opportunities/student-opportunities-fund/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
