INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 348, 'MIT Graduate Progression Scholarship', 'The Graduate Progression Scholarship is available to international students who have completed a Bachelor\'s or Master\'s degree at MIT and are commencing a Higher Degree by Research at MIT in 2025. Eligible students will receive a 10% tuition fee redu', '10% tuition fee reduction per trimester, including the thesis component.', 'https://www.mit.edu.au/study-with-us/scholarships/graduate-progression-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
