INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 349, 'International Student Scholarship - Bangladesh, India, Pakistan and Sri Lanka', 'Are you an international student and currently in Bangladesh, India, Pakistan or Sri Lanka? Apply now to study at SIBT and receive a $1,000 scholarship to assist with your start.', 'Up to AUD $1000 — $1,000 off your program fees for international students in Bangladesh, India, Pakistan or Sri Lanka.', 'https://sibt.nsw.edu.au/essential-information/scholarships/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 349, 'International Student Scholarship - China, Japan, South Korea, all countries in Southeast Asia, and Australia', 'This scholarship offer is valid when students apply from China, Japan, South Korea, and all countries in Southeast Asia, and Australia', 'Up to AUD $3000 — $3,000 off your program fees for international students.', 'https://sibt.nsw.edu.au/essential-information/scholarships/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 349, 'International Student Scholarship - Nepal', 'Are you an international student currently in Nepal? Apply now to study at SIBT and receive a $5,000 scholarship to assist with your start.', 'Up to AUD $5000 — $5,000 off your program fees for international students in Nepal.', 'https://sibt.nsw.edu.au/essential-information/scholarships/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 352, 'Deakin College International Scholarships', 'Deakin College is committed to helping you achieve your goals by offering tuition fee scholarships to selected international students.', 'The scholarship is valued between 10%-20% of your Foundation and/or diploma program tuition fees', 'https://www.deakincollege.edu.au/how-apply/scholarships/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 352, 'Deakin College Loyalty Scholarships', 'Deakin College is committed to helping you achieve your goals by rewarding new international students from Africa with a Deakin College Loyalty Scholarship.', 'The scholarship is valued at 10% of your Foundation and/or Diploma program tuition fees', 'https://www.deakincollege.edu.au/how-apply/scholarships/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 352, 'Navitas Family Bursaries', '-', 'The bursary is equivalent to 10% of the tuition fee for up to 8 units of study within one program only with a Navitas member institution. The bursary does not apply to additional units or repeat units that may also be undertaken. It excludes mixed En', 'https://www.deakincollege.edu.au/how-apply/scholarships/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 19, 'Australia Awards', 'Australia Awards are prestigious international scholarships and fellowships funded by the Australian Government. The Awards offer the next generation of global leaders an opportunity to undertake study, research and professional development.', 'See scholarship details', 'https://www.usc.edu.au/study/life-at-unisc/study-overseas/australia-awards', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 19, 'English Excellence Scholarship', 'Please Contact University of the Sunshine Coast Australia for more information.', 'The English Excellence Scholarship is a 20% tuition fee reduction that is awarded to commencing international students in 2025 who have achieved higher than required results in a recognised English language proficiency test.', 'https://www.usc.edu.au/international/programs-and-fees/international-scholarships#tab-2025-unisc-international-scholarships-for-new-students_37511', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 19, 'International Bright Futures Scholarship', 'The International Bright Futures Scholarship is a 20% tuition fee reduction that is awarded to commencing international students in 2025 who enrol in a newly launched UniSC program (i.e. Bachelor of Education Studies (Early Childhood), Master of Busi', '20% tuition fee reduction', 'https://www.usc.edu.au/international/programs-and-fees/international-scholarships#tab-2025-unisc-international-scholarships-for-new-students_98937', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 19, 'International Student Scholarship', 'Please Contact University of the Sunshine Coast Australia for more information.', 'The International Student Scholarship is a 15% tuition fee reduction offered to commencing international students in 2025.', 'https://www.usc.edu.au/international/programs-and-fees/international-scholarships#tab-2025-unisc-international-scholarships-for-new-students_37511', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 19, 'National Centre for Timber Durability and Design Life Scholarship', 'The newly established Australian National Centre for Timber Durability and Design Life is seeking highly motivated students interested in pursuing PhDs in the area of wood deterioration and its prevention. The Centre is based in Brisbane Australia an', 'Annual stipend / If the successful recipient is an International student the scholarship will include tuition fees and Overseas Student Health Cover (single cover)', 'https://www.usc.edu.au/study/scholarships/research-scholarships/national-centre-for-timber-durability-and-design-life-scholarship', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
