INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 464, 'Bland Family Scholarship', 'This scholarship is available to any new or returning domestic or international student who enrols in our Bachelor of Business with a major in accounting or in our Master of Business Administration.', 'Up to AUD $8700', 'https://www.avondale.edu.au/scholarship/bland-family-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 464, 'Driscoll Pacific Islands Student Scholarship', 'The Driscoll Pacific Islands Student Scholarship has been made possible as a result of the generosity of Linda and William Driscoll, both alumni of Avondale University. They both served for many years in the Pacific Islands. They desired to assist st', 'The scholarship is worth $7000. The recipient receives $3500 in their first semester and $3500 in their second.', 'https://www.avondale.edu.au/scholarship/driscoll-pacific-islands-student-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 464, 'International Student Scholarship', 'Please contact Avondale University for further information.', 'The scholarships are worth $8500. Each recipient receives $7000 ($3500 per semester or equivalent) in their first year of study and &1500 ($750 per semester or equivalent) in their second. Avondale will apply the money to each recipient’s general or ', 'https://www.avondale.edu.au/scholarship/international-student-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 464, 'King Family Scholarship', 'The King Family Scholarship encourages students in a degree course who want to sing with vocal ensembles Avondale Singers and The Promise but who are not vocal performance majors to improve their skills through private tuition.', 'Up to two scholarships valued at $500 per student per semester.', 'https://www.avondale.edu.au/scholarship/king-family-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
