INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 464, 'Young Scientist Scholarship', 'Avondale University offers the Young Scientist Scholarship to help young adults consider a career as a science teacher or scientist.', 'The scholarship is worth $2000. The successful applicant receives $1000 per semester in their first year of study. Avondale will apply the money to the recipient\'s tuition account. The money comes from the Young Scientist Scholarship Reserve, which t', 'https://www.avondale.edu.au/scholarship/young-scientist-scholarship/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
