INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 52, 'Alumni Scholarship', 'We’re committed to supporting our graduates with further opportunities to advance their careers and find work they love. That’s why we offer alumni scholarships to encourage you on your continuing journey through education.', '25% off tuition fees', 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/alumni-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 52, 'Alumni Scholarship', 'If you are an Alumni of BMIHMS, Torrens University Australia, Think Education or from a Laureate University you are entitled to a 25% scholarship.', 'See scholarship details', 'https://www.bluemountains.edu.au/apply/scholarships-available/', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) VALUES (1, 0, 52, 'Career Enhancement scholarship', 'Connection to industry is one of our most important philosophies, and we take it very seriously. It’s part of our DNA. If you’re working in a relevant field and want to upgrade your qualifications, we’re here to help with a 15% tuition fee reduction ', '15% off tuition fees', 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/industry-scholarships', '2026-11-02 16:20:46', '2026-11-02 16:20:46');
